CANCEL_WORDS = ["cancel", "cancell", "disput", "delete", "hold"]

async def decide(request, kit):
    text = request
    lower = text.lower()

    def clean_number(value):
        if isinstance(value, float):
            whole = int(value)
            if value == whole:
                return whole
        return value

    def find_candidates(pattern):
        found = kit.find(pattern, text)
        return [x.upper() for x in found]

    def find_positions(phrases):
        positions = []
        for phrase in phrases:
            start = 0
            while True:
                pos = lower.find(phrase, start)
                if pos == -1:
                    break
                positions.append(pos)
                start = pos + 1
        return positions

    async def choose_target(cands, phrases, kind):
        if len(cands) == 1:
            return cands[0]

        positions = find_positions(phrases)
        scored = []

        if len(positions) > 0:
            for cand in cands:
                cand_low = cand.lower()
                start = 0
                best = None
                while True:
                    pos = lower.find(cand_low, start)
                    if pos == -1:
                        break
                    dist = min([abs(pos - p) for p in positions])
                    if best is None or dist < best:
                        best = dist
                    start = pos + 1
                if best is not None:
                    scored.append((best, cand))

            if len(scored) > 0:
                scored = sorted(scored, key=lambda item: item[0])
                if len(scored) == 1 or scored[0][0] < scored[1][0]:
                    return scored[0][1]

        criteria = {}
