def has_word(text, word):
    start = 0
    while True:
        i = text.find(word, start)
        if i == -1:
            return False
        before = ' ' if i == 0 else text[i - 1]
        after_index = i + len(word)
        after = ' ' if after_index >= len(text) else text[after_index]
        if not before.isalpha() and not after.isalpha():
            return True
        start = i + 1


def normalize_id(raw, prefix):
    digits = ''
    for ch in raw:
        if ch >= '0' and ch <= '9':
            digits += ch
    if digits == '':
        return None
    if len(digits) < 3:
        digits = digits.zfill(3)
    return prefix + digits


def collect_ids(text, kind, kit):
    if kind == 'doc':
        raw = kit.find('doc-\\d+|(?:document|doc)\\s+\\d+', text)
        prefix = 'DOC-'
    else:
        raw = kit.find('inv-\\d+|(?:invoice|inv)\\s+\\d+', text)
        prefix = 'INV-'
    ids = []
    for item in raw:
        cid = normalize_id(item, prefix)
        if cid is not None and cid not in ids:
            ids.append(cid)
    return ids


