        return None
    if choice in candidates and confidence >= 0.5:
        return choice
    return None


async def decide(request, kit):
    if not isinstance(request, str):
        return {"handoff": "Unsupported request."}

    text = request.lower()

    if has_any(text, BLOCK_PHRASES):
        return {"handoff": "This request is out of scope."}

    record = is_record_request(text)
    pay = is_pay_request(text)

    if record and pay:
        return {"handoff": "This request mixes record and payment actions."}

    if not record and not pay:
        return {"handoff": "This request is not a ledger action."}

    intent = "record" if record else "pay"
    candidates = collect_candidates(kit, request, intent)

    if len(candidates) == 0:
        if intent == "record":
            return {"handoff": "No document id was found."}
        return {"handoff": "No invoice id was found."}

    target = await choose_target(kit, request, intent, candidates)
    if target is None:
        if intent == "record":
            return {"handoff": "I cannot identify the document confidently."}
        return {"handoff": "I cannot identify the invoice confidently."}

    if intent == "record":
        parsed = await kit.procedure("parse_invoice", doc_id=target)
        record_data = unwrap_record(parsed)
        if record_data is None:
            fallback = kit.read("read_document", doc_id=target)
            record_data = unwrap_record(fallback)
        if record_data is None:
            return {"handoff": "Could not parse the document."}
        return {
            "action": "record_invoice",
            "arguments": record_data,
            "reply": "Recording the invoice.",
        }

    due = await kit.procedure("amount_payable", invoice_id=target)
    invoice_id = find_value(due, ID_KEYS)
    amount = find_value(due, AMOUNT_KEYS)
    pay_on = find_value(due, DATE_KEYS)

    if invoice_id is None:
        invoice_id = target

    if amount is None or pay_on is None:
        info = kit.read("read_invoice", invoice_id=target)
        if amount is None:
            amount = find_value(info, AMOUNT_KEYS)
        if pay_on is None:
            pay_on = find_value(info, DATE_KEYS)
        if invoice_id == target:
            found_id = find_value(info, ID_KEYS)
            if found_id is not None:
                invoice_id = found_id

    amount_value = normalize_number(amount)
    if amount_value is None or pay_on is None:
        return {"handoff": "Could not determine the payable amount."}

    return {
        "action": "schedule_payment",
        "arguments": {
            "invoice_id": str(invoice_id),
            "amount_usd": amount_value,
            "pay_on": str(pay_on),
        },
        "reply": "Scheduling the payment.",
    }
