    chosen = trip_candidates[0]
    if len(trip_candidates) > 1:
        trip_answer = answers["trip_id"]
        chosen = trip_answer["choice"]
        if chosen == NONE_NAME or chosen not in trip_candidates or trip_answer["confidence"] < CONFIDENCE_LIMIT:
            return {"handoff": "trip identity is ambiguous"}

    actual_trip_id = ""
    for variant in trip_variants(chosen):
        trip = kit.read("read_trip", trip_id=variant)
        if isinstance(trip, dict):
            if "trip_id" in trip:
                actual = str(trip["trip_id"])
            else:
                actual = variant
            if normalize_trip_id(actual) == normalize_trip_id(variant):
                actual_trip_id = actual
                break

    if actual_trip_id == "":
        return {"handoff": "trip not found"}

    total = await kit.procedure("reimbursable_total", trip_id=actual_trip_id)
    if not isinstance(total, dict) or "total_usd" not in total:
        return {"handoff": "could not compute claim total"}

    try:
        amount = round(float(total["total_usd"]), 2)
    except Exception:
        return {"handoff": "could not compute claim total"}

    return {
        "action": FILE_NAME,
        "arguments": {"trip_id": actual_trip_id, "amount_usd": amount},
        "reply": "Filed the claim for " + actual_trip_id + "."
