async def decide(request, kit):
    def has_phrase(text, phrases):
        for phrase in phrases:
            if phrase in text:
                return True
        return False

    def money_text(value):
        cents = int(round(float(value) * 100))
        whole = cents // 100
        frac = cents % 100
        if frac < 10:
            return str(whole) + ".0" + str(frac)
        return str(whole) + "." + str(frac)

    def digits_only(text):
        digits = ""
        for ch in text:
            if ch >= "0" and ch <= "9":
                digits = digits + ch
        return digits

    def add_matches(target, matches):
        for match in matches:
            digits = digits_only(match)
            if len(digits) == 3:
                trip_id = "T-" + digits
                if trip_id not in target:
                    target.append(trip_id)

    def load_trip(trip_id):
        attempts = []
        digits = digits_only(trip_id)
        if len(digits) == 3:
            attempts.append("T-" + digits)
            attempts.append(digits)
        else:
            attempts.append(trip_id)

        tried = []
        for candidate in attempts:
            if candidate in tried:
                continue
            tried.append(candidate)
            try:
                trip = kit.read("read_trip", trip_id=candidate)
            except Exception:
                trip = {"error": "exception"}
            if not (isinstance(trip, dict) and "error" in trip):
                return candidate, trip
        return "", {"error": "not found"}

    text = request.lower()

    if has_phrase(text, HANDOFF_PHRASES):
        return {"handoff": "This request is out of scope for claim filing."}

    file_mode = has_phrase(text, FILE_PHRASES)
    estimate_mode = has_phrase(text, ESTIMATE_PHRASES) and not file_mode

    if not file_mode and not estimate_mode:
        return {"handoff": "This is not a clear expense-claim filing request."}

    candidates = []
    add_matches(candidates, kit.find("t-[0-9]{3}", text))
    add_matches(candidates, kit.find("trip\\s*[0-9]{3}", text))

    if len(candidates) == 0:
        return {"handoff": "I couldn't identify a valid trip id."}

    trip_id = candidates[0]
    if len(candidates) > 1:
        state = {"request": request, "candidates": candidates}
        questions = {
            "trip": {
                "type": "choice",
                "instructions": "Choose the single trip id the user really wants the expense assistant to act on. If the user is asking about more than one trip, or no single trip is clearly the target, choose none.",
                "criteria": {}
            }
        }
        for candidate in candidates:
            questions["trip"]["criteria"][candidate] = "The user really wants trip " + candidate + "."
        questions["trip"]["criteria"]["none"] = "No single trip id is clearly requested."
        answer = await kit.ask(state, questions)
        choice = answer["trip"]["choice"]
        confidence = answer["trip"]["confidence"]
        if choice == "none" or confidence < 0.6 or choice not in candidates:
            return {"handoff": "I couldn't tell which trip you meant."}
        trip_id = choice

    resolved_trip_id, trip = load_trip(trip_id)
    if resolved_trip_id == "":
        return {"handoff": "I couldn't find that trip."}

    total = await kit.procedure("reimbursable_total", trip_id=resolved_trip_id)
    if not isinstance(total, dict) or "total_usd" not in total:
        return {"handoff": "I couldn't compute the reimbursable total."}

    amount = round(float(total["total_usd"]), 2)

    if estimate_mode:
        return {"reply": "The reimbursable total for " + resolved_trip_id + " is $" + money_text(amount) + "."}

    return {
        "action": "file_claim",
        "arguments": {"trip_id": resolved_trip_id, "amount_usd": amount},
        "reply": "Filed claim for " + resolved_trip_id + " for $" + money_text(amount) + "."
    }
