async def decide(request, kit):
    CONTEXT_WINDOW = 60

    def clean_number(value):
        if isinstance(value, float) and round(value) == value:
            return int(round(value))
        return value

    def select_target(candidates, text, kind):
        best = None
        best_score = None
        tie = False

        for candidate in candidates:
            pos = text.find(candidate)
            if pos < 0:
                continue

            start = pos - CONTEXT_WINDOW
            if start < 0:
                start = 0
            end = pos + len(candidate) + CONTEXT_WINDOW
            if end > len(text):
                end = len(text)

            ctx = text[start:end]
            score = 0

            if kind == "payment":
                if "SCHEDULE" in ctx:
                    score += 3
                if "SET UP" in ctx or "SETUP" in ctx:
                    score += 3
                if "PAYMENT" in ctx:
                    score += 1
            else:
                if "ENTER" in ctx:
                    score += 3
                if "RECORD" in ctx:
                    score += 3
                if "LEDGER" in ctx or "VENDOR INVOICE" in ctx:
                    score += 1

            if "ONLY" in ctx:
                score += 1
            if "DIFFERENT" in ctx or "NEEDS NOTHING" in ctx or "ALREADY HANDLED" in ctx:
                score -= 3

            if best is None or score > best_score:
                best = candidate
                best_score = score
                tie = False
            elif score == best_score:
                tie = True

        if best is None or best_score is None or best_score <= 0 or tie:
            return None
        return best

    text = request.upper()
    padded = " " + text + " "

    schedule_intent = (
        (" SCHEDULE " in padded or " SET UP " in padded or " SETUP " in padded)
        and " PAYMENT " in padded
    )
    record_intent = (
        (" ENTER " in padded or " RECORD " in padded)
