        return out

    def tail_digits(value):
        i = len(value) - 1
        while i >= 0 and value[i].isdigit():
            i -= 1
        if i == len(value) - 1:
            return value
        return value[i + 1:]

    def variants(raw):
        raw = raw.strip()
        out = []
        if raw.startswith("DOC-") or raw.startswith("INV-"):
            out.append(raw)
            bare = raw[4:]
            if bare not in out:
                out.append(bare)
            return out
        if raw.startswith("DOCUMENT"):
            bare = tail_digits(raw)
            if bare not in out:
                out.append(bare)
            if raw not in out:
                out.append(raw)
            return out
        if raw.startswith("INVOICE"):
            bare = tail_digits(raw)
            if bare not in out:
                out.append(bare)
            if raw not in out:
