]
STOP_PHRASES = ["how much", "been filed", "has my"]
CLAIM_PATTERNS = ["\\bclaim\\b", "\\bexpense\\b"]

async def decide(request, kit):
    text = request.lower()

    def found(pattern):
        return len(kit.find(pattern, text)) > 0

    def normalize(raw):
        digits = ""
        for ch in raw:
            if "0" <= ch <= "9":
                digits += ch
        if len(digits) == 0:
            return ""
        return "T-" + digits

    def negative(raw):
        pos = text.find(raw)
        while pos != -1:
            before = text[max(0, pos - 8):pos]
            after = text[pos + len(raw):min(len(text), pos + len(raw) + 25)]
            before_clean = before.strip()
            if before_clean.endswith("not") or "ignore" in before:
                return True
            if after.startswith(" is a different"):
                return True
            if after.startswith(" is different"):
                return True
            if after.startswith(" is the other"):
                return True
            if after.startswith(" is other"):
                return True
            if after.startswith(" needs nothing"):
                return True
            if after.startswith(" need nothing"):
                return True
            pos = text.find(raw, pos + 1)
        return False

    if any(found(pattern) for pattern in STOP_PATTERNS) or any(phrase in text for phrase in STOP_PHRASES):
        return {"handoff": "request is about something other than filing a new expense claim"}

    if not (any(found(pattern) for pattern in FILE_PATTERNS) and any(found(pattern) for pattern in CLAIM_PATTERNS)):
        return {"handoff": "request is not a clear expense-claim filing request"}

    raw_matches = kit.find("(t-\\d+|trip\\s*\\d+)", text)
    if len(raw_matches) == 0:
        return {"handoff": "no valid trip id was specified"}

    candidates = []
    raws = []
    for raw in raw_matches:
        norm = normalize(raw)
        if len(norm) > 0 and norm not in candidates:
            candidates.append(norm)
            raws.append(raw)

    if len(candidates) == 0:
        return {"handoff": "no valid trip id was specified"}

    selected = candidates[0]

    if len(candidates) == 1:
        if negative(raws[0]):
            return {"handoff": "the trip id is ambiguous"}
    else:
        questions = {
            "trip": {
                "type": "choice",
                "instructions": "Choose the single trip id the user wants filed. Pick none if the request is ambiguous or incomplete, or if no single filing target is clear.",
                "criteria": {cand: "file this trip" for cand in candidates},
            }
        }
        questions["trip"]["criteria"]["none"] = "no single clear filing target"
        state = {"request": request, "text": text, "candidates": candidates}
        try:
            answer = await kit.ask(state, questions)
            pick = answer["trip"]["choice"]
            confidence = answer["trip"]["confidence"]
        except Exception:
            return {"handoff": "the trip id is ambiguous"}

        if pick == "none" or pick not in candidates or confidence < 0.7:
            return {"handoff": "the trip id is ambiguous"}
        selected = pick

    try:
        trip = kit.read("read_trip", trip_id=selected)
    except Exception:
        return {"handoff": "trip id was not found"}

    if isinstance(trip, dict) and "error" in trip:
        return {"handoff": "trip id was not found"}

    try:
        total = await kit.procedure("reimbursable_total", trip_id=selected)
        amount = round(float(total["total_usd"]), 2)
    except Exception:
        return {"handoff": "could not compute the reimbursable total"}

    return {
        "action": "file_claim",
        "arguments": {"trip_id": selected, "amount_usd": amount},
        "reply": "Filed your claim for " + selected + " for $" + str(amount) + ".",
    }
