def readNumber(value):
    if isinstance(value, dict):
        if "noul" in value:
            return readNumber(value["noul"])
        if "total_usd" in value:
            return readNumber(value["total_usd"])
        if "confidence" in value:
            return readNumber(value["confidence"])
        if "value" in value:
            return readNumber(value["value"])
        if "answer" in value:
            return readNumber(value["answer"])
        if len(value) == 1:
            for key in value:
                return readNumber(value[key])
        return None
    try:
        return float(value)
    except Exception:
        return None

def extractChoice(answer):
    if isinstance(answer, dict):
        if "choice" in answer:
            choice = answer["choice"]
            confidence = readNumber(answer.get("confidence"))
            if confidence is None:
                confidence = 0.0
            return choice, confidence
        if "value" in answer:
            choice = answer["value"]
            confidence = readNumber(answer.get("confidence"))
            if confidence is None:
                confidence = 0.0
            return choice, confidence
        if "answer" in answer:
            choice = answer["answer"]
            confidence = readNumber(answer.get("confidence"))
            if confidence is None:
                confidence = 0.0
            return choice, confidence
        if len(answer) == 1:
            for key in answer:
                return extractChoice(answer[key])
    if isinstance(answer, str):
        return answer, 1.0
    return NONE_OPTION, 0.0

def normalizeTripId(candidate, kit):
    text = str(candidate)
    lower = text.lower()
    digits = list(kit.find("\\d+", text))
    if len(digits) == 0:
        return ""
    number = digits[0]
    if lower.startswith("trip ") or lower.startswith("t-"):
        return "T-" + number.zfill(3)
    return ""

async def decide(request, kit):
    lower_request = request.lower()
    words = list(kit.find("[A-Za-z]+", lower_request))
    word_set = set(words)

    action_found = any(word in word_set for word in ["file", "files", "filed", "filing", "submit", "submits", "submitted", "submitting"])
    target_found = any(word in word_set for word in ["claim", "claims", "expense", "expenses"])
    if not (action_found and target_found):
        return {"handoff": "this request is not clearly asking to file an expense claim"}

    candidates = list(kit.find(TRIP_PATTERN, request))
    if len(candidates) == 0:
        return {"handoff": "no trip id found in the filing request"}

