        amount = readNumber(total["total_usd"])
    else:
        amount = readNumber(total)

    if amount is None or amount < 0:
        return {"handoff": "could not compute the reimbursable total"}

    return {
        "action": "file_claim",
        "arguments": {"trip_id": trip_id, "amount_usd": amount},
        "reply": "Your expense claim for " + trip_id + " has been filed."
    }
