    "please submit my expense claim for",
    "submit my expense claim for",
    "please file my claim for",
    "file my claim for",
    "please submit my claim for",
    "submit my claim for",
    "please file my expense claim",
    "file my expense claim",
    "please submit my expense claim",
    "submit my expense claim",
]

async def decide(request, kit):
    text = request.lower()

    for word in OUTSCOPE:
        if word in text:
            return {"handoff": "This request is out of scope for filing claims."}

    tripids = kit.find("(?i)T-\\d+", request)
    if len(tripids) == 0:
        return {"handoff": "I couldn't identify a valid trip id."}

    filepos = -1
    for phrase in FILEPHRASES:
        pos = text.rfind(phrase)
        if pos > filepos:
            filepos = pos

    if filepos < 0:
        return {"handoff": "I couldn't tell that this is a request to file a claim."}

    besttrip = None
    bestscore = None
    tied = 0

    for tripid in tripids:
        lowid = tripid.lower()
        pos = text.find(lowid)
        if pos < 0:
            continue

        score = 0
        if pos >= filepos:
            score += 10
        else:
            score -= 5

        if ("only act on " + lowid) in text:
            score += 20
        if ("only file " + lowid) in text:
            score += 20
        if ("only for " + lowid) in text:
            score += 15

        left = pos - 35
        if left < 0:
            left = 0
        right = pos + len(lowid) + 40
        if right > len(text):
            right = len(text)
        window = text[left:right]

        if ("not " + lowid) in window:
            score -= 12
        if ("ignore " + lowid) in window:
            score -= 12
        if "different trip" in window:
            score -= 8
        if "different one" in window:
            score -= 8
        if "needs nothing" in window:
            score -= 8
        if "other trip" in window:
            score -= 8

        if bestscore is None or score > bestscore:
            bestscore = score
            besttrip = tripid
            tied = 1
        elif score == bestscore:
            tied += 1

    if besttrip is None or tied != 1 or bestscore is None or bestscore < 5:
        return {"handoff": "I can't confidently identify a single trip to file."}

    tripdata = None
    names = ["read_trip", "trip"]
    for name in names:
        try:
            data = kit.read(name, trip_id=besttrip)
        except Exception:
            data = None
        if isinstance(data, dict) and not data.get("error"):
            tripdata = data
            break

    if tripdata is None:
        return {"handoff": "That trip id doesn't look valid for this traveler."}

    try:
        result = await kit.procedure("reimbursable_total", trip_id=besttrip)
    except Exception:
        return {"handoff": "I couldn't compute the reimbursable total."}

    if not isinstance(result, dict) or "total_usd" not in result:
        return {"handoff": "I couldn't compute the reimbursable total."}

    amount = round(float(result["total_usd"]), 2)

    return {
        "action": "file_claim",
        "arguments": {"trip_id": besttrip, "amount_usd": amount},
        "reply": "Filed the claim for " + besttrip + ".",
    }
