        raw_low = raw.lower()
        for phrase in phrases:
            start = 0
            while True:
                p = text.find(phrase, start)
                if p < 0:
                    break
                q = text.find(raw_low, max(0, p - window))
                if q >= 0 and q <= p + window:
                    return True
                start = p + 1
        return False

