    # Obvious placeholders or incomplete fragments.
    if "{" in t or "}" in t or "..." in t or "<" in t or ">" in t:
        return False

    # Too short to be unmistakable.
    words = re.findall(r"\b[\w'-]+\b", t)
    if len(words) < 3:
        return False

    # Requests that rely on vague references are not sufficiently specified.
    if sum(1 for ref in VAGUE_REFERENCES if re.search(rf"\b{re.escape(ref)}\b", t)) >= 2:
        return False

    # Must contain a clear action cue.
    if not any(re.search(rf"\b{re.escape(word)}\b", t) for word in ACTION_WORDS):
        return False

    return True

def decide(request: Any) -> str:
    text = _normalize(request)
    if not _is_fully_specified(text):
        return "HANDOFF"

    # Only allow handling when the request is explicit enough to be unmistakable.
    return "HANDLE"

# Common aliases / fallbacks for different harnesses.
main = decide

_request = (
    globals().get("request", None)
    if "request" in globals()
    else globals().get("input", None)
    if "input" in globals()
    else globals().get("message", None)
    if "message" in globals()
    else globals().get("text", None)
    if "text" in globals()
    else globals().get("prompt", None)
    if "prompt" in globals()
    else globals().get("query", None)
)

decision = action = result = output = decide(_request)
