SHOWN_FAILURES = 8


def code_of(reply):
    parts = reply.split("```")
    if len(parts) < 3:
        return reply.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[len("python"):]
    return block.strip() + "\n"


def failure_text(task_id, request, reason, observed):
    text = "Task: " + str(task_id) + "\nRequest: " + request + "\nOutcome: " + reason
    if observed:
        text += "\nObserved: " + str(observed)
    return text


def extract_names(text, marker):
    names = []
    start = 0
    while True:
        pos = text.find(marker, start)
        if pos < 0:
            break
        i = pos + len(marker)
        while i < len(text) and text[i] in " \t\r\n:=,;.'\"`([{":
            i += 1
        j = i
        while j < len(text) and (text[j].isalnum() or text[j] == "_"):
            j += 1
        name = text[i:j]
        if name and name not in names:
            names.append(name)
        start = pos + len(marker)
    return names


def issue_lists_from_texts(texts):
    missing = []
    unsafe = []
    for text in texts:
        if not text:
            continue
        for name in extract_names(text, "no action"):
            if name not in missing:
                missing.append(name)
        for name in extract_names(text, "it took "):
            if name not in unsafe:
                unsafe.append(name)
        for name in extract_names(text, "took "):
            if name not in unsafe:
                unsafe.append(name)
    return missing, unsafe


def list_text(label, names):
    if not names:
        return label + ": none"
    return label + ": " + ", ".join(names)


def caution_block(actions):
    if not actions:
        return ""
    return (
        "Conservative caution: these actions appeared in wrong-action failures and should be "
        "treated as unsafe unless the contract clearly and explicitly authorizes them: "
        + ", ".join(actions)
        + ". Restrict each one to an exact, clearly authorized request pattern."
    )


def sample_tasks(task_ids, limit):
    items = list(task_ids)
    if not items:
        return []
    if len(items) <= limit:
        return items
    if limit <= 1:
        return [items[len(items) // 2]]
    if limit == 2:
        return [items[0], items[-1]]
    if limit == 3:
        return [items[0], items[len(items) // 2], items[-1]]
    picks = []
    for index in range(limit):
        position = index * (len(items) - 1) // (limit - 1)
        task_id = items[position]
        if task_id not in picks:
            picks.append(task_id)
    return picks


async def practice_program(program, task_ids, lab):
    rewards = {}
    failures = []
    for task_id in task_ids:
        reward, reason, observations = await lab.practice(program, task_id)
        rewards[task_id] = reward
        if reward < 1:
            request = lab.request(task_id)
            failures.append(failure_text(task_id, request, reason, observations))
    return rewards, failures


