        return False

    def unique(values):
        result = []
        for value in values:
            if value not in result:
                result.append(value)
        return result

    def canonicalize(raw, kind):
        value = raw.upper().replace(" ", "")
        prefix = "DOC" if kind == "doc" else "INV"
        if value.startswith(prefix):
            rest = value[len(prefix):]
            if rest.startswith("-"):
                rest = rest[1:]
            if rest.isdigit():
                if len(rest) < 3:
                    rest = rest.zfill(3)
                return prefix + "-" + rest
            if rest:
                return prefix + "-" + rest
            return prefix
        if value.isdigit():
            if len(value) < 3:
                value = value.zfill(3)
            return prefix + "-" + value
        return value

    async def extractid(kind):
        pattern = "(?:DOC-?\\d+|INV-?\\d+|\\b\\d{1,6}\\b)"
