        prefixed = []
        for cand in filtered:
            if cand.upper().startswith(prefix):
                prefixed.append(cand)

        if len(prefixed) == 1:
            return canonicalize(prefixed[0], kind)
        if len(prefixed) > 1:
            candidates = prefixed
        else:
            candidates = filtered

        if len(candidates) == 1:
            return canonicalize(candidates[0], kind)

        criteria = {}
        for cand in candidates:
            criteria[cand] = "the request refers to " + cand
        criteria["none"] = "none of these fit"

