"""Program synthesis: a decision program written from the agent's judged runs, then repaired from its own practice."""

DRAFT_PROMPT = """{contract}

You are writing a decision program for this job from judged runs.

Learn only the patterns that are clearly supported by the examples.
Be conservative: a wrong action is much worse than a hand-off.
Do not overgeneralize a tool-like phrase into a direct action branch unless the contract and accepted runs clearly support it.
If a request is ambiguous, outside the job, or only weakly matches a learned pattern, hand it off rather than acting.

{episodes}"""

REPAIR_PROMPT = """{contract}

This decision program was tried on requests for this job:

```python
{program}
```

These requests came out wrong or were handed off when they could have been served.
The first block is the most important to fix.

{failures}

When repairing, be especially careful about branches that are too broad.
If a failure should have been handed off, narrow or remove the matching action path instead of forcing an action.
Preserve the parts that already work.

Reply with one ```python block that holds the whole program."""

ROUNDS = 4
SHOWN_FAILURES = 16


def code_of(reply):
    start = reply.find("```")
    if start < 0:
        return reply.strip() + "\n"
    rest = reply[start + 3:]
    if rest.startswith("python"):
        rest = rest[len("python"):]
    end = rest.find("```")
    if end >= 0:
        rest = rest[:end]
    return rest.strip() + "\n"


def words(text):
    out = []
    current = []
    for ch in text.lower():
        if ch.isalnum():
            current.append(ch)
        else:
            if current:
                word = "".join(current)
                if len(word) > 2:
                    out.append(word)
                current = []
    if current:
        word = "".join(current)
        if len(word) > 2:
            out.append(word)
    return out


def common_terms(texts):
    pool = None
    for text in texts:
        seen = set(words(text))
        if pool is None:
            pool = seen
        else:
            pool = {word for word in pool if word in seen}
    if not pool:
        return []
    return sorted(pool)


def failure_block(items):
    chunks = []
    for task_id, request, reward, reason, observed in items[:SHOWN_FAILURES]:
        chunks.append(
            "Task: " + str(task_id) +
            "\nRequest: " + request +
            "\nReward: " + str(reward) +
            "\nReason: " + str(reason) +
            "\nObserved: " + str(observed)
        )
    return "\n\n".join(chunks)


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    program = code_of(await lab.ask(lab.fill(DRAFT_PROMPT, contract=lab.contract, episodes=shown)))
    best = program
    best_score = -10**9

    for attempt in range(ROUNDS):
        hard = []
        soft = []
        score = 0.0

        for task_id in lab.stream():
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            request = lab.request(task_id)
            if reward < 0:
                hard.append((task_id, request, reward, reason, observed))
            elif reward < 1:
                soft.append((task_id, request, reward, reason, observed))

        lab.note("attempt " + str(attempt) + ": score " + str(score))

        if score > best_score:
            best = program
            best_score = score

        if not hard and not soft:
            break

        selected = hard if hard else soft
        terms = common_terms([item[1] for item in selected])
        extra = ""
        if terms:
            extra = "\n\nLikely over-broad shared request terms: " + ", ".join(terms[:12])

        program = code_of(
            await lab.ask(
                lab.fill(
                    REPAIR_PROMPT,
                    contract=lab.contract,
                    program=program,
                    failures=failure_block(selected) + extra
                )
            )
        )

    return best

