"""Program synthesis: a decision program written from judged runs, then repaired from practice with conservative counterexamples."""

DRAFT_PROMPT = """{contract}

Below are judged runs for this job: each request, the observed tool trace, and the verdict.

Write a decision program that follows the accepted behavior shown here.

Rules for the program:
- Be conservative about out-of-job requests, but do not overuse hand-offs for requests that clearly match the contract.
- If a request clearly maps to a contract action, handle it directly in code.
- Only hand off when the request is outside the job, genuinely ambiguous, or would require guessing.
- Do not invent actions.
- For any action that commits to a future event, external side effect, payment, booking, scheduling, or other state change, require an explicit request and clear contract support; otherwise hand off.
- Be especially careful with actions that change state or schedule something: only use them when the request explicitly asks for that operation and the contract clearly supports it.
- schedule_payment is high-risk: do not infer it from payment-related context, deadlines, reminders, or timing hints. Only include it if the contract explicitly defines it and the request explicitly and unambiguously asks to schedule a payment with all required details. If there is any doubt, hand off.
- If code can decide, use code. Ask Jev only for judgments code cannot make.
- Keep the full program self-contained and generic to this contract.

{episodes}"""

REPAIR_PROMPT = """{contract}

This decision program was tried on requests for this job:

```python
{program}
```

These requests came out wrong or were handed off when they could have been served:

{failures}

{coverage}

{cautions}

Rewrite the program so these come out right, keeping what already works.

Important repair guidance:
- If a failure says the program handed off a request that should have been served, add coverage for that pattern instead of staying overly conservative.
- If a failure says it took an unsafe action, narrow that action so it only fires on explicit requests that clearly ask for it.
- If a failure says it took schedule_payment, remove that behavior unless the contract explicitly requires scheduling payments and the request is an explicit direct request with no ambiguity.
- If schedule_payment appeared as a wrong action, remove any branch that calls it; do not keep a guarded fallback version unless the contract itself plainly requires it.
- Do not let one risky action suppress other safe actions.
- Prefer direct serving for requests that clearly match contract actions, especially read-only or lookup-style actions.
- Reply with one ```python block that holds the whole program."""

ROUNDS = 4
SHOWN_FAILURES = 20


def code_of(reply):
    parts = reply.split("```")
    if len(parts) < 3:
        return reply.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[len("python"):]
    return block.strip() + "\n"


def failure_text(task_id, request, reason, observed):
    text = "Task: " + str(task_id) + "\nRequest: " + request + "\nOutcome: " + reason
    if observed:
        text += "\nObserved: " + str(observed)
    return text


def parse_missing_actions(text):
    names = []
    marker = "no action "
    if marker not in text:
        marker = "missing action "
    if marker not in text:
        return names
    tail = text.split(marker, 1)[1].strip()
    if not tail:
        return names
    if tail[0] in "\"'`":
        quote = tail[0]
        tail = tail[1:]
        name = tail.split(quote, 1)[0].strip()
    else:
        name = tail.split(",", 1)[0].split(".", 1)[0].split(";", 1)[0].split(":", 1)[0].strip()
        name = name.split(" ", 1)[0].strip()
    name = name.strip(".;:()[]{}")
    if name:
        names.append(name)
    return names


def parse_taken_actions(text):
    names = []
    marker = "it took "
    if marker not in text:
        marker = "took "
    if marker not in text:
        return names
    tail = text.split(marker, 1)[1]
    name = tail.split(",", 1)[0].strip()
    name = name.split(" ", 1)[0].strip()
    name = name.strip(".;:()[]{}")
    if name:
        names.append(name)
    return names


def unique(items):
    out = []
    for item in items:
        if item and item not in out:
            out.append(item)
    return out


def missing_actions(failures):
    names = []
    for item in failures:
        for name in parse_missing_actions(item):
            names.append(name)
    return unique(names)


def unsafe_actions(failures):
    names = []
    for item in failures:
        if "it took " in item or "took " in item:
            for name in parse_taken_actions(item):
                names.append(name)
    return unique(names)


def coverage_block(actions):
    if not actions:
        return ""
    return (
        "Coverage note: the following actions were missing from hand-offs and should be "
        "implemented when the request clearly asks for them, including obvious paraphrases: "
        + ", ".join(actions)
        + "."
    )


def caution_block(actions):
    if not actions:
        return ""
    base = (
        "Safety note: the following actions appeared in wrong-action failures and should be "
        "treated as high-risk unless the request explicitly asks for them: "
        + ", ".join(actions)
        + ". Only fire them on clear, explicit requests; otherwise hand off."
    )
    if "schedule_payment" in actions:
        base += (
            " Hard ban: do not infer schedule_payment from timing, reminders, deadlines, "
            "payment context, or partial instructions. Unless the contract explicitly defines "
            "schedule_payment and the request explicitly requests scheduling a payment with all "
            "required details, the program must hand off."
        )
    return base


def objective_score(score, failures):
    bonus = 0.0
    for item in failures:
        text = item.lower()
        if "no action" in text or "missing action" in text:
            bonus += 0.25
        if "it took " in text or "took " in text:
            bonus -= 1.0
    return score + bonus


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    program = code_of(await lab.ask(lab.fill(DRAFT_PROMPT, contract=lab.contract, episodes=shown)))
    best = program
    best_score = -10**9
    best_failures = 10**9

    for attempt in range(ROUNDS):
        failures = []
        score = 0.0

        for task_id in lab.stream():
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            if reward < 1:
                request = lab.request(task_id)
                failures.append(failure_text(task_id, request, reason, observed))

        total = objective_score(score, failures)
        lab.note(
            "attempt "
            + str(attempt)
            + ": score "
            + str(score)
            + ", objective "
            + str(total)
            + ", failures "
            + str(len(failures))
        )

        if total > best_score or (total == best_score and len(failures) < best_failures):
            best = program
            best_score = total
            best_failures = len(failures)

        if not failures or attempt == ROUNDS - 1:
            break

        miss = missing_actions(failures)
        unsafe = unsafe_actions(failures)

        if miss:
            lab.note("missing actions: " + ", ".join(miss))
        if unsafe:
            lab.note("unsafe actions: " + ", ".join(unsafe))
            if "schedule_payment" in unsafe:
                lab.note("hard ban: schedule_payment must be removed unless the contract explicitly requires it and the request is an explicit scheduling request")

        program = code_of(
            await lab.ask(
                lab.fill(
                    REPAIR_PROMPT,
                    contract=lab.contract,
                    program=program,
                    failures="\n\n".join(failures[:SHOWN_FAILURES]),
                    coverage=coverage_block(miss),
                    cautions=caution_block(unsafe),
                )
            )
        )

    return best

