    return False


def canonical_id(prefix, raw):
    digits = ""
    for ch in raw:
        if ch >= "0" and ch <= "9":
            digits = digits + ch
    if digits == "":
        return None
    return prefix + "-" + digits.zfill(3)


def gather_ids(text, patterns, prefix, kit):
    raw = []
    for pattern in patterns:
