"""Program synthesis: a decision program written from judged runs, then repaired from practice with a conservative boundary."""

DRAFT_PROMPT = """{contract}

Below are runs where the assistant handled requests for this job: each request, the steps taken, and the verdict.

Write a decision program that handles requests the way the accepted runs did, using no language model. Use code for everything code can do. Ask Jev only for judgments code can't make, such as what a request is really asking for, or which of several candidates it means. Be conservative: a wrong action is much worse than a hand-off.

Important boundary rule: if a request looks like money movement, payment, billing, invoicing, refunds, transfers, scheduling a payment, or any other external side effect, and the contract/examples do not clearly show that this job owns it, hand it off instead of acting.

{episodes}"""

REPAIR_PROMPT = """{contract}

This decision program was tried on requests for this job:

```python
{program}
```

These requests came out wrong or were handed off when they could have been served:

{failures}

Rewrite the program so these come out right, keeping what already works.

Use a conservative boundary: if a request is outside the job, or if it involves money/payment/billing/transfer/refund/schedule_payment or any other side effect not clearly covered by the contract/examples, hand it off rather than taking a wrong action.

Reply with one ```python block that holds the whole program."""

ROUNDS = 4
SHOWN_FAILURES = 16


def code_of(reply):
    parts = reply.split("```")
    if len(parts) < 3:
        return reply.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[len("python"):]
    return block.strip() + "\n"


def failure_hint(failures):
    text = "\n".join((request + " " + reason + " " + observed).lower() for request, reason, observed in failures)
    hints = []
    if "schedule_payment" in text:
        hints.append("Note: schedule_payment requests should be treated as out of scope unless the contract/examples clearly authorize them.")
    if "payment" in text or "billing" in text or "invoice" in text or "refund" in text or "transfer" in text:
        hints.append("Note: requests involving money, billing, invoices, refunds, or transfers should default to hand-off unless clearly in scope.")
    return "\n".join(hints)


def failure_block(failures):
    chunks = []
    for request, reason, observed in failures:
        chunk = "Request: " + request + "\nOutcome: " + reason
        if observed:
            chunk += "\nObserved: " + observed
        chunks.append(chunk)
    return "\n\n".join(chunks)


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    program = code_of(await lab.ask(lab.fill(DRAFT_PROMPT, contract=lab.contract, episodes=shown)))
    best = program
    best_score = -1.0
    for attempt in range(ROUNDS):
        failures = []
        score = 0.0
        for task_id in lab.stream():
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            if reward < 1:
                failures.append((lab.request(task_id), reason, observed))
        lab.note("attempt " + str(attempt) + ": score " + str(score))
        if score > best_score:
            best = program
            best_score = score
        if not failures or attempt == ROUNDS - 1:
            break
        prompt = lab.fill(
            REPAIR_PROMPT,
            contract=lab.contract,
            program=program,
            failures=failure_block(failures[:SHOWN_FAILURES]) + ("\n\n" + failure_hint(failures[:SHOWN_FAILURES]) if failure_hint(failures[:SHOWN_FAILURES]) else "")
        )
        program = code_of(await lab.ask(prompt))
    return best

