"""Program synthesis: a decision program written from judged runs, then repaired with separated safe lookups and unsafe actions."""

DRAFT_PROMPT = """{contract}

Below are judged runs for this job: each request, the observed tool trace, and the verdict.

Write a decision program that follows the accepted behavior shown here. Be conservative about side effects:
- Serve direct information retrieval, extraction, counting, lookup, and other clearly read-only requests when the contract supports them.
- Hand off requests that are outside the job, ambiguous, or would require guessing.
- For action names that look side-effectful or commitment-like, only use them when the contract and request clearly authorize them.
- If the judged runs reveal a missing action that is clearly a lookup or other read-only capability, add it instead of handing it off.
- Use Jev only for judgments code cannot make, such as selecting between valid interpretations when the contract allows multiple.

{episodes}"""

REPAIR_PROMPT = """{contract}

This decision program was tried on requests for this job:

```python
{program}
```

Observed failures are grouped below.

Missing capabilities: these requests were handed off even though the program should have served them.
{missing}

Unsafe capabilities: these requests were served with an action that should not have been taken.
{unsafe}

Other failures:
{other}

{cautions}

Rewrite the program so the missing capabilities are added when the contract supports them, while keeping the unsafe capabilities conservative. A wrong action is much worse than a hand-off, but do not let a wrong-action failure suppress a clearly read-only or lookup-style capability that the contract authorizes.

Reply with one ```python block that holds the whole program."""

ROUNDS = 4
SHOWN_FAILURES = 14


def code_of(reply):
    parts = reply.split("```")
    for index in range(1, len(parts), 2):
        block = parts[index]
        if block.startswith("python"):
            block = block[len("python"):]
            return block.strip() + "\n"
    if len(parts) >= 2:
        block = parts[1]
        if block.startswith("python"):
            block = block[len("python"):]
        return block.strip() + "\n"
    return reply.strip() + "\n"


def failure_text(task_id, request, reason, observed):
    text = "Task: " + str(task_id) + "\nRequest: " + request + "\nOutcome: " + reason
    if observed:
        text += "\nObserved: " + str(observed)
    return text


def action_name(text):
    markers = ["no action '", "no action ", "it took ", "took "]
    for marker in markers:
        if marker not in text:
            continue
        tail = text.split(marker, 1)[1]
        if marker == "no action '":
            return tail.split("'", 1)[0].strip().strip(".;:()[]{}")
        name = tail.split(",", 1)[0].strip()
        name = name.split(" ", 1)[0].strip()
        return name.strip(".;:()[]{}")
    return ""


def categorize_failure(reason):
    lowered = reason.lower()
    if "no action" in lowered or "could be served" in lowered:
        return "missing"
    if "should have been handed off" in lowered or "wrong action" in lowered:
        return "unsafe"
    if "handed off" in lowered and "could be served" in lowered:
        return "missing"
    return "other"


def split_failures(failures):
    missing = []
    unsafe = []
    other = []
    for item in failures:
        reason = item.split("\nOutcome: ", 1)[1] if "\nOutcome: " in item else item
        kind = categorize_failure(reason)
        name = action_name(reason)
        if kind == "missing" and name:
            if name not in missing:
                missing.append(name)
        elif kind == "unsafe" and name:
            if name not in unsafe:
                unsafe.append(name)
        else:
            other.append(item)
    return missing, unsafe, other


def caution_block(actions):
    if not actions:
        return ""
    return (
        "Conservative caution: the following actions appeared in wrong-action failures and should "
        "be treated as unsafe unless the contract clearly and explicitly authorizes them: "
        + ", ".join(actions)
        + ". If a request would lead to one of these actions but the contract does not clearly "
        "say to do it, hand the request off."
    )


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    program = code_of(await lab.ask(lab.fill(DRAFT_PROMPT, contract=lab.contract, episodes=shown)))
    best = program
    best_score = -1.0
    best_failures = 10**9

    for attempt in range(ROUNDS):
        failures = []
        score = 0.0

        for task_id in lab.stream():
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            if reward < 1:
                request = lab.request(task_id)
                failures.append(failure_text(task_id, request, reason, observed))

        lab.note("attempt " + str(attempt) + ": score " + str(score) + ", failures " + str(len(failures)))

        if score > best_score or (score == best_score and len(failures) < best_failures):
            best = program
            best_score = score
            best_failures = len(failures)

        if not failures or attempt == ROUNDS - 1:
            break

        missing, unsafe, other = split_failures(failures)
        cautions = caution_block(unsafe)

        if missing:
            lab.note("missing capabilities: " + ", ".join(missing))
        if unsafe:
            lab.note("unsafe actions: " + ", ".join(unsafe))

        program = code_of(
            await lab.ask(
                lab.fill(
                    REPAIR_PROMPT,
                    contract=lab.contract,
                    program=program,
                    missing="\n\n".join(missing) if missing else "(none)",
                    unsafe="\n\n".join(unsafe) if unsafe else "(none)",
                    other="\n\n".join(other[:SHOWN_FAILURES]) if other else "(none)",
                    cautions=cautions,
                )
            )
        )

    return best

