            norm = normalize_id(prefix, ref)
            if norm is not None and norm not in out:
                out.append(norm)
        return out

    def norm_amount(value):
        return round(float(value), 2)

    async def pick_target(ids, kind):
        if len(ids) == 0:
            return None
        if len(ids) == 1:
            return ids[0]
        state = {"request": request, "kind": kind, "candidates": ids}
        criteria = {}
        for ident in ids:
            criteria[ident] = "Act on " + ident + "."
        criteria["none"] = "No clear target."
        questions = {
            "target": {
                "type": "choice",
                "instructions": "Choose the single " + kind + " ID the user wants acted on. Prefer the one explicitly asked to be entered or scheduled, and ignore IDs described as already handled, different, or needing nothing. If no candidate clearly fits, choose none.",
                "criteria": criteria,
            }
        }
        try:
            ans = await kit.ask(state, questions)
        except Exception:
            return None
        picked = ans["target"].get("choice")
        confidence = ans["target"].get("confidence", 0.0)
        if picked == "none" or picked not in ids or confidence < 0.6:
            return None
        return picked

    doc_ids = find_ids(DOC_PATTERN, "DOC")
    inv_ids = find_ids(INV_PATTERN, "INV")

    status_intent = (
        "been entered" in low
        or "entered yet" in low
        or "already entered" in low
        or "has it been entered" in low
        or "is it entered" in low
        or "been recorded" in low
        or "status" in low
    )

    record_intent = (
        not status_intent
        and (
            "enter" in low
            or "record" in low
            or "add" in low
            or "post" in low
        )
    )

    schedule_intent = (
        "schedule" in low
        or "set up" in low
        or "set-up" in low
        or "make payment" in low
        or "pay invoice" in low
        or "payment for" in low
        or "payment of" in low
        or "work out what we owe" in low
        or "what we owe" in low
        or "owe on" in low
    )

    if status_intent and len(doc_ids) > 0:
        return {"handoff": "This request asks about a document's status rather than entering it."}

    if record_intent and len(doc_ids) > 0:
        target = await pick_target(doc_ids, "document")
        if target is None:
            return {"handoff": "I couldn't tell which document to record."}
        try:
            parsed = await kit.procedure("parse_invoice", doc_id=target)
        except Exception:
            return {"handoff": "I couldn't parse " + target + " for ledger entry."}
        if not isinstance(parsed, dict) or parsed.get("error"):
            return {"handoff": "I couldn't parse " + target + " for ledger entry."}
        if "doc_id" not in parsed:
            parsed = dict(parsed)
            parsed["doc_id"] = target
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + target + " in the ledger.",
        }

    if schedule_intent and len(inv_ids) > 0:
        target = await pick_target(inv_ids, "invoice")
        if target is None:
            return {"handoff": "I couldn't tell which invoice to schedule."}
        try:
            payable = await kit.procedure("amount_payable", invoice_id=target)
        except Exception:
            return {"handoff": "I couldn't compute the payable amount for " + target + "."}
        if not isinstance(payable, dict) or payable.get("error"):
            return {"handoff": "I couldn't compute the payable amount for " + target + "."}
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "The payable amount for " + target + " was incomplete."}
        amount_usd = norm_amount(payable["amount_usd"])
        arguments = {
            "invoice_id": target,
            "amount_usd": amount_usd,
            "pay_on": payable["pay_on"],
        }
        return {
            "action": "schedule_payment",
            "arguments": arguments,
            "reply": "Scheduled payment for " + target + " for $" + str(amount_usd) + " on " + arguments["pay_on"] + ".",
        }

    return {"handoff": "This request is outside invoice entry and payment scheduling."}
