        if pay_on is None:
            for key in due:
                if 'pay' in key.lower() or 'date' in key.lower():
                    pay_on = due[key]
                    break

        if amount is None or pay_on is None:
            return {
                "handoff": "amount_payable did not return amount and pay date for " + canon_inv(inv),
                "route": "low"
            }

        amount_text = str(amount).replace(',', '').replace('$', '').strip()
        if amount_text[:3].upper() == 'USD':
            amount_text = amount_text[3:].strip()

        try:
            amount_value = float(amount_text)
        except Exception:
            return {
                "handoff": "amount_payable returned an unusable amount for " + canon_inv(inv),
