        }

    if len(INVS) > 0 and hasany(VENDOR_WORDS):
        return {
            "handoff": "vendor-related questions are out of scope",
            "route": "none"
        }

    if len(DOCS) > 0 and hasany(VENDOR_WORDS):
        return {
            "handoff": "vendor-related questions are out of scope",
            "route": "none"
        }

    return {
        "handoff": "no supported AP action is clear from this request",
        "route": "none"
