                "amount_usd": clean_num(amount_usd),
                "pay_on": str(pay_on),
            },
            "reply": "Scheduled payment for " + amount_invoice + ".",
        }

    if job_choice == JOB_RECORD:
        doc_id, picked_confidence = await choose_id("document", doc_ids)
        if doc_id == "":
            return handoff("I could not identify a single document id to use.")

        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict):
            return handoff("I could not parse document " + doc_id + ".")
        if "error" in parsed:
            return handoff("I could not parse document " + doc_id + ".")

        record = dict(parsed)
        if "doc_id" not in record:
            record["doc_id"] = doc_id

        return {
            "action": "record_invoice",
            "arguments": record,
            "reply": "Recorded document " + doc_id + ".",
        }

    return handoff("The request does not match a supported AP task.")
