DIGITS = "0123456789"
ID_PATTERN = "(?:(?:[Dd][Oo][Cc]|[Dd][Oo][Cc][Uu][Mm][Ee][Nn][Tt])[- ]?\\d+|(?:[Ii][Nn][Vv]|[Ii][Nn][Vv][Oo][Ii][Cc][Ee])[- ]?\\d+)"

async def decide(request, kit):
    def unique(items):
        out = []
        for item in items:
            if item and item not in out:
                out.append(item)
        return out

    def normalize_id(raw):
        up = raw.upper()
        digits = ""
        for ch in up:
            if ch in DIGITS:
                digits += ch
        if digits == "":
            return ""
        if "INV" in up or "INVOICE" in up:
            return "INV-" + digits
        return "DOC-" + digits

    def whole_number(value):
        if isinstance(value, float) and value == int(value):
            return int(value)
        return value

    raw_ids = kit.find(ID_PATTERN, request)
    ids = unique([normalize_id(x) for x in raw_ids])

    state = {
        "request": request,
        "ids": ids,
    }

    questions = {
        "intent": {
            "type": "choice",
            "instructions": "Decide whether the request is asking to enter a vendor invoice document into the ledger, schedule payment for an already-entered invoice, or should be handed off instead.",
            "criteria": {
                "record_invoice": "enter a vendor invoice document into the ledger",
                "schedule_payment": "schedule payment for an existing invoice",
                "handoff": "anything else, including questions, status checks, refusals, cancellations, disputes, vendor questions, or requests not to act now",
            },
        },
        "now": {
            "type": "noul",
            "instructions": "Is the request asking to carry out the chosen job now, rather than asking about it, refusing it, changing it, or discussing it?",
        },
        "target": {
            "type": "choice",
            "instructions": "If the request names several ids, choose the one the request is actually about. Choose none if no id fits.",
            "criteria": dict([(x, "candidate id") for x in ids] + [("none", "no matching id")]),
        },
    }

    judged = await kit.ask(state, questions)
    intent = judged.get("intent", {})
    now = judged.get("now", {})
    target = judged.get("target", {})

    choice = intent.get("choice", "handoff")
    carry_out = now.get("noul", 0.0)
    selected = target.get("choice", "none")

    if carry_out < 0.3 or carry_out > 0.7:
        return {"handoff": "The request is not clearly asking to carry out a ledger job now."}

    if choice == "record_invoice":
