    INV_PATTERNS = ["[Ii][Nn][Vv][- ]?[0-9]+", "[Ii]nvoice[^0-9]{0,3}[0-9]+"]
    JOB_RECORD = "record_invoice"
    JOB_PAY = "schedule_payment"
    JOB_OTHER = "other"
    JOB_CONF = 0.55
    PICK_CONF = 0.55

    def uniq(items):
        seen = set()
        out = []
        for item in items:
            item = str(item).upper()
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out

    def digits(text):
        out = ""
        for ch in str(text):
            if ch >= "0" and ch <= "9":
                out = out + ch
        return out

    def clean_num(value):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        return value

    def handoff(reason):
        return {"handoff": reason}

    def extract_ids(patterns, prefix):
        out = []
        for pattern in patterns:
            found = kit.find(pattern, request)
            for item in found:
                num = digits(item)
                if num != "":
                    out.append(prefix + num)
        return uniq(out)

    async def choose_id(kind, candidates):
        if len(candidates) == 0:
            return "", 0.0
        if len(candidates) == 1:
            return candidates[0], 1.0

        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "This is the " + kind + " id the user means."

        criteria["none"] = "None of these fit the request."

        judge = await kit.ask(
            {"request": request, "kind": kind, "candidates": candidates},
            {
                "which": {
                    "type": "choice",
                    "instructions": "Pick the single " + kind + " id the user means for this request. Use only the candidates shown. Choose none if none fit. If the request mentions more than one candidate, asks about several ids, or otherwise does not clearly point to one single id to act on, choose none. Ignore ids that are mentioned only as examples, comparisons, or as items that need nothing done.",
                    "criteria": criteria,
                }
            },
        )

        answer = judge.get("which", {})
        choice = answer.get("choice", "none")
        confidence = answer.get("confidence", 0.0)
        if choice == "none" or confidence < PICK_CONF:
            return "", confidence
        return choice, confidence

