                    'criteria': criteria
                }
            }
        )
        chosen = target_answer['target']['choice']
        chosen_confidence = target_answer['target']['confidence']
        if chosen == 'none' or chosen_confidence < TARGET_CUTOFF:
            return {'handoff': HANDOFF_TEXT}
        target = chosen

    if intent == 'schedule_payment':
        payable = await kit.procedure('amount_payable', invoice_id=target)
        return {
            'action': 'schedule_payment',
            'arguments': {
                'invoice_id': payable['invoice_id'],
                'amount_usd': payable['amount_usd'],
                'pay_on': payable['pay_on']
            },
