        if not isinstance(text, str):
            return False
        if len(text) != 10:
            return False
        if text[4] != '-' or text[7] != '-':
            return False
        if not text[:4].isdigit():
            return False
        if not text[5:7].isdigit():
            return False
        if not text[8:10].isdigit():
            return False
        return True

    def extract(pattern):
