    def canon(kind, raw):
        d = digits(raw)
        if d == '':
            return ''
        if kind == 'DOC':
            return 'DOC-' + d
        return 'INV-' + d

    def normalize_date(text):
        if not isinstance(text, str):
            return text
        if len(text) == 10 and text[4] == '-' and text[7] == '-':
            return text
        def pad2(value):
            if len(value) == 1:
                return '0' + value
            return value
        for sep in ('-', '/', '.'):
            if sep in text:
                parts = text.split(sep)
                if len(parts) == 3:
                    a = parts[0]
                    b = parts[1]
                    c = parts[2]
                    if len(a) == 4 and len(b) <= 2 and len(c) <= 2:
                        return a + '-' + pad2(b) + '-' + pad2(c)
                    if len(c) == 4 and len(a) <= 2 and len(b) <= 2:
                        return c + '-' + pad2(b) + '-' + pad2(a)
        return text

    def normalize_record(record):
        if not isinstance(record, dict):
            return record
        out = {}
        for key in record:
            value = record[key]
            if isinstance(value, str) and (key == 'pay_on' or key.endswith('_date')):
                out[key] = normalize_date(value)
            else:
