        "request": request,
        "trip_ids": candidates
    }

    questions = {
        "trip": {
            "type": "choice",
            "instructions": "Choose which trip id the user means, or none if the request is not asking to file a claim for one trip.",
            "criteria": options
        },
        "now": {
            "type": "noul",
            "instructions": "Does the request ask to file the claim now?"
        }
    }

    answers = await kit.ask(state, questions)
    trip_answer = answers["trip"]
    now_prob = answers["now"]["noul"]
    trip_choice = trip_answer["choice"]
    trip_conf = trip_answer["confidence"]

    if now_prob < NO:
        return {
            "handoff": "the request is not asking to file a claim now",
            "read_only": True
        }

    if now_prob < YES:
        return {
            "handoff": "it is unclear whether the request asks to file a claim now"
        }

    if trip_choice == NONE or trip_conf < YES:
        return {
            "handoff": "the trip id is ambiguous or missing"
