DOC_PATTERN = '(?:[Dd][Oo][Cc][- ]?\\d{1,4}|[Dd]ocument\\s*\\d{1,4})'
DOC_PREFIX = 'DOC-'
NONE_CHOICE = 'none'
RECORD_KEYS = ['doc_id', 'invoice_number', 'po_number', 'invoice_date', 'subtotal_usd', 'freight_usd', 'discount_percent', 'discount_days', 'net_days']

def normalizeDoc(candidate):
    text = str(candidate).strip()
    upper = text.upper()
    digits = ''
    for ch in upper:
        if ch.isdigit():
            digits = digits + ch
    if digits == '':
        return upper
    return DOC_PREFIX + digits.zfill(3)

def normalizeRecord(record):
    out = {}
    for key in RECORD_KEYS:
        if key in record:
            value = record[key]
            if isinstance(value, float) and int(value) == value:
                value = int(value)
            out[key] = value
    for key in record:
        if key not in out:
            value = record[key]
            if isinstance(value, float) and int(value) == value:
                value = int(value)
            out[key] = value
    return out

async def decide(request, kit):
    matches = kit.find(DOC_PATTERN, request)
    candidates = []
    seen = set()
    for match in matches:
        doc_id = normalizeDoc(match)
        if doc_id not in seen:
            seen.add(doc_id)
            candidates.append(doc_id)

    if len(candidates) == 0:
        return {'handoff': 'I could not identify the document id to enter.'}

    if len(candidates) == 1:
        doc_id = candidates[0]
    else:
        options = {}
        for candidate in candidates:
            options[candidate] = 'This is a candidate document id mentioned in the request.'
        options[NONE_CHOICE] = 'No candidate fits.'
        judgment = await kit.ask(
            {'request': request, 'candidates': candidates},
            {
