async def decide(request, kit):
    INV_PATTERNS = ('[Ii][Nn][Vv][Oo][Ii][Cc][Ee][- ]?\\d+', '[Ii][Nn][Vv][- ]?\\d+')
    DOC_PATTERNS = ('[Dd][Oo][Cc][Uu][Mm][Ee][Nn][Tt][- ]?\\d+', '[Dd][Oo][Cc][- ]?\\d+')

    SCHEDULE_PHRASES = (
        'schedule the payment',
        'schedule payment',
        'set up the payment',
        'set up payment',
        'payment setup',
        'work out what we owe',
        'what we owe on'
    )

    RECORD_PHRASES = (
        'record the vendor invoice',
        'record the invoice',
        'record invoice',
        'please record',
        'please enter',
        'enter the vendor invoice',
        'enter the invoice',
        'enter it in the ledger',
        'enter into the ledger',
        'enter document',
        'enter doc',
        'record document',
        'record doc'
    )

    def has_any(text, phrases):
        for phrase in phrases:
            if phrase in text:
                return True
        return False

    def normalize_id(raw, prefix):
        digits = ''
        for ch in raw:
            if ch >= '0' and ch <= '9':
                digits = digits + ch
        if digits != '':
            return prefix + '-' + digits
        return raw.upper()

    def extract_ids(text, prefix, patterns):
        found = []
        seen = set()
        for pattern in patterns:
            matches = kit.find(pattern, text)
            for raw in matches:
                value = normalize_id(raw, prefix)
                if value not in seen:
                    seen.add(value)
                    found.append(value)
        return found

    def valid_iso_date(value):
        if not isinstance(value, str):
            return False
        if len(value) != 10:
            return False
        for i, ch in enumerate(value):
            if i == 4 or i == 7:
                if ch != '-':
                    return False
            elif ch < '0' or ch > '9':
                return False
        return True

    async def choose_candidate(kind, candidates):
        if len(candidates) == 1:
            return candidates[0]
        options = {}
        for candidate in candidates:
            options[candidate] = 'Act on ' + candidate
        options['none'] = 'None of these'
        judgment = await kit.ask(
            {
                'request': request,
                'kind': kind,
                'candidates': candidates
            },
            {
                'selected': {
                    'type': 'choice',
                    'instructions': 'The request mentions several ' + kind + ' IDs. Choose the one the user means to act on. Prefer the ID tied to the actual command and ignore IDs explicitly described as different or needing nothing. If none fit, choose none.',
                    'criteria': options
                }
            }
        )
        choice = judgment['selected']['choice']
        if choice == 'none':
            return None
        if choice not in candidates:
            return None
        return choice

    lower = request.lower()
    invoice_ids = extract_ids(request, 'INV', INV_PATTERNS)
    document_ids = extract_ids(request, 'DOC', DOC_PATTERNS)

    schedule_like = has_any(lower, SCHEDULE_PHRASES)
    record_like = has_any(lower, RECORD_PHRASES)

    if schedule_like and record_like:
        return {
            'handoff': 'The request appears to mix invoice scheduling and document entry, so it needs a manual decision.',
            'read_only': True
        }

    if schedule_like and len(invoice_ids) > 0:
        invoice_id = await choose_candidate('invoice', invoice_ids)
        if invoice_id is None:
            return {
                'handoff': 'The request names multiple invoice IDs, and I could not determine which one to schedule.'
            }
        payable = await kit.procedure('amount_payable', invoice_id=invoice_id)
        if not isinstance(payable, dict):
            return {
                'handoff': 'I could not get a payable amount for ' + invoice_id + '.'
            }
        amount_usd = payable.get('amount_usd')
        pay_on = payable.get('pay_on')
        if not valid_iso_date(pay_on):
            return {
                'handoff': 'I got an invalid payment date for ' + invoice_id + '.'
            }
        await kit.procedure(
            'schedule_payment',
            invoice_id=invoice_id,
            amount_usd=float(amount_usd),
            pay_on=pay_on
        )
        return {
            'action': 'schedule_payment',
            'arguments': {
                'invoice_id': invoice_id,
                'amount_usd': float(amount_usd),
                'pay_on': pay_on
            },
            'reply': 'Scheduled payment for ' + invoice_id + ' on ' + pay_on + '.'
        }

    if record_like and len(document_ids) > 0:
        doc_id = await choose_candidate('document', document_ids)
        if doc_id is None:
            return {
                'handoff': 'The request names multiple document IDs, and I could not determine which one to record.'
            }
        parsed = await kit.procedure('parse_invoice', doc_id=doc_id)
        if not isinstance(parsed, dict):
            return {
                'handoff': 'I could not parse ' + doc_id + '.'
            }
        if not valid_iso_date(parsed.get('invoice_date')):
            return {
                'handoff': 'The parsed invoice date for ' + doc_id + ' is not in YYYY-MM-DD format.'
            }
        await kit.procedure('record_invoice', **parsed)
        return {
            'action': 'record_invoice',
            'arguments': parsed,
            'reply': 'Recorded ' + doc_id + ' in the ledger.'
        }

    if len(invoice_ids) > 0 or len(document_ids) > 0:
        return {
            'handoff': 'This is a read-only question or status check, not a payment scheduling or invoice-entry action.',
            'read_only': True
        }

    return {
        'handoff': 'I could not identify a single invoice or document to act on.',
        'read_only': True
    }
