            if has_any(request_words, {"entered", "scheduled", "done", "recorded"}):
                return True
        if "what" in request_words and "status" in request_words:
            return True
        if ("did" in request_words or "already" in request_words) and has_any(request_words, {"schedule", "scheduled", "enter", "entered", "record", "recorded"}):
            return True
        if ("which" in request_words or "where" in request_words or "who" in request_words) and has_any(request_words, {"email", "address", "contact", "remittance", "advice"}):
            return True
        return False

    def is_entry_request(request_words):
        if has_any(request_words, {"enter", "entered", "record", "recorded"}):
