async def learn(lab):
    if len(lab.memories) > 0:
        for memory in lab.memories:
            lab.remember(**memory)
        return ROUTER
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
    for kind in lab.parse(reply):
        lab.remember(kind["name"], kind["description"], kind["guidance"], route="none", read_only=not kind["acts"])
    return ROUTER

"""Everything through the language model: memories of how the work went, read by the model that serves each request.

Nothing here serves a request without the model, and nothing here asks Jev. It is where a search starts when the
question is whether a search can find the code that moves work from the model to a decision program.
"""

KINDS_PROMPT = """{contract}

Below are runs where the assistant, a language model, handled requests for
this job: each request, every tool call with its result, and the verdict.
Some requests are worded oddly, some should not be acted on at all, and
some runs went wrong.

List the kinds of request these runs show, and for each write what the
assistant should know the next time it meets one: how ids are really
written in the tools, which tools to call and in what order, and the
mistakes to avoid. Use as few kinds as cover the runs.

Reply with only a JSON list. Each item has the keys "name" (short, in
snake_case), "description" (which requests belong to this kind, and which
similar ones don't), "guidance" (what the assistant should know), and
"acts" (true if a request of this kind should end in an action, false if
it should only be answered or passed on).

{episodes}"""

ROUTER = """async def decide(request, kit):
    def words(text):
        chars = []
        for ch in text.lower():
            if ch.isalnum():
                chars.append(ch)
            else:
                chars.append(" ")
        return "".join(chars).split()

    def has_any(wordset, items):
        for item in items:
            if item in wordset:
                return True
        return False

    def score_memory(request_words, memory):
        memory_words = set(words(memory["name"] + " " + memory["description"]))
        return len(request_words & memory_words)

    def pick_by_name(found, names, require_read_only=None):
        for name in names:
            for memory in found:
                if memory["name"] == name:
                    if require_read_only is None or memory["read_only"] == require_read_only:
                        return memory
        return None

    def best_memory(found, request_words, require_read_only=None):
        best = None
        best_score = -1
        for memory in found:
            if require_read_only is not None and memory["read_only"] != require_read_only:
                continue
            score = score_memory(request_words, memory)
            if score > best_score:
                best = memory
                best_score = score
        return best

    def best_read_only(found, request_words, prefer_special):
        special = None
        special_score = -1
        best = None
        best_score = -1
        for memory in found:
            if not memory["read_only"]:
                continue
            score = score_memory(request_words, memory)
            if score > best_score:
                best = memory
                best_score = score
            if ("out_of_scope" in memory["name"] or "status_or_change" in memory["name"]) and score > special_score:
                special = memory
                special_score = score
        if prefer_special and special is not None:
            return special
        return best

    def has_negation(raw_text, request_words):
        text = raw_text.lower()
        if "don't" in text or "do not" in text:
            return True
        if "never" in request_words or "without" in request_words:
            return True
        if "not" in request_words and has_any(request_words, {"enter", "record", "schedule", "pay", "payment", "remove", "delete", "cancel", "hold", "dispute", "reject", "move", "change", "update"}):
            return True
        if "no" in request_words and has_any(request_words, {"enter", "record", "schedule", "pay", "payment", "remove", "delete", "cancel", "hold", "dispute", "reject", "move", "change", "update"}):
            return True
        return False

    def is_forbidden(raw_text, request_words):
        if has_any(request_words, {"status", "reminder", "remind", "delete", "remove", "cancel", "hold", "reject", "dispute", "reschedule", "postpone", "delay", "change", "changed", "update", "updated"}):
            return True
        if "move" in request_words and has_any(request_words, {"payment", "scheduled", "schedule", "invoice"}):
            return True
        if ("has" in request_words or "have" in request_words or "is" in request_words or "was" in request_words or "did" in request_words) and "yet" in request_words:
            if has_any(request_words, {"entered", "scheduled", "done", "recorded"}):
                return True
        if "what" in request_words and "status" in request_words:
            return True
        if ("did" in request_words or "already" in request_words) and has_any(request_words, {"schedule", "scheduled", "enter", "entered", "record", "recorded"}):
            return True
        if ("which" in request_words or "where" in request_words or "who" in request_words) and has_any(request_words, {"email", "address", "contact", "remittance", "advice"}):
            return True
        if has_negation(raw_text, request_words) and has_any(request_words, {"enter", "record", "schedule", "pay", "payment", "remove", "delete", "cancel", "hold", "dispute", "reject", "move", "change", "update"}):
            return True
        return False

    def is_schedule_request(request_words):
        if has_any(request_words, {"schedule", "scheduled", "pay", "paid", "payment"}):
            return True
        if "set" in request_words and ("up" in request_words or "out" in request_words) and has_any(request_words, {"payment", "pay", "invoice"}):
            return True
        if "work" in request_words and "out" in request_words and has_any(request_words, {"owe", "owed", "due", "when"}) and has_any(request_words, {"schedule", "scheduled", "payment", "pay"}):
            return True
        return False

    def is_quote_request(request_words):
        if has_any(request_words, {"owe", "owed", "due"}):
            return True
        if "what" in request_words and "when" in request_words and not has_any(request_words, {"schedule", "scheduled", "pay", "paid", "payment"}):
            return True
        return False

    def is_entry_request(request_words):
        if has_any(request_words, {"enter", "entered", "record", "recorded"}):
            if has_any(request_words, {"document", "doc", "invoice", "ledger"}):
                return True
        return False

    found = await kit.recall(request, k=12)
    if len(found) == 0:
        return {"handoff": "nothing learned applies"}

    request_words = set(words(request))
    request_lower = request.lower()

    if is_forbidden(request_lower, request_words):
        chosen = best_read_only(found, request_words, True)
        if chosen is not None:
            return {"serve": chosen["name"]}
        return {"handoff": "request is outside the acted-on jobs"}

    if is_schedule_request(request_words):
        chosen = pick_by_name(found, ["invoice_payment_schedule"])
        if chosen is not None:
            return {"serve": chosen["name"]}
        chosen = best_memory(found, request_words, require_read_only=False)
        if chosen is not None:
            return {"serve": chosen["name"]}

    if is_entry_request(request_words):
        chosen = pick_by_name(found, ["vendor_invoice_entry"])
        if chosen is not None:
            return {"serve": chosen["name"]}
        chosen = best_memory(found, request_words, require_read_only=False)
        if chosen is not None:
            return {"serve": chosen["name"]}

    if is_quote_request(request_words):
        chosen = pick_by_name(found, ["invoice_payment_quote"], require_read_only=True)
        if chosen is not None:
            return {"serve": chosen["name"]}
        chosen = best_read_only(found, request_words, False)
        if chosen is not None:
            return {"serve": chosen["name"]}

    chosen = best_memory(found, request_words)
    if chosen is not None:
        return {"serve": chosen["name"]}

    chosen = best_read_only(found, request_words, False)
    if chosen is not None:
        return {"serve": chosen["name"]}

    return {"handoff": "nothing learned applies"}
"""


async def learn(lab):
    if len(lab.memories) > 0:
