ACTION_MARKERS = (
    "enter ",
    "record ",
    "enter into",
    "record into",
    "enter in",
    "record in",
    "enter the",
    "record the",
    "enter doc",
    "record doc",
    "enter document",
    "record document",
)

PRIMARY_PATTERN = "(?:enter|record)[^\\n]{0,80}(?:doc[- ]*[0-9]+|document[ ]*[0-9]+)"
DOC_PATTERN = "(?:doc[- ]*[0-9]+|document[ ]*[0-9]+)"

STATUS_MARKERS = (
    "status",
    "approved",
    "approval",
    "delete",
    "deleted",
    "reversal",
    "reverse",
    "dispute",
    "disputed",
    "entered yet",
    "recorded yet",
)

NEGATION_MARKERS = (
    "don't enter",
    "don't record",
    "do not enter",
    "do not record",
    "not enter",
    "not record",
)

CONNECTORS = ("but", "however", "except", "instead")


async def decide(request, kit):
    low = request.lower()

    def has_any(words, text):
        for word in words:
            if word in text:
                return True
        return False

    def normalize_doc(match):
        digits = ""
        for ch in match:
            if ch >= "0" and ch <= "9":
                digits += ch
        if digits == "":
            return ""
        if len(digits) < 3:
            digits = ("0" * (3 - len(digits))) + digits
        return "DOC-" + digits

    def collect(pattern):
        found = kit.find(pattern, low)
        out = []
        seen = set()
        for item in found:
            docid = normalize_doc(item)
            if docid != "" and docid not in seen:
                seen.add(docid)
                out.append(docid)
        return out

    action = False
    for marker in ACTION_MARKERS:
        if marker in low:
            action = True
            break

    if not action:
        if "?" in request or has_any(STATUS_MARKERS, low):
            return {
                "handoff": "This is a status or other non-entry question.",
                "read_only": True,
            }
        return {"handoff": "No vendor invoice entry or record request was identified."}

    if has_any(NEGATION_MARKERS, low) and not has_any(CONNECTORS, low):
        return {
            "handoff": "The request negates the entry action.",
            "read_only": True,
        }

    ids = collect(PRIMARY_PATTERN)
    if len(ids) == 0:
        ids = collect(DOC_PATTERN)

    if len(ids) == 0:
        return {"handoff": "I could not identify a document id to enter or record."}

    if len(ids) > 1:
        state = {"request": request, "candidates": ids}
        questions = {
            "target": {
                "type": "choice",
                "instructions": "Choose the document id to enter or record. If none fit, choose none.",
                "criteria": dict([(item, "the document id to use") for item in ids] + [("none", "none of these")]),
            }
        }
        answer = await kit.ask(state, questions)
        target = answer["target"]["choice"]
        if target == "none" or target not in ids:
            return {"handoff": "I could not determine which document to enter or record."}
        docid = target
    else:
        docid = ids[0]

    parsed = await kit.procedure("parse_invoice", doc_id=docid)
    if not isinstance(parsed, dict) or "error" in parsed:
        return {"handoff": "parse_invoice failed or the document was missing."}

    return {
        "action": "record_invoice",
        "arguments": parsed,
        "reply": "Recorded " + parsed["doc_id"] + " in the ledger.",
    }
