RECORD_PHRASES = (
    "record the vendor invoice",
    "record vendor invoice",
    "record the invoice",
    "record invoice",
    "record in the ledger",
    "record into the ledger",
    "add to the ledger",
    "put in the ledger",
    "please enter",
    "enter doc",
    "enter document",
    "enter invoice",
    "enter the document",
    "enter the invoice",
)

NEG_PHRASES = (
    "don't schedule",
    "do not schedule",
    "don’t schedule",
    "don't set up",
    "do not set up",
    "don’t set up",
    "don't enter",
    "do not enter",
    "don’t enter",
    "hold the payment",
    "hold payment",
    "cancel the payment",
    "cancel payment",
    "delete",
    "reverse",
    "dispute",
)

MEMORY_NAME = "invoice_payment_schedule"

MEMORY_TEXT = (
    "The invoice id in tools is written as INV-###, not a bare number. "
    "First call amount_payable(invoice_id), then call schedule_payment with the same invoice_id "
    "plus the returned amount_usd and pay_on. Do not guess the amount or date yourself. "
    "Do not use unsupported read tools. If amount_payable fails because the invoice is not entered, "
    "stop and hand off instead of scheduling."
)


async def decide(request, kit):
    def hand(reason, ro, route, memory):
        out = {"handoff": reason}
        if ro:
            out["read_only"] = True
        if route:
            out["route"] = route
        if memory:
            out["memory"] = memory
        return out

    async def choose(kind, items):
        options = list(items)
        criteria = {}
        for item in options:
            criteria[item] = "the target " + kind
        criteria["none"] = "no candidate clearly fits"
        state = {"request": request, "kind": kind, "candidates": options}
        questions = {
            "pick": {
                "type": "choice",
                "instructions": "Choose the " + kind + " the user wants. Pick none if no candidate clearly fits.",
                "criteria": criteria,
            }
        }
        ans = await kit.ask(state, questions)
        if isinstance(ans, dict):
            pick = ans.get("pick")
            if isinstance(pick, dict):
                choice = pick.get("choice")
                if choice in criteria:
                    return choice
        return None

    lower = request.lower()
    upper = request.upper()

    schedule_like = any(phrase in lower for phrase in SCHEDULE_PHRASES)
    record_like = (
        ("record" in lower and ("invoice" in lower or "document" in lower or "vendor" in lower))
        or (("please enter" in lower or "enter doc" in lower or "enter document" in lower or "enter invoice" in lower or "enter the document" in lower or "enter the invoice" in lower) and "ledger" in lower)
        or ("add to the ledger" in lower)
        or ("put in the ledger" in lower)
        or ("record in the ledger" in lower)
        or ("record into the ledger" in lower)
    )
    neg_like = any(phrase in lower for phrase in NEG_PHRASES)

    if neg_like:
        return hand("request negates or blocks the action", True, "low", "")

    if schedule_like and record_like:
        return hand("request mixes payment scheduling and invoice entry", False, "medium", "")

    if schedule_like:
        candidates = kit.find("INV-[0-9]+", upper)
        target = None
        if len(candidates) == 1:
            target = candidates[0]
        elif len(candidates) > 1:
            target = await choose("invoice id", candidates)
        if not target or target == "none":
            return hand("no clear invoice id was provided", False, "medium", MEMORY_TEXT)
        try:
            pay = await kit.procedure("amount_payable", invoice_id=target)
        except Exception as e:
            return hand("amount_payable failed for " + target + ": " + str(e), False, "medium", MEMORY_TEXT)
        if not isinstance(pay, dict) or "error" in pay:
            message = ""
            if isinstance(pay, dict):
                message = pay.get("error", "")
            else:
                message = str(pay)
            return hand("amount_payable failed for " + target + ": " + message, False, "medium", MEMORY_TEXT)
        if pay.get("invoice_id") != target or "amount_usd" not in pay or "pay_on" not in pay:
            return hand("amount_payable returned incomplete data for " + target, False, "medium", MEMORY_TEXT)
        return {
            "action": "schedule_payment",
            "arguments": pay,
            "reply": "Scheduling payment for " + target + ".",
        }

    if record_like:
        candidates = kit.find("DOC-[0-9]+", upper)
        target = None
        if len(candidates) == 1:
            target = candidates[0]
        elif len(candidates) > 1:
            target = await choose("document id", candidates)
        if not target or target == "none":
            return hand("no clear document id was provided", False, "medium", "")
        try:
            rec = await kit.procedure("parse_invoice", doc_id=target)
        except Exception as e:
            return hand("parse_invoice failed for " + target + ": " + str(e), False, "medium", "")
        if not isinstance(rec, dict) or "error" in rec:
            message = ""
            if isinstance(rec, dict):
                message = rec.get("error", "")
            else:
                message = str(rec)
            return hand("parse_invoice failed for " + target + ": " + message, False, "medium", "")
        need = (
            "doc_id",
            "invoice_number",
            "po_number",
            "invoice_date",
            "subtotal_usd",
            "freight_usd",
            "discount_percent",
            "discount_days",
            "net_days",
        )
        if not all(key in rec for key in need):
            return hand("parse_invoice returned incomplete data for " + target, False, "medium", "")
        if rec.get("doc_id") != target:
            return hand("parse_invoice returned the wrong document id for " + target, False, "medium", "")
        return {
            "action": "record_invoice",
            "arguments": rec,
            "reply": "Recording " + target + " in the ledger.",
        }

    return hand("request is not a supported schedule-payment or invoice-entry action", True, "low", "")
