    def choose_read_only():
        if has_any(text, STATUS_WORDS):
            if memory_ok("out_of_scope_status_or_change"):
                return "out_of_scope_status_or_change"
        if has_any(text, QUOTE_WORDS):
            if memory_ok("invoice_payment_quote"):
                return "invoice_payment_quote"
        return ""

    if has_any(text, STATUS_WORDS):
        fallback = choose_read_only()
        if fallback:
