    if len(candidates) == 0:
        nums = kit.find("\\b\\d{1,3}\\b", text)
        candidates = unique([normalize_doc(x) for x in nums])

    if len(candidates) == 0:
        return ""

    if len(candidates) == 1:
        return candidates[0]

    criteria = {}
    for cand in candidates:
        criteria[cand] = "The document id to enter"
    criteria["none"] = "None of the options fit"

