PROGRAM_ROUNDS = 4
THRESHOLD = "0.8"


def distance(reward):
    if reward is None:
        return 1
    if reward >= 0.99:
        return 0
    if reward >= 0.5:
        return 0.4
    if reward > 0:
        return 1
    return 3


def total(results):
    return sum(distance(r["reward"]) for r in results)


def wrongs(results):
    return len([r for r in results if r["reward"] is not None and r["reward"] <= 0])


def quote(text):
    s = str(text).replace("\\", "\\\\").replace('"', '\\"').replace("\n", " ").replace("\r", " ")
    return '"' + s + '"'


def build_router(memories):
    acting = []
    readonly = []
    for m in memories:
        item = "    [" + quote(m["name"]) + ", " + quote(m.get("description", "")) + "],"
        if m.get("read_only", False):
            readonly.append(item)
        else:
            acting.append(item)
    head = "THRESHOLD = " + THRESHOLD + "\n"
    head = head + "ACTING = [\n" + "\n".join(acting) + "\n]\n"
    head = head + "READONLY = [\n" + "\n".join(readonly) + "\n]\n"
    return head + ROUTER_BODY


def extract(reply):
    text = str(reply)
    if "```" in text:
        parts = text.split("```")
        if len(parts) >= 3:
            block = parts[1]
            lines = block.split("\n")
            if len(lines) > 0 and "def " not in lines[0] and len(lines[0].strip()) < 20:
                lines = lines[1:]
            text = "\n".join(lines)
    if text.find("async def decide") < 0:
        return None
    return text.strip() + "\n"


async def measure(lab, source, ids):
    results = []
    for tid in ids:
        try:
            outcome = await lab.practice(source, tid)
            reward = outcome[0]
            reason = outcome[1]
            name = outcome[2] if len(outcome) > 2 else None
        except Exception as error:
            reward = 0.25
            reason = "program failed: " + str(error)
            name = None
        results.append({"id": tid, "reward": reward, "reason": reason, "name": name})
    return results


def request_text(lab, tid):
    try:
        return str(lab.request(tid))
    except Exception:
        return str(tid)


def tag_of(labels, tid):
    should = labels.get(tid)
    if should is True:
        return "should act"
    if should is False:
        return "should NOT act"
    return "unknown"


def describe_failures(lab, results, labels):
    lines = []
    for r in results:
        if distance(r["reward"]) <= 0:
            continue
        lines.append("- [" + tag_of(labels, r["id"]) + "] " + request_text(lab, r["id"]) + " -> memory "
                     + str(r["name"]) + ", reward " + str(r["reward"]) + ": " + str(r["reason"]))
    if len(lines) == 0:
        return ""
    return "A previous version got these requests wrong or left them to the language model; fix them:\n" + "\n".join(lines[:30])


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    memories = []
    if len(lab.memories) > 0:
        for memory in lab.memories:
            memories.append(dict(memory))
    else:
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
        for kind in lab.parse(reply):
            memories.append({
                "name": kind["name"],
                "description": kind["description"],
                "body": kind["guidance"],
                "route": "none",
                "read_only": not kind["acts"],
            })
    for memory in memories:
        lab.remember(**memory)

    labels = {}
    ids = []
    for test in lab.tests:
        labels[test["id"]] = test["should_act"]
        ids.append(test["id"])
    if len(ids) == 0:
        ids = list(lab.stream())
    ids = ids[:40]

    listing = "\n".join(
        "- " + m["name"] + " (route " + str(m.get("route", "none")) + ", read_only "
        + str(bool(m.get("read_only", False))) + "): " + str(m.get("description", ""))
        for m in memories
    )

    router = build_router(memories)
    best = await measure(lab, router, ids)
    lab.note("built router distance " + str(total(best)) + " wrong " + str(wrongs(best)))
    failures = describe_failures(lab, best, labels)
    if total(best) > 0:
        try:
            reply = await lab.ask(lab.fill(ROUTER_PROMPT, contract=lab.contract, memories=listing,
                                           current=router, failures=failures))
            source = extract(reply)
            if source is not None:
                results = await measure(lab, source, ids)
                if wrongs(results) <= wrongs(best) and total(results) < total(best):
                    router = source
                    best = results
                    lab.note("writer router kept, distance " + str(total(best)))
        except Exception as error:
            lab.note("router attempt failed: " + str(error))

    counts = {}
    for r in best:
        if r["reward"] is not None and r["reward"] >= 0.5 and r["reward"] < 0.99 and r["name"] is not None:
            counts[r["name"]] = counts.get(r["name"], 0) + 1
    target = None
    for memory in memories:
        if memory.get("read_only", False) or memory.get("route", "none") == "program":
            continue
        if counts.get(memory["name"], 0) > 0:
            if target is None or counts[memory["name"]] > counts[target["name"]]:
                target = memory
    if target is None:
        return router

    original = dict(target)
    target_ids = [r["id"] for r in best if r["name"] == target["name"]]
    baseline = [r for r in best if r["name"] == target["name"]]
    targets = "\n".join("- [" + tag_of(labels, tid) + "] " + request_text(lab, tid) for tid in target_ids)
    failures = ""
    chosen = None
    chosen_results = baseline
    for round_index in range(PROGRAM_ROUNDS):
        try:
            reply = await lab.ask(lab.fill(
                PROGRAM_PROMPT,
                contract=lab.contract,
                name=original["name"],
                description=str(original.get("description", "")),
                body=str(original.get("body", "")),
                targets=targets,
                episodes=shown,
                failures=failures,
            ))
        except Exception as error:
            lab.note("program writer failed: " + str(error))
            continue
        source = extract(reply)
        if source is None:
            continue
        candidate = dict(original)
        candidate["body"] = source
        candidate["route"] = "program"
        candidate["read_only"] = False
        try:
            lab.remember(**candidate)
            results = await measure(lab, router, target_ids)
        except Exception as error:
            lab.note("program trial failed: " + str(error))
            results = None
        if results is not None and wrongs(results) <= wrongs(baseline) and total(results) < total(chosen_results):
            chosen = candidate
            chosen_results = results
            if total(results) <= 0:
                break
        if results is not None:
            failures = describe_failures(lab, results, labels)
        if failures == "" and results is not None:
            failures = "The previous version still left some of these requests to the language model."

    if chosen is not None:
        lab.remember(**chosen)
        lab.note("moved " + original["name"] + " to a decision program; distance on its requests "
                 + str(total(chosen_results)) + " from " + str(total(baseline)))
    else:
        lab.remember(**original)
        lab.note("kept " + original["name"] + " with the language model")
    return router
