"""Memories of how the work went, a router that asks Jev whether a request really asks for an acting memory's
action, and one acting memory moved from the language model to a decision program.

Every change is written by the writer from the contract, tried with lab.practice on the shared requests, and kept
only if it scores at least as well as what it replaces.
"""

KINDS_PROMPT = """{contract}

Below are runs where the assistant, a language model, handled requests for
this job: each request, every tool call with its result, and the verdict.
Some requests are worded oddly, some should not be acted on at all, and
some runs went wrong.

List the kinds of request these runs show, and for each write what the
assistant should know the next time it meets one: how ids are really
written in the tools, which tools to call and in what order, and the
mistakes to avoid. Use as few kinds as cover the runs. Include one kind
for requests that should not be acted on (questions, status checks, undoing,
holding, changing or any other action outside the job).

Reply with only a JSON list. Each item has the keys "name" (short, in
snake_case), "description" (which requests belong to this kind, and which
similar ones don't), "guidance" (what the assistant should know), and
"acts" (true if a request of this kind should end in an action, false if
it should only be answered or passed on).

{episodes}"""

ROUTER_PROMPT = """{contract}

Write the routing program for this job. It picks which memory serves each
request. The memories are:

{memories}

Write `async def decide(request, kit)` that:
- calls `await kit.recall(request, 4)` to get candidate memories (dicts with
  "name", "description", "route", "read_only");
- asks Jev, exactly as the contract describes, to judge which candidate the
  request belongs to. A memory that is not read_only may be chosen only when
  Jev judges that the request asks, right now, for exactly the action that
  memory describes. A question, a status check, a request to undo, hold,
  delay, change, cancel, reject, remind, or to do any other action than the
  one the memory describes, is NOT that action;
- when no acting memory fits, returns {{"serve": "{fallback}"}}, a read-only
  memory, so the request is handed off read-only;
- otherwise returns {{"serve": name}} of the chosen memory.

Never decide what a request asks for by looking for words in it; ask Jev.
No imports, no names starting with an underscore, no bare except, no
str.format. The only builtins allowed are: {builtins}.
Reply with only the program in one python code block.
{failures}"""

PROGRAM_PROMPT = """{contract}

Write a decision program that serves requests of this kind with no
language model:

name: {name}
description: {description}
what is known about doing it: {guidance}

Here are runs of the assistant on requests for this job, with every tool
call and result and the verdict:

{episodes}

Write `async def decide(request, kit)` following the contract: find ids
with code and write them as the tools really write them (the runs show the
form), ask Jev for any judgment code cannot make exactly, call the tools in
the order the successful runs show, and return the action as the contract
says. If Jev judges the request is not asking for exactly this action now,
or an id cannot be found, or a tool result is not what the runs show,
hand off as the contract says instead of acting: a wrong action is far
worse than a hand-off. Never decide what a request asks for by looking for
words in it; ask Jev. No imports, no names starting with an underscore, no
bare except, no str.format. The only builtins allowed are: {builtins}.
Reply with only the program in one python code block.
{failures}"""

FAILURES_HEAD = """
A previous version did this on these requests; fix it:
{lines}"""

BUILTINS = "Exception, KeyError, TypeError, ValueError, abs, all, any, bool, dict, divmod, enumerate, filter, float, int, isinstance, len, list, map, max, min, range, reversed, round, set, sorted, str, sum, tuple, zip"

ROUTER = """async def decide(request, kit):
    found = await kit.recall(request, k=1)
    if len(found) == 0:
        return {"handoff": "nothing learned applies"}
    return {"serve": found[0]["name"]}
"""

FALLBACK_NAME = "outside_the_job"
FALLBACK_DESCRIPTION = "Requests that should not be acted on: questions, status checks, and requests to undo, hold, change, or do anything other than the actions this job performs."
FALLBACK_BODY = "Do not act. Answer from what can be read, or pass the request on."


def extract_code(reply):
    if "```" not in reply:
        return reply.strip() + "\n"
    parts = reply.split("```")
    for i in range(1, len(parts), 2):
        block = parts[i]
        if block.startswith("python"):
            block = block[6:]
        if "async def decide" in block:
            return block.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[6:]
    return block.strip() + "\n"


def task_ids(lab):
    if len(lab.tests) > 0:
        return [t["id"] for t in lab.tests]
    ids = list(lab.stream())
    return ids[:24]


async def measure(lab, source, ids):
    total = 0.0
    rows = []
    for tid in ids:
        try:
            result = await lab.practice(source, tid)
        except Exception as error:
            rows.append({"id": tid, "reward": 0.0, "reason": str(error), "name": None})
            total = total - 2.0
            continue
        reward = result[0]
        if reward <= 0:
            total = total - 2.0
        else:
            total = total + reward
        rows.append({"id": tid, "reward": reward, "reason": result[1], "name": result[2]})
    return total, rows


def failure_text(lab, rows):
    lines = []
    for row in rows:
        if row["reward"] < 1:
            lines.append("- " + str(lab.request(row["id"]))[:300] + " -> served by " + str(row["name"]) + ": " + str(row["reason"])[:300])
    if len(lines) == 0:
        return ""
    return lab.fill(FAILURES_HEAD, lines="\n".join(lines[:14]))


def memory_lines(memories):
    lines = []
    for m in memories:
        lines.append("- " + m["name"] + " (route " + str(m["route"]) + ", read_only " + str(bool(m["read_only"])) + "): " + str(m["description"]))
    return "\n".join(lines)


def shown_episodes(lab):
    parts = []
    for e in lab.episodes:
        parts.append(lab.render(e)[:3000])
    return "\n\n".join(parts[:20])


async def learn(lab):
    memories = []
    if len(lab.memories) > 0:
        for memory in lab.memories:
            memories.append(dict(memory))
    else:
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown_episodes(lab)))
        kinds = []
        try:
            kinds = lab.parse(reply)
        except ValueError:
            kinds = []
        for kind in kinds:
            memories.append({"name": kind["name"], "description": kind["description"], "body": kind["guidance"],
                             "route": "none", "read_only": not kind["acts"]})
    fallback = None
    for m in memories:
        if m["read_only"] and fallback is None:
            fallback = m["name"]
    if fallback is None:
        memories.append({"name": FALLBACK_NAME, "description": FALLBACK_DESCRIPTION, "body": FALLBACK_BODY,
                         "route": "none", "read_only": True})
        fallback = FALLBACK_NAME
    for m in memories:
        lab.remember(**m)

    ids = task_ids(lab)
    router = ROUTER
    best, rows = await measure(lab, router, ids)
    failures = failure_text(lab, rows)
    for attempt in range(2):
        if failures == "":
            break
        reply = await lab.ask(lab.fill(ROUTER_PROMPT, contract=lab.contract, memories=memory_lines(memories),
                                       fallback=fallback, builtins=BUILTINS, failures=failures))
        candidate = extract_code(reply)
        score, crows = await measure(lab, candidate, ids)
        if score > best:
            best = score
            router = candidate
            rows = crows
        failures = failure_text(lab, crows)
    lab.note("router score " + str(best))

    counts = {}
    for row in rows:
        if row["name"] is not None and row["reward"] > 0.3 and row["reward"] < 1:
            counts[row["name"]] = counts.get(row["name"], 0) + 1
    target = None
    most = 0
    for m in memories:
        if not m["read_only"] and m["route"] != "program":
            c = counts.get(m["name"], 0)
            if c > most:
                most = c
                target = m
    if target is None:
        return router

    failures = ""
    for attempt in range(2):
        reply = await lab.ask(lab.fill(PROGRAM_PROMPT, contract=lab.contract, name=target["name"],
                                       description=target["description"], guidance=target["body"],
                                       episodes=shown_episodes(lab), builtins=BUILTINS, failures=failures))
        program = extract_code(reply)
        lab.remember(target["name"], target["description"], program, route="program", read_only=False)
        score, prows = await measure(lab, router, ids)
        if score >= best:
            lab.note("moved " + target["name"] + " to a program, score " + str(score))
            return router
        mine = [r for r in prows if r["name"] == target["name"]]
        failures = failure_text(lab, mine)
        lab.remember(**target)
    return router

