            name = item.get("name")
            if isinstance(name, str) and name not in seen:
                seen.add(name)
                candidates.append(item)

    criteria = {}
    for item in candidates:
        name = item.get("name")
        if isinstance(name, str):
            description = item.get("description")
            route = item.get("route")
            read_only = item.get("read_only")
            criteria[name] = str(description) + " | route=" + str(route) + " | read_only=" + str(read_only)

    criteria["none"] = "No candidate memory fits this request."

    state = {"request": request, "candidates": candidates}
    questions = {
        CHOICE_NAME: {
            "type": "choice",
            "instructions": "Choose the single best memory for the request. Choose a memory only if the request is exactly for that memory's work. Choose invoice_payment_quote only for requests that only ask what is owed and/or when it is due, without asking to schedule payment. Choose invoice_payment_schedule only for requests that ask to schedule payment for an invoice already in the ledger, including combined phrasing. Choose vendor_invoice_entry only for requests to enter or record a vendor invoice document into the ledger. Choose out_of_scope_status_or_change for status checks, questions, cancellations, disputes, deletions, reminders, vendor questions, or any other request outside the two jobs. If nothing fits, choose none.",
            "criteria": criteria
        }
    }

    judgment = await kit.ask(state, questions)
    answer = judgment.get(CHOICE_NAME)
    choice = None
    if isinstance(answer, dict):
        choice = answer.get("choice")

    if choice is None or choice == "none":
        return {"serve": QUOTE_MEMORY}
    if choice not in criteria:
        return {"serve": QUOTE_MEMORY}
    return {"serve": choice}
