SCHEDULE = "schedule_payment"
RECORD = "record_invoice"
READ_ONLY = "read_only"
OTHER = "other"
NONE = "none"

INV_PATTERN = "INV-[0-9]+"
DOC_PATTERN = "DOC-[0-9]+"

SCHEDULE_MEMORY = "For payment scheduling, invoice ids are written as INV-###. Call amount_payable first, then schedule_payment with the returned amount_usd and pay_on. If amount_payable fails because the invoice is not entered, stop and hand off."
RECORD_MEMORY = "For ledger entry, document ids are written as DOC-###. Call parse_invoice first, then record_invoice with the parsed record. If parsing fails, stop and hand off."
READ_ONLY_MEMORY = "This request is read-only or outside the payment-scheduling and invoice-entry jobs. Answer it without taking any action."

async def decide(request, kit):
    async def choose_id(kind, pattern, memory):
        candidates = kit.find(pattern, request)
        if len(candidates) == 0:
            return NONE
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "This is the " + kind + " id the user means."
        criteria[NONE] = "None of these clearly fits."
        answer = await kit.ask(
            {"request": request, "candidates": candidates, "memory": memory},
            {
                "pick": {
                    "type": "choice",
                    "instructions": "Choose the single " + kind + " id the user means. If none fits, choose none.",
                    "criteria": criteria,
                }
            },
        )
        choice = answer["pick"]["choice"]
        if choice in candidates:
            return choice
        return NONE

    intent_answer = await kit.ask(
        {"request": request},
        {
            "intent": {
                "type": "choice",
                "instructions": "Classify the request as the likeliest supported job.",
                "criteria": {
                    SCHEDULE: "The user wants a payment scheduled for an invoice already in the ledger.",
                    RECORD: "The user wants a vendor invoice document entered into the ledger.",
                    READ_ONLY: "The user wants information only, or another read-only answer.",
                    OTHER: "None of these.",
                },
            }
        },
    )
    intent = intent_answer["intent"]["choice"]

    if intent == SCHEDULE:
        invoice_id = await choose_id("invoice", INV_PATTERN, SCHEDULE_MEMORY)
        if invoice_id == NONE:
            return {
                "handoff": "No invoice id could be chosen for payment scheduling.",
                "read_only": True,
                "route": "low",
                "memory": SCHEDULE_MEMORY,
            }
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict):
            return {
                "handoff": "amount_payable did not return a usable result.",
                "read_only": True,
                "route": "low",
                "memory": SCHEDULE_MEMORY,
            }
        if payable.get("invoice_id") != invoice_id:
            return {
                "handoff": "amount_payable returned a mismatched invoice id.",
                "read_only": True,
                "route": "low",
                "memory": SCHEDULE_MEMORY,
            }
        if "error" in payable or "amount_usd" not in payable or "pay_on" not in payable:
            return {
                "handoff": "amount_payable could not produce a schedulable amount.",
                "read_only": True,
                "route": "low",
                "memory": SCHEDULE_MEMORY,
            }
        scheduled = await kit.procedure(
            "schedule_payment",
            invoice_id=invoice_id,
            amount_usd=payable["amount_usd"],
            pay_on=payable["pay_on"],
        )
        if not isinstance(scheduled, dict) or scheduled.get("status") != "scheduled" or scheduled.get("invoice_id") != invoice_id:
            return {
                "handoff": "schedule_payment did not confirm the scheduling.",
                "read_only": True,
                "route": "low",
                "memory": SCHEDULE_MEMORY,
            }
        return {
            "action": SCHEDULE,
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": payable["amount_usd"],
                "pay_on": payable["pay_on"],
            },
            "reply": "Payment scheduled for " + invoice_id + ".",
        }

    if intent == RECORD:
        doc_id = await choose_id("document", DOC_PATTERN, RECORD_MEMORY)
        if doc_id == NONE:
            return {
                "handoff": "No document id could be chosen for ledger entry.",
                "read_only": True,
                "route": "low",
                "memory": RECORD_MEMORY,
            }
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict):
            return {
                "handoff": "parse_invoice did not return a usable invoice record.",
                "read_only": True,
                "route": "low",
                "memory": RECORD_MEMORY,
            }
        if parsed.get("doc_id") != doc_id or "error" in parsed:
            return {
                "handoff": "parse_invoice could not parse that document.",
                "read_only": True,
                "route": "low",
                "memory": RECORD_MEMORY,
            }
        recorded = await kit.procedure("record_invoice", **parsed)
        if not isinstance(recorded, dict) or recorded.get("status") != "recorded" or recorded.get("doc_id") != doc_id:
            return {
                "handoff": "record_invoice did not confirm the ledger entry.",
                "read_only": True,
                "route": "low",
                "memory": RECORD_MEMORY,
            }
        return {
            "action": RECORD,
            "arguments": parsed,
            "reply": "Invoice recorded for " + doc_id + ".",
        }

    return {
        "handoff": "This request is read-only or outside the payment-scheduling and invoice-entry jobs.",
        "read_only": True,
        "route": "low",
        "memory": READ_ONLY_MEMORY,
    }
