invoicePattern = "INV-[0-9]+|[0-9]+"
noneOption = "none"
amountName = "amount_payable"

async def decide(request, kit):
    def normalize(value):
        if isinstance(value, str) and value.startswith("INV-"):
            return value
        if isinstance(value, str) and value.isdigit():
            return "INV-" + value.zfill(3)
        return value

    questions = {
        "job": {
            "type": "noul",
            "instructions": "Is the user asking to schedule payment for an invoice already in the ledger, rather than asking about invoice status, amount due, cancellation, a vendor, or some other task?"
        }
    }
    state = {"request": request}
    result = await kit.ask(state, questions)
    serve = result["job"]["noul"]

    if serve < 0.7:
        return {
            "handoff": "the request is not clearly asking to schedule an invoice payment",
            "read_only": True
        }

    candidates = kit.find(invoicePattern, request)
    if len(candidates) == 0:
        return {
            "handoff": "no invoice id could be found for payment scheduling"
        }

    criteria = {}
    for candidate in candidates:
        criteria[candidate] = "this is the invoice id to schedule payment for"
    criteria[noneOption] = "no invoice id fits"

    choice = await kit.ask(
        {"request": request, "candidates": candidates},
        {
            "invoice": {
                "type": "choice",
                "instructions": "Pick the invoice id the user wants scheduled. Use none if no candidate clearly fits.",
                "criteria": criteria
            }
        }
    )

    selected = choice["invoice"]["choice"]
    if selected == noneOption:
        return {
            "handoff": "no invoice id could be chosen for payment scheduling"
        }

    invoiceId = normalize(selected)
    if not isinstance(invoiceId, str) or not invoiceId.startswith("INV-"):
        return {
            "handoff": "no valid invoice id could be chosen for payment scheduling"
        }

    try:
        amount = await kit.procedure(amountName, invoice_id=invoiceId)
    except Exception:
        return {
            "handoff": "the payable amount could not be retrieved for the chosen invoice"
        }

    if not isinstance(amount, dict):
        return {
            "handoff": "the payable amount result was not in the expected format"
        }
    if "error" in amount:
        return {
            "handoff": "the invoice is not entered in the ledger"
        }
    if amount.get("invoice_id") != invoiceId:
        return {
            "handoff": "the payable amount result did not match the chosen invoice"
        }
    if "amount_usd" not in amount or "pay_on" not in amount:
        return {
            "handoff": "the payable amount result was missing required fields"
        }

    amountUsd = float(amount["amount_usd"])
    payOn = str(amount["pay_on"])

    return {
        "action": "schedule_payment",
        "arguments": {
            "invoice_id": invoiceId,
            "amount_usd": amountUsd,
            "pay_on": payOn
        },
        "reply": "Payment scheduled for " + invoiceId + " on " + payOn + "."
