PATTERNS = (
    "inv-[0-9]{1,3}",
    "inv[ ]*[0-9]{1,3}",
    "invoice[ ]*inv-[0-9]{1,3}",
    "invoice[ ]*[0-9]{1,3}",
)

def normalizeInvoiceId(token):
    digits = ""
    for ch in token:
        if ch >= "0" and ch <= "9":
            digits = digits + ch
    if digits == "":
        return ""
    if len(digits) == 1:
        digits = "00" + digits
    elif len(digits) == 2:
        digits = "0" + digits
    elif len(digits) > 3:
        digits = digits[-3:]
    return "INV-" + digits

def collectInvoiceIds(text, kit):
    items = []
    for pattern in PATTERNS:
        matches = kit.find(pattern, text)
        for match in matches:
            invoice_id = normalizeInvoiceId(match)
            if invoice_id != "" and invoice_id not in items:
                items.append(invoice_id)
    return items

def handoff(reason):
    return {"handoff": reason, "read_only": True}

async def decide(request, kit):
    text = request.lower()
    candidates = collectInvoiceIds(text, kit)

    if len(candidates) == 0:
        return handoff("No invoice id could be identified for scheduling.")

    invoice_id = candidates[0]
    if len(candidates) > 1:
        questions = {
            "pick": {
                "type": "choice",
                "instructions": "Choose which invoice id in the request should be scheduled. If none should be acted on, choose none.",
                "criteria": dict([(candidate, "Act on " + candidate) for candidate in candidates] + [("none", "No invoice should be scheduled")]),
            }
        }
        judgment = await kit.ask({"request": request, "candidates": candidates}, questions)
        choice = judgment["pick"]["choice"]
        if choice == "none" or choice not in candidates:
            return handoff("The request mentioned multiple invoice ids and I could not determine which one to schedule.")
        invoice_id = choice

    try:
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
    except Exception as e:
        return handoff("Could not get the payable amount for " + invoice_id + ": " + str(e))

    if not isinstance(payable, dict):
        return handoff("Could not get the payable amount for " + invoice_id + ".")
    if "error" in payable:
        return handoff("Could not get the payable amount for " + invoice_id + ": " + str(payable["error"]))
    if "amount_usd" not in payable or "pay_on" not in payable:
        return handoff("The payable amount result for " + invoice_id + " was incomplete.")

    amount_usd = payable["amount_usd"]
    pay_on = payable["pay_on"]

    return {
        "action": "schedule_payment",
        "arguments": {
            "invoice_id": invoice_id,
            "amount_usd": amount_usd,
            "pay_on": pay_on,
        },
        "reply": "Payment scheduled for " + invoice_id + ".",
    }
