```python
PUNCTUATION = [",", ".", "?", "!", ":", ";", "(", ")", "[", "]", "{", "}", "\"", "'", "’", "—", "–", "\n", "\t"]
RECORD_WORDS = ["enter", "record"]
SCHEDULE_WORDS = ["schedule", "scheduled"]
SET_WORDS = ["set", "up"]
STATUS_WORDS = ["status", "cancel", "cancelling", "canceled", "dispute", "disputing", "void", "hold", "held"]


def clean_words(text):
    s = text.lower()
    for p in PUNCTUATION:
        s = s.replace(p, " ")
    return s.split()


def pad_id(text):
    if len(text) < 3:
        return ("000" + text)[-3:]
    return text


def maybe_int(value):
    if isinstance(value, float):
        if int(value) == value:
            return int(value)
    return value


def pick_target(words, kind):
    ids = []
    short = kind.lower()
    noun = "document" if kind == "DOC" else "invoice"
    for i, w in enumerate(words):
        candidate = None
        if w.startswith(short + "-"):
            body = w.split("-", 1)[1]
            if body:
                if body.isdigit():
                    candidate = kind + "-" + pad_id(body)
                else:
                    candidate = kind + "-" + body
        elif w == short or w == noun:
            if i + 1 < len(words):
                nxt = words[i + 1]
                if nxt.startswith(short + "-"):
                    body = nxt.split("-", 1)[1]
                    if body:
                        if body.isdigit():
                            candidate = kind + "-" + pad_id(body)
                        else:
                            candidate = kind + "-" + body
                elif nxt.isdigit():
                    candidate = kind + "-" + pad_id(nxt)
        if candidate is not None and candidate not in ids:
            ids.append(candidate)
    if len(ids) > 0:
        return ids[-1]
    return None


def wants_record(words):
    if any(w in words for w in RECORD_WORDS):
        return True
    if "ledger" in words and ("document" in words or "doc" in words):
        return True
    return False


def wants_schedule(words):
    if any(w in words for w in SCHEDULE_WORDS):
        return True
    if "set" in words and "up" in words and "payment" in words:
        return True
    if "pay" in words and "payment" in words:
        return True
    return False


async def decide(request, kit):
    words = clean_words(request)
    doc_id = pick_target(words, "DOC")
    invoice_id = pick_target(words, "INV")

    if any(w in words for w in STATUS_WORDS):
        return {"handoff": "This is a status or hold/cancel/dispute request, which must be handled by another agent."}

    if wants_record(words):
        if doc_id is None:
            return {"handoff": "No document id was found for the ledger-entry request."}
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "The document could not be parsed for ledger entry."}
        required = ["doc_id", "invoice_number", "po_number", "invoice_date", "subtotal_usd", "freight_usd", "discount_percent", "discount_days", "net_days"]
        if not all(key in parsed for key in required):
            return {"handoff": "The parsed invoice is missing required fields for ledger entry."}
        args = {
            "doc_id": parsed["doc_id"],
            "invoice_number": parsed["invoice_number"],
            "po_number": parsed["po_number"],
            "invoice_date": parsed["invoice_date"],
            "subtotal_usd": maybe_int(parsed["subtotal_usd"]),
            "freight_usd": maybe_int(parsed["freight_usd"]),
            "discount_percent": maybe_int(parsed["discount_percent"]),
            "discount_days": maybe_int(parsed["discount_days"]),
            "net_days": maybe_int(parsed["net_days"])
        }
        result = await kit.procedure("record_invoice", **args)
        if isinstance(result, dict) and result.get("status") == "recorded":
            return {"action": "record_invoice", "arguments": args, "reply": "Recorded " + str(args["doc_id"]) + " in the ledger."}
        return {"handoff": "The invoice could not be recorded."}

    if wants_schedule(words):
        if invoice_id is None:
            return {"handoff": "No invoice id was found for the payment-scheduling request."}
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "The invoice could not be priced for scheduling."}
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "The payable amount response was incomplete."}
        args = {
            "invoice_id": payable["invoice_id"],
            "amount_usd": maybe_int(payable["amount_usd"]),
            "pay_on": payable["pay_on"]
        }
        result = await kit.procedure("schedule_payment", **args)
        if isinstance(result, dict) and result.get("status") == "scheduled":
            return {"action": "schedule_payment", "arguments": args, "reply": "Scheduled payment for " + str(args["invoice_id"]) + "."}
        return {"handoff": "The payment could not be scheduled."}

    if invoice_id is not None and ("due" in words or "owe" in words or "what" in words):
        return {"handoff": "Amount-due requests belong in the quote kind instead."}

    return {"handoff": "This request is outside the invoice-entry and payment-scheduling jobs."}
