```python
DIGITS = "0123456789"
STATUSPHRASES = (
    "status",
    "already scheduled",
    "been scheduled",
    "has the payment",
    "was the payment",
    "did we already schedule",
    "who approved",
    "approved",
    "late",
    "hold",
    "held",
    "cancel",
    "canceled",
    "cancelled",
    "dispute",
    "disputed",
    "reminder",
    "move the scheduled payment",
    "reschedule",
    "postpone",
    "delay",
    "next month",
    "don't pay",
    "do not pay",
    "dont pay",
    "not pay"
)
DUEPHRASES = (
    "amount due",
    "what we owe",
    "what do we owe",
    "owe on",
    "owe for",
    "how much do we owe",
    "how much is due",
    "what is due"
)

def hasphrase(text, phrases):
    return any(phrase in text for phrase in phrases)

def scheduleintent(text):
    return (
        "schedule" in text
        or (("set up" in text or "setup" in text) and "payment" in text)
        or ("pay" in text and ("invoice" in text or "payment" in text))
        or "make payment" in text
        or "arrange payment" in text
    )

def lastdigits(text):
    digits = ""
    for ch in reversed(text.strip()):
        if ch in DIGITS:
            digits = ch + digits
        elif digits != "":
            break
    return digits

def normalizeid(text):
    digits = lastdigits(text)
    if digits != "":
        return "INV-" + digits
    return None

def extractids(text, kit):
    raw = kit.find("[Ii][Nn][Vv]-\\d+|[Ii]nvoice\\s*#?\\s*\\d+", text)
    if len(raw) == 0:
        raw = kit.find("\\b\\d{3}\\b", text)
    ids = []
    seen = set()
    for item in raw:
        norm = normalizeid(item)
        if norm is not None and norm not in seen:
            seen.add(norm)
            ids.append(norm)
    return ids

async def decide(request, kit):
    text = request.lower()

    if hasphrase(text, STATUSPHRASES):
        return {
            "handoff": "This is a status, hold, cancel, dispute, or similar request, which must be handled read-only by another agent.",
            "read_only": True
        }

    if (not scheduleintent(text)) and hasphrase(text, DUEPHRASES):
        return {
            "handoff": "This asks only for the amount due, which belongs in the quote kind.",
            "read_only": True
        }

    if not scheduleintent(text):
        return {
            "handoff": "This request is outside invoice payment scheduling.",
            "read_only": True
        }

    ids = extractids(request, kit)
    if len(ids) == 0:
        return {
            "handoff": "I couldn't identify a single invoice id to schedule."
        }

    state = {"request": request, "candidates": ids}
    questions = {
        "now": {
            "type": "noul",
            "instructions": "Does the request really ask to schedule the payment now, rather than asking about status or something else?"
        }
    }

    if len(ids) > 1:
        questions["which"] = {
            "type": "choice",
            "instructions": "Which invoice id in `candidates` is the one to schedule payment for? Choose one candidate or none.",
            "criteria": dict(
                (
                    candidate,
                    "This is the invoice to schedule payment for."
                )
                for candidate in ids
            ) | {"none": "No candidate fits."}
        }

    answers = await kit.ask(state, questions)
    now = answers["now"]["noul"]
    if now < 0.3:
        return {
            "handoff": "This does not look like a request to schedule payment now."
        }
    if now <= 0.7:
        return {
            "handoff": "It is unclear whether this request is asking to schedule payment now."
        }

    chosen = ids[0]
    if len(ids) > 1:
        if "which" not in answers:
            return {
                "handoff": "I couldn't determine which invoice to schedule."
            }
        chosen = answers["which"]["choice"]
        if chosen == "none" or chosen not in ids:
            return {
                "handoff": "I couldn't determine which invoice to schedule."
            }

    payable = await kit.procedure("amount_payable", invoice_id=chosen)
    if not isinstance(payable, dict) or "error" in payable:
        return {
            "handoff": "The invoice could not be priced for scheduling."
        }
    if "amount_usd" not in payable or "pay_on" not in payable or "invoice_id" not in payable:
        return {
            "handoff": "The payable amount response was incomplete."
        }

    args = {
        "invoice_id": payable["invoice_id"],
        "amount_usd": float(payable["amount_usd"]),
        "pay_on": payable["pay_on"]
    }
    scheduled = await kit.procedure("schedule_payment", **args)
    if isinstance(scheduled, dict) and scheduled.get("status") == "scheduled":
        return {
            "action": "schedule_payment",
            "arguments": args,
            "reply": "Scheduled payment for " + str(args["invoice_id"]) + "."
        }

    return {
        "handoff": "The payment could not be scheduled."
    }
