        if len(text) == 1:
            return "T-00" + text
        if len(text) == 2:
            return "T-0" + text
        return "T-" + text

    def chooseCandidate(candidates, stateLabel):
        if len(candidates) == 1:
            return candidates[0]
        options = dict()
        for candidate in candidates:
            options[candidate] = "This is a candidate trip id."
        options["none"] = "None of these."
        answer = await kit.ask(
