def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    start_month = trip.get("start", "")[:7]
    rates = policy.get("company_rates_usd_per_unit", {}).get(start_month, {})
    city_policy = policy.get("allowances_usd", {}).get(trip.get("city", ""), {})

    meal_limit = float(city_policy.get("meals_per_day", 0.0))
    hotel_limit = float(city_policy.get("hotel_per_night", 0.0))

    meals = {}
    hotels = {}
    other_total = 0.0

    def to_usd(amount, currency):
        currency = str(currency).upper()
        if currency == "USD":
            return float(amount)
        return float(amount) * float(rates.get(currency, 1.0))

    for receipt in trip.get("receipts", []):
        note = receipt.get("note", "")
        if note is None:
            note = ""
        else:
            note = str(note)

        if "alcohol" in note.lower():
            continue

        amount = receipt.get("amount", 0.0)
        currency = receipt.get("currency", "USD")
        usd = to_usd(amount, currency)

        category = str(receipt.get("category", "")).lower()

        if category == "meal":
            day = receipt.get("date", "")
