def reimbursable_total(api, trip_id: str) -> dict:
    def to_number(value):
        if isinstance(value, int) or isinstance(value, float):
            return float(value)
        if isinstance(value, str):
            text = value.strip()
            if text:
                try:
                    return float(text)
                except ValueError:
                    return None
        return None

    def find_value(obj, keys):
        if isinstance(obj, dict):
            for key in keys:
                if key in obj:
                    return obj[key]
            for value in obj.values():
                found = find_value(value, keys)
                if found is not None:
                    return found
        elif isinstance(obj, list):
            for value in obj:
                found = find_value(value, keys)
                if found is not None:
                    return found
        return None

    def normalize_text(value):
        if isinstance(value, str):
            return value.strip().lower()
        return ""

    def get_candidate(source, keys):
        if isinstance(source, dict):
            for key in keys:
                if key in source:
                    return source[key]
        return None

    def get_rate(source, currency):
        code = normalize_text(currency).upper()
        if not code:
            return None
        if isinstance(source, dict):
            for key, value in source.items():
                if isinstance(key, str) and key.strip().upper() == code:
                    rate = to_number(value)
                    if rate is not None:
                        return rate
            for key in ["exchange_rates", "rates", "currency_rates"]:
                if key in source:
                    rate = get_rate(source[key], currency)
                    if rate is not None:
                        return rate
        elif isinstance(source, list):
            for item in source:
                rate = get_rate(item, currency)
                if rate is not None:
                    return rate
        return None

    def is_receipt_item(item):
        if not isinstance(item, dict):
            return False
        amount = find_value(item, ["amount", "value", "total", "cost", "price", "sum"])
        return to_number(amount) is not None

    def normalize_receipts(value):
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            values = list(value.values())
            good = []
            for item in values:
                if is_receipt_item(item):
                    good.append(item)
            if len(good) > 0:
                return good
        return None

    def find_receipts(obj):
        if isinstance(obj, dict):
            for key in ["receipts", "expenses", "items", "charges", "receipts_list"]:
                if key in obj:
                    receipts = normalize_receipts(obj[key])
                    if receipts is not None:
                        return receipts
            for value in obj.values():
                receipts = find_receipts(value)
                if receipts is not None:
                    return receipts
        elif isinstance(obj, list):
            good = True
            if len(obj) == 0:
                good = False
            else:
                for item in obj:
                    if not is_receipt_item(item):
                        good = False
                        break
            if good:
                return obj
            for value in obj:
                receipts = find_receipts(value)
                if receipts is not None:
                    return receipts
        return None

    def lookup_city_entry(source, city):
        city_key = normalize_text(city)
        if not city_key:
            return None
        if isinstance(source, dict):
            for key, value in source.items():
                if isinstance(key, str) and normalize_text(key) == city_key:
                    return value
            for key in ["allowances", "allowance", "city_allowances", "cities"]:
                if key in source:
                    found = lookup_city_entry(source[key], city)
                    if found is not None:
                        return found
        elif isinstance(source, list):
            for item in source:
                if isinstance(item, dict):
                    name = find_value(item, ["city", "name", "location"])
                    if isinstance(name, str) and normalize_text(name) == city_key:
                        if "amount" in item or "value" in item or "total" in item:
                            return item
                        return item
                found = lookup_city_entry(item, city)
                if found is not None:
                    return found
        return None

    def entry_amount_and_currency(entry):
        if isinstance(entry, int) or isinstance(entry, float) or isinstance(entry, str):
            amount = to_number(entry)
            if amount is not None:
                return amount, "USD"
            return None, None
        if isinstance(entry, dict):
            amount = find_value(entry, ["amount", "value", "total", "limit", "cap", "sum"])
            currency = find_value(entry, ["currency", "curr", "ccy", "code"])
            amount = to_number(amount)
            if amount is None:
                return None, None
            if not isinstance(currency, str):
                currency = "USD"
            return amount, currency
        return None, None

    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = find_value(trip, ["city", "destination", "location", "trip_city", "place"])
    receipts = find_receipts(trip)
    if receipts is None:
        receipts = []

    rates_source = get_candidate(policy, ["exchange_rates", "rates", "currency_rates"])
    if rates_source is None:
        rates_source = policy

    total = 0.0
    for receipt in receipts:
        amount = find_value(receipt, ["amount", "value", "total", "cost", "price", "sum"])
        currency = find_value(receipt, ["currency", "curr", "ccy", "code"])
        amount = to_number(amount)
        if amount is None:
            continue
        if not isinstance(currency, str):
            currency = "USD"
        rate = get_rate(rates_source, currency)
        if rate is None:
            rate = 1.0
        total += amount * rate

    allowance_source = get_candidate(policy, ["allowances", "allowance", "city_allowances", "cities"])
    if allowance_source is None:
        allowance_source = policy

    if isinstance(city, str):
        allowance_entry = lookup_city_entry(allowance_source, city)
        if allowance_entry is None:
            allowance_entry = lookup_city_entry(policy, city)
        if allowance_entry is not None:
            allowance_amount, allowance_currency = entry_amount_and_currency(allowance_entry)
            if allowance_amount is not None:
                allowance_rate = get_rate(rates_source, allowance_currency)
                if allowance_rate is None:
                    allowance_rate = 1.0
                allowance_usd = allowance_amount * allowance_rate
                if total > allowance_usd:
                    total = allowance_usd

    return {"total_usd": round(total, 2)}
