    intent = judge.get('intent')
    target = judge.get('target')
    if not isinstance(intent, dict) or not isinstance(target, dict):
        return handoff('Could not judge the request.')

    if noul_state(intent.get('noul')) != 'yes':
        return handoff('This is not a clear request to file one claim now.')

    choice = target.get('choice')
