async def decide(request, kit):
    readonly = "read_only_question_or_out_of_scope"
    direct = "direct_shift_change"
    weekly = "weekly_rota_plan_and_publish"
    acting = [direct, weekly]
    descriptions = {
        direct: "Requests to put one named person on one named day's shift, or to move that day's shift to a new person. This includes terse forms like \"Wed: Noor\", \"Mon: Omar\", and phrasing with filler such as \"Leave Lena alone. Put Omar on Monday.\" It does not include whole-rota planning or questions about who is on call.",
        weekly: "Requests to plan next week's rota and publish it, usually with constraints like who must work, who must not work certain days, one-shift or two-shift limits, and ordering constraints such as one person's first shift needing to come before another's. This is the whole-week scheduling job, not a single-day change."
    }
    try:
        check = await kit.ask(
            {"request": request},
            {
                "change": {
                    "type": "noul",
                    "instructions": "Does this request, plainly and right now, ask for a change that this job does? Say no for questions about the current state, previews or plans that should not be published, hypotheticals, reminders for later, requests to hold off, undo, or wait, things the user says they already did, and anything outside the job. Say yes when a change is asked for, even if it is phrased as an offer someone made, tersely, or with filler around it."
                }
            }
        )
        p = check["change"]["noul"]
        if not isinstance(p, (int, float)):
            return {"serve": readonly}
        if p < 0.5:
            return {"serve": readonly}
    except Exception:
        return {"serve": readonly}

    recalled = []
    try:
        recalled = await kit.recall(request, 2)
    except Exception:
        recalled = []

    items = []
    if isinstance(recalled, list):
        items = recalled
    elif isinstance(recalled, dict):
        if "candidates" in recalled and isinstance(recalled["candidates"], list):
            items = recalled["candidates"]
        else:
            items = [recalled]

    names = []
    seen = set()
    for item in items:
        name = None
        if isinstance(item, str):
            name = item
        elif isinstance(item, dict):
            if "name" in item and isinstance(item["name"], str):
                name = item["name"]
        if name in descriptions and name not in seen:
            seen.add(name)
            names.append(name)

    for name in acting:
        if name not in seen:
            seen.add(name)
            names.append(name)

    criteria = {}
    for name in names:
        criteria[name] = descriptions[name]
    criteria["none"] = "none of these"

    try:
        pick = await kit.ask(
            {"request": request, "recalled": recalled},
            {
                "memory": {
                    "type": "choice",
                    "instructions": "Choose the acting memory that best fits this request. direct_shift_change is for one named person on one named day's shift. weekly_rota_plan_and_publish is for next week's full rota planning and publishing. If none fits, choose none.",
                    "criteria": criteria
                }
            }
        )
        choice = pick["memory"]["choice"]
        if choice in descriptions:
            return {"serve": choice}
        return {"serve": acting[0]}
    except Exception:
        return {"serve": readonly}
