        if not isinstance(personConfidence, (int, float)) or personConfidence < 0.7:
            return {"handoff": "I couldn't identify a single team member to assign."}

        person = personChoice

    if len(dayCandidates) == 1:
        day = dayCandidates[0]
    else:
        dayCriteria = {}
        for cand in dayCandidates:
            dayCriteria[cand] = cand
        dayCriteria["none"] = "none fits"

        try:
            dayAnswer = await kit.ask(
                {"request": request, "candidates": dayCandidates},
                {
                    "day": {
                        "type": "choice",
                        "instructions": "Choose the weekday to change from `candidates`. If none fits, choose none.",
                        "criteria": dayCriteria
                    }
