        if not isinstance(dayAnswer, dict):
            return {"handoff": "I couldn't identify a single weekday to change."}

        dayData = dayAnswer.get("day")
        if not isinstance(dayData, dict):
            return {"handoff": "I couldn't identify a single weekday to change."}

        dayChoice = dayData.get("choice")
        dayConfidence = dayData.get("confidence")
        if dayChoice == "none" or dayChoice not in dayCandidates:
            return {"handoff": "I couldn't identify a single weekday to change."}
        if not isinstance(dayConfidence, (int, float)) or dayConfidence < 0.7:
            return {"handoff": "I couldn't identify a single weekday to change."}

        day = dayChoice

    try:
        result = await kit.procedure("assign_shift", day=day, person=person)
    except Exception:
        return {"handoff": "I couldn't complete the shift change."}

    if not isinstance(result, dict) or result.get("status") != "assigned":
        return {"handoff": "I couldn't complete the shift change."}

    return {
        "action": "assign_shift",
        "arguments": {"day": day, "person": person},
        "reply": "Done — " + person + " is on " + day + "."
    }
