DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
DAYPATTERN = r'(?i)\b(?:mon(?:day)?|tue(?:s(?:day)?)?|wed(?:nesday)?|thu(?:r(?:s(?:day)?)?)?|fri(?:day)?)\b'
NAMEPATTERN = r'\b[A-Z][a-z]+\b'
FAILURE_STATUSES = {"error", "failed", "failure", "rejected", "invalid"}


async def decide(request, kit):
    def unique(items):
        out = []
        seen = set()
        for item in items:
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out

    def canonical_day(token):
        text = token.lower()
        if text.startswith("mon"):
            return "Monday"
        if text.startswith("tue"):
            return "Tuesday"
        if text.startswith("wed"):
            return "Wednesday"
        if text.startswith("thu"):
            return "Thursday"
        if text.startswith("fri"):
            return "Friday"
        return None

    def team_names(team):
        names = []
        if isinstance(team, dict):
            people = team.get("people")
            if isinstance(people, dict):
                for name in people.keys():
                    names.append(str(name))
            elif isinstance(people, list):
                for person in people:
                    if isinstance(person, str):
                        names.append(person)
                    elif isinstance(person, dict):
                        name = person.get("name")
                        if isinstance(name, str):
                            names.append(name)
            else:
                for key, value in team.items():
                    if key in ("rules", "standing_rules", "skills"):
                        continue
                    if isinstance(value, dict):
                        names.append(str(key))
        elif isinstance(team, list):
            for person in team:
                if isinstance(person, str):
                    names.append(person)
                elif isinstance(person, dict):
                    name = person.get("name")
                    if isinstance(name, str):
                        names.append(name)
        return unique(names)

    def extract_days(text):
        found = []
        for token in kit.find(DAYPATTERN, text):
            day = canonical_day(token)
            if day is not None:
                found.append(day)
        return unique(found)

    def extract_people(text, names):
        found = []
        lower_map = {}
        for name in names:
            lower_map[str(name).lower()] = str(name)

        for token in kit.find(NAMEPATTERN, text):
            key = token.lower()
            if key in lower_map:
                found.append(lower_map[key])

        if len(found) == 0:
            lower_text = text.lower()
            for name in names:
                if str(name).lower() in lower_text:
                    found.append(str(name))

        return unique(found)

    async def pick_choice(state, key, instructions, candidates):
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = candidate
        criteria["none"] = "none fits"

        try:
            answer = await kit.ask(
                state,
                {
                    key: {
                        "type": "choice",
                        "instructions": instructions,
                        "criteria": criteria,
                    }
                },
            )
        except Exception:
            return None

        if not isinstance(answer, dict):
            return None

        data = answer.get(key)
        if not isinstance(data, dict):
            return None

        choice = data.get("choice")
        if choice == "none" or choice not in criteria:
            return None

        return choice

    try:
        intent_answer = await kit.ask(
            {"request": request},
            {
                "intent": {
                    "type": "choice",
                    "instructions": (
                        "Choose the single best description of what the user wants. "
                        "assign_shift means one named person is being put or moved onto one named day's shift. "
                        "plan_rota means the user wants next week's Monday-Friday rota planned or published. "
                        "info means the whole request is only asking who is on a day or for rota information, and nothing else. "
                        "other means it is not one of the supported actions, or it combines rota information with another task such as lunch, passwords, channels, holding, drafting, or undoing. "
                        "none means nothing fits."
                    ),
                    "criteria": {
                        "assign_shift": "one named person onto one named day's shift",
                        "plan_rota": "plan or publish next week's rota",
                        "info": "rota information only",
                        "other": "outside the supported actions",
                        "none": "cannot tell",
                    },
                }
            },
        )
    except Exception:
        return {"handoff": "I couldn't judge the request type."}

    if not isinstance(intent_answer, dict):
        return {"handoff": "I couldn't judge the request type."}

    intent_data = intent_answer.get("intent")
    if not isinstance(intent_data, dict):
        return {"handoff": "I couldn't judge the request type."}

    intent = intent_data.get("choice")
    if intent == "info":
        return {"handoff": "This request asks for information rather than a change.", "read_only": True}
    if intent == "other":
        return {"handoff": "This request is outside the on-call desk actions.", "read_only": True}
    if intent not in ("assign_shift", "plan_rota"):
        return {"handoff": "I couldn't judge the request type."}

    if intent == "assign_shift":
        try:
            team = kit.read("team")
        except Exception:
            return {"handoff": "I couldn't identify the team."}

        names = team_names(team)
        day_candidates = extract_days(request)
        person_candidates = extract_people(request, names)

        if len(day_candidates) == 0 or len(person_candidates) == 0:
            return {"handoff": "I couldn't identify both a day and a person."}

        if len(day_candidates) == 1:
            day = day_candidates[0]
        else:
            day = await pick_choice(
                {"request": request, "candidates": day_candidates, "people": person_candidates},
                "day",
                "Choose the weekday the request means from `candidates`. If none fits, choose none.",
                day_candidates,
            )
            if day is None:
                return {"handoff": "I couldn't identify a single weekday to change."}

        if len(person_candidates) == 1:
            person = person_candidates[0]
        else:
            person = await pick_choice(
                {"request": request, "day": day, "candidates": person_candidates},
                "person",
                "Choose the person the request means from `candidates`. If none fits, choose none.",
                person_candidates,
            )
            if person is None:
                return {"handoff": "I couldn't identify a single team member to assign."}

        try:
            avail = await kit.procedure("available_people", day=day)
        except Exception:
            return {"handoff": "I couldn't verify availability for that day."}

        if not isinstance(avail, dict):
            return {"handoff": "I couldn't verify availability for that day."}

        available = avail.get("people")
        if not isinstance(available, list):
            return {"handoff": "I couldn't verify availability for that day."}

        if person not in available:
            return {"handoff": "I couldn't complete the shift change."}

        try:
            result = await kit.procedure("assign_shift", day=day, person=person)
        except Exception:
            return {"handoff": "I couldn't complete the shift change."}

        if not isinstance(result, dict):
            return {"handoff": "I couldn't complete the shift change."}

        status = result.get("status")
        if status in FAILURE_STATUSES:
            return {"handoff": "I couldn't complete the shift change."}

        return {
            "action": "assign_shift",
            "arguments": {"day": day, "person": person},
            "reply": "Done — " + person + " is on " + day + ".",
        }

    try:
        team = kit.read("team")
        leave = kit.read("leave")
        rota = kit.read("rota")
    except Exception:
        return {"handoff": "I couldn't read the rota data."}

    partial = {}
    published = {}

    for day in DAYS:
        try:
            avail = await kit.procedure("available_people", day=day)
        except Exception:
            return {"handoff": "I couldn't verify availability for " + day + "."}

        if not isinstance(avail, dict):
            return {"handoff": "I couldn't verify availability for " + day + "."}

        available = avail.get("people")
        if not isinstance(available, list):
            return {"handoff": "I couldn't verify availability for " + day + "."}

        candidates = []
        for person in available:
            if isinstance(person, str):
                candidates.append(person)
        candidates = unique(candidates)

        if len(candidates) == 0:
            return {"handoff": "I couldn't build a valid rota."}

        if len(candidates) == 1:
            chosen = candidates[0]
        else:
            chosen = await pick_choice(
                {
                    "request": request,
                    "team": team,
                    "leave": leave,
                    "rota": rota,
                    "partial": partial,
                    "day": day,
                    "candidates": candidates,
                },
                day.lower(),
                "Choose the best person for " + day + " in next week's rota from `candidates`, considering the request, team rules, leave, current rota, and the partial rota already chosen. If none fits, choose none.",
                candidates,
            )
            if chosen is None:
                return {"handoff": "I couldn't build a valid rota."}

        published[day.lower()] = chosen
        partial[day.lower()] = chosen

    try:
        result = await kit.procedure(
            "publish_rota",
            monday=published["monday"],
            tuesday=published["tuesday"],
            wednesday=published["wednesday"],
            thursday=published["thursday"],
            friday=published["friday"],
        )
    except Exception:
        return {"handoff": "I couldn't publish the rota."}

    if not isinstance(result, dict):
        return {"handoff": "I couldn't publish the rota."}

    status = result.get("status")
    if status in FAILURE_STATUSES:
        return {"handoff": "I couldn't publish the rota."}

    return {
        "action": "publish_rota",
        "arguments": {
            "monday": published["monday"],
            "tuesday": published["tuesday"],
            "wednesday": published["wednesday"],
            "thursday": published["thursday"],
            "friday": published["friday"],
        },
        "reply": "Done — next week's rota is published.",
    }
