        choice = pick["memory"]["choice"]
    except Exception:
        return {"serve": READONLY}
    if choice in criteria and choice != "none":
        return {"serve": choice}
    return {"serve": READONLY}
"""

READONLY_NAME = "not_to_act_on"
READONLY_DESCRIPTION = ("Requests that must not be acted on: questions about the current state, previews, "
                        "hypotheticals, reminders, requests to hold off or undo, things already done, and anything "
                        "outside the job.")
READONLY_BODY = "Answer from what can be read, or say it is outside this job. Change nothing."

MAX_ASKS = 8


def quote(text):
    s = str(text).replace("\\", "\\\\").replace('"', '\\"').replace("\n", " ").replace("\r", " ")
    return '"' + s + '"'


def clean(reply):
    text = str(reply)
    start = text.find("async def decide")
    if start < 0:
        return ""
    text = text[start:]
    end = text.find("```")
    if end >= 0:
        text = text[:end]
    return text.strip() + "\n"


async def trial(lab, source, ids):
    out = []
    for tid in ids:
        try:
            got = await lab.practice(source, tid)
            out.append([tid, got[0], got[1], got[2]])
        except Exception as err:
            out.append([tid, 0, "error: " + str(err), None])
    return out


def total(results):
    return sum(r[1] for r in results)


def report(lab, results):
    lines = []
    for r in results:
        lines.append(str(lab.request(r[0])) + " -> " + str(r[1]) + ", " + str(r[2]) + ", " + str(r[3]))
    return "\n".join(lines)


def build_router(memories, readonly):
    parts = []
    for m in memories:
        if not m.get("read_only"):
            parts.append(str(m["name"]) + ": " + str(m["description"]))
    job = "This job does only these kinds of change. " + " | ".join(parts)
    return "READONLY = " + quote(readonly) + "\nJOB = " + quote(job) + "\n" + ROUTER_BODY


async def learn(lab):
    asks = 0
    memories = []
    if len(lab.memories) > 0:
        for memory in lab.memories:
            memories.append(dict(memory))
    else:
        shown = "\n\n".join(lab.render(e) for e in lab.episodes)
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
        asks = asks + 1
        for kind in lab.parse(reply):
            memories.append({"name": kind["name"], "description": kind["description"], "body": kind["guidance"],
                             "route": "none", "read_only": not kind["acts"]})

    readonly = ""
    for m in memories:
        if m.get("read_only") and readonly == "":
            readonly = m["name"]
    if readonly == "":
        readonly = READONLY_NAME
        memories.append({"name": READONLY_NAME, "description": READONLY_DESCRIPTION, "body": READONLY_BODY,
                         "route": "none", "read_only": True})
    for m in memories:
        lab.remember(**m)

    if len(lab.tests) > 0:
        ids = [t["id"] for t in lab.tests]
    else:
        ids = list(lab.stream())

    router = build_router(memories, readonly)
    best = await trial(lab, router, ids)
    if total(best) < 0.5 * len(ids):
        plain = await trial(lab, ROUTER, ids)
        if total(plain) > total(best):
            router = ROUTER
            best = plain
    lab.note("router reward " + str(total(best)) + " of " + str(len(ids)))

    gaps = dict()
    for r in best:
        if r[3] is not None and r[1] < 0.95:
            gaps[r[3]] = gaps.get(r[3], 0) + (1 - r[1])
    targets = []
    for m in memories:
        if m.get("route") != "program" and not m.get("read_only") and gaps.get(m["name"], 0) > 0:
            targets.append(m)
    targets = sorted(targets, key=lambda m: -gaps.get(m["name"], 0))

    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    for target in targets:
        if asks >= MAX_ASKS - 1:
            break
        before = [r for r in best if r[3] == target["name"]]
        ids_t = [r[0] for r in before]
        failures = report(lab, before)
        reply = await lab.ask(lab.fill(PROGRAM_PROMPT, contract=lab.contract, name=target["name"],
                                       description=target["description"], guidance=target["body"],
                                       failures=failures, episodes=shown))
        asks = asks + 1
        program = clean(reply)
        kept = False
        best_prog = None
        best_res = before
        attempts = 0
        while program != "" and attempts < 3 and not kept:
            attempts = attempts + 1
            lab.remember(target["name"], target["description"], program, route="program", read_only=False)
            res = await trial(lab, router, ids_t)
            new_wrong = 0
            for i in range(len(res)):
                if res[i][1] < 0.05 and before[i][1] > 0.05:
                    new_wrong = new_wrong + 1
            if new_wrong == 0 and total(res) > total(best_res):
                best_prog = program
                best_res = res
                if total(res) >= len(ids_t) - 0.05:
                    kept = True
            if not kept and attempts < 3 and asks < MAX_ASKS:
                reply = await lab.ask(lab.fill(REPAIR_PROMPT, contract=lab.contract, source=program,
                                               report=report(lab, res)))
                asks = asks + 1
                program = clean(reply)
            elif not kept:
                break
        if best_prog is not None:
            lab.remember(target["name"], target["description"], best_prog, route="program", read_only=False)
            lab.note("program for " + target["name"] + " kept, reward " + str(total(best_res)))
        else:
            lab.remember(**target)
            lab.note("program for " + target["name"] + " not kept")
    return router
