    kind, kindconf = answerchoice(kindanswer.get("kind", {}))
    if kind != "one" or kindconf < 0.7:
        if kind in ("many", "other") and kindconf >= 0.7:
            return {"handoff": "This is not a single direct shift change request.", "read_only": True}
        return {"handoff": "I couldn't tell that this was one clear direct shift change."}

