    try:
        result = await kit.procedure("assign_shift", {"day": daychoice, "person": personchoice})
    except Exception:
        return {"handoff": "I couldn't complete the shift change."}

    if isinstance(result, dict) and result.get("status") == "assigned":
        return {
            "action": "assign_shift",
            "arguments": {"day": daychoice, "person": personchoice},
            "reply": "Done — " + personchoice + " is on " + daychoice + "."
        }

    return {"handoff": "I couldn't complete the shift change."}
