    for day in days:
        required = mustByDay[day]
        options = []
        if len(required) == 1:
            person = required[0]
            if person in people and day not in leaveMap.get(person, set()):
                options.append(person)
        else:
            for person in people:
                if day not in leaveMap.get(person, set()):
                    options.append(person)
        optionsByDay[day] = options

    peopleSet = set(people)
    plan = [None, None, None, None, None]
    counts = {}
    firsts = {}
    for person in people:
        counts[person] = 0
        firsts[person] = None

    def validPlan():
        for person in people:
            if counts[person] > limitMap[person]:
                return False
            if person in needSet and counts[person] < 1:
                return False
        for day in days:
            person = plan[dayIndex[day]]
            if person not in peopleSet:
                return False
            if day in leaveMap.get(person, set()):
                return False
            if (person, day) in forbidSet:
                return False
            required = mustByDay[day]
            if len(required) == 1 and required[0] != person:
                return False
            if len(required) > 1:
                return False
        for index in range(1, len(plan)):
            person = plan[index]
            prev = plan[index - 1]
            if person == prev and person in noConsecutive:
                return False
        for first, second in beforePairs:
            a = firsts[first]
            b = firsts[second]
            if a is None or b is None or a >= b:
                return False
        return True

    def search(index):
        if index == len(days):
            if validPlan():
                return list(plan)
            return None

        day = days[index]
        options = optionsByDay[day]
        for person in options:
            if counts[person] >= limitMap[person]:
                continue
            if index > 0 and plan[index - 1] == person and person in noConsecutive:
                continue
            oldCount = counts[person]
            oldFirst = firsts[person]
            plan[index] = person
            counts[person] = oldCount + 1
            if oldCount == 0:
                firsts[person] = index
            result = search(index + 1)
            counts[person] = oldCount
            firsts[person] = oldFirst
            if result is not None:
                return result
        plan[index] = None
        return None

    result = search(0)
    if result is None:
        return {"handoff": "No rota satisfies all the stated constraints and standing rules."}

    arguments = {
        "monday": result[0],
        "tuesday": result[1],
        "wednesday": result[2],
        "thursday": result[3],
        "friday": result[4]
    }

    return {
        "action": "publish_rota",
        "arguments": arguments,
        "reply": "Published next week's rota."
    }
