def names_in_text(text, names):
    hits = []
    for name in names:
        pos = text.find(name)
        if pos >= 0:
            hits.append((pos, name))
    hits = sorted(hits)
    result = []
    for _, name in hits:
        if name not in result:
            result.append(name)
    return result


def days_in_text(text):
    low = text.lower()
    hits = []
    for key in DAY_ALIASES:
        pos = low.find(key)
        if pos >= 0:
            hits.append((pos, DAY_ALIASES[key]))
    hits = sorted(hits)
    result = []
    for _, day in hits:
        if day not in result:
            result.append(day)
    return result


def parse_constraints(request, names):
    fixed_day = {}
    forbidden = {}
    max_shifts = {}
    no_consec = set()
    required = set()
    order_pairs = []

    segments = request.replace("\r", "\n").replace("\n", ".").split(".")
    for piece in segments:
        segment = piece.strip()
        if segment == "":
            continue

        lower = segment.lower()
        found_names = names_in_text(segment, names)
        found_days = days_in_text(segment)

        if "one shift at most" in lower:
            for name in found_names:
                max_shifts[name] = 1

        if "shouldn't work two days in a row" in lower or "should not work two days in a row" in lower:
            for name in found_names:
                no_consec.add(name)

        if "need a shift this week" in lower:
            for name in found_names:
                required.add(name)

        if "first shift has to come before" in lower and len(found_names) >= 2:
            order_pairs.append((found_names[0], found_names[1]))
            required.add(found_names[0])
            required.add(found_names[1])

        if "has to take" in lower and len(found_names) >= 1 and len(found_days) >= 1:
            fixed_day[found_names[0]] = found_days[0]
            required.add(found_names[0])

        if ("can't do" in lower or "cannot do" in lower or "can't take" in lower or "cannot take" in lower) and len(found_names) >= 1 and len(found_days) >= 1:
            for name in found_names:
                if name not in forbidden:
                    forbidden[name] = set()
                forbidden[name].add(found_days[0])

    fixed_by_day = {}
    for name in fixed_day:
        day = fixed_day[name]
        if day in fixed_by_day and fixed_by_day[day] != name:
            return None
        fixed_by_day[day] = name

    return {
        "fixed_day": fixed_day,
        "fixed_by_day": fixed_by_day,
        "forbidden": forbidden,
        "max_shifts": max_shifts,
        "no_consec": no_consec,
        "required": required,
        "order_pairs": order_pairs,
    }


def validate_rota(candidate, names, leave_map, parsed):
    counts = {}
    first_seen = {}
    previous = None

    fixed_day = parsed["fixed_day"]
    forbidden = parsed["forbidden"]
    max_shifts = parsed["max_shifts"]
    no_consec = parsed["no_consec"]
    required = parsed["required"]
    order_pairs = parsed["order_pairs"]

    for index, day in enumerate(DAY_ORDER):
        person = candidate[day]

        if person not in names:
            return False

        if day in forbidden.get(person, set()):
            return False

        if day in leave_map.get(person, []):
            return False

        if person in fixed_day and fixed_day[person] != day:
            return False

        counts[person] = counts.get(person, 0) + 1
        if counts[person] > max_shifts.get(person, 2):
            return False

        if person in no_consec and previous == person:
            return False

        if person not in first_seen:
            first_seen[person] = index

        previous = person

    for person in required:
        if counts.get(person, 0) < 1:
            return False

    for left, right in order_pairs:
        if counts.get(left, 0) < 1 or counts.get(right, 0) < 1:
            return False
        if first_seen[left] >= first_seen[right]:
            return False

    return True


def build_rota(names, leave_map, parsed):
    allowed = {}
    for day in DAY_ORDER:
        day_people = []
        for person in names:
            if day not in leave_map.get(person, []):
                if day not in parsed["forbidden"].get(person, set()):
                    day_people.append(person)
        allowed[day] = day_people

    candidate = {}

    def walk(index):
        if index == len(DAY_ORDER):
            if validate_rota(candidate, names, leave_map, parsed):
                return candidate.copy()
            return None

        day = DAY_ORDER[index]
        fixed_person = parsed["fixed_by_day"].get(day)

        for person in allowed[day]:
            if fixed_person is not None and person != fixed_person:
                continue
            candidate[day] = person
            result = walk(index + 1)
            if result is not None:
                return result

        return None

    return walk(0)


