    plan = []
    counts = {}
    found = [None]

    def validate(candidate):
        countsLocal = {}
        firstLocal = {}
        for idx in range(len(candidate)):
            person = candidate[idx]
            countsLocal[person] = countsLocal.get(person, 0) + 1
            if person not in firstLocal:
                firstLocal[person] = idx

        for person in people:
            if countsLocal.get(person, 0) > 2:
