        for person in maxone:
            if countsLocal.get(person, 0) > 1:
                return False

        for person in need:
            if countsLocal.get(person, 0) < 1:
                return False

        for person in fixed:
            day = fixed[person]
            if candidate[DAY_INDEX[day]] != person:
                return False

        for person in forbid:
            daysSet = forbid[person]
            for day in daysSet:
                if candidate[DAY_INDEX[day]] == person:
                    return False

        for person in noc:
            for idx in range(len(candidate) - 1):
                if candidate[idx] == person and candidate[idx + 1] == person:
                    return False

        for pair in order:
            a = pair[0]
            b = pair[1]
            if a not in firstLocal or b not in firstLocal:
                return False
            if firstLocal[a] >= firstLocal[b]:
                return False

        return True

    def search(index):
        if found[0] is not None:
