        if index == len(DAY_NAMES):
            if validate(plan):
                found[0] = list(plan)
            return

        day = DAY_NAMES[index]
        domain = domains.get(day, [])
        forced = None
        for person, forcedDay in fixed.items():
            if forcedDay == day:
                forced = person
                break

