            if counts.get(person, 0) >= 2:
                continue
            if person in maxone and counts.get(person, 0) >= 1:
                continue
            if person in noc and index > 0 and plan[index - 1] == person:
                continue
            plan.append(person)
            counts[person] = counts.get(person, 0) + 1
            search(index + 1)
            if found[0] is not None:
                return
            counts[person] -= 1
            if counts[person] == 0:
                del counts[person]
            plan.pop()

