    if found[0] is None:
        return {"handoff": "could not satisfy the rota constraints"}

    rota = {
        "monday": found[0][0],
        "tuesday": found[0][1],
        "wednesday": found[0][2],
        "thursday": found[0][3],
        "friday": found[0][4]
    }

    try:
