        if len(kit.find(nocPattern, requestLower)) > 0:
            noc.add(person)

        needPattern = "\\b" + nameLower + "\\b\\s+(?:needs?|must\\s+have|should\\s+have)\\s+a\\s+shift(?:\\s+this\\s+week)?"
        if len(kit.find(needPattern, requestLower)) > 0:
            need.add(person)

    for aLower in people:
        aPerson = nameLookup.get(aLower)
        if aPerson is None:
            continue
        for bLower in people:
            if aLower == bLower:
                continue
            bPerson = nameLookup.get(bLower)
            if bPerson is None:
                continue

            pairNeedPattern = "\\b" + aLower + "\\b\\s+and\\s+\\b" + bLower + "\\b\\s+both\\s+need\\s+a\\s+shift(?:\\s+this\\s+week)?"
            if len(kit.find(pairNeedPattern, requestLower)) > 0:
                need.add(aPerson)
                need.add(bPerson)

            orderPattern = "\\b" + aLower + "\\b's\\s+first\\s+shift\\s+has\\s+to\\s+come\\s+before\\s+\\b" + bLower + "\\b's"
            if len(kit.find(orderPattern, requestLower)) > 0:
                need.add(aPerson)
                need.add(bPerson)
                beforePairs.append((aPerson, bPerson))

    return {
        "fixedDay": fixedDay,
        "forbid": forbid,
        "need": need,
        "maxone": maxone,
        "noc": noc,
        "beforePairs": beforePairs,
        "fixedConflict": fixedConflict
    }

def orderOk(firstSeen, beforePairs):
    for pair in beforePairs:
        a = pair[0]
        b = pair[1]
        ia = firstSeen.get(a)
        ib = firstSeen.get(b)
        if ib is not None and ia is None:
            return False
        if ia is not None and ib is not None and ia >= ib:
            return False
    return True

async def decide(request, kit) -> dict:
    try:
        verdict = await kit.ask(
            {"request": request},
            {
                "kind": {
                    "type": "choice",
                    "instructions": "Classify the request. Choose assign if it asks to put exactly one named person on exactly one day's shift, or to move one day's shift to one named person. Choose publish if it asks to plan next week's rota and publish it. Choose other for questions, status checks, hypotheticals, undo/hold requests, or anything else.",
                    "criteria": {
                        "assign": "a direct one-day shift change for one named person",
                        "publish": "plan and publish next week's rota",
                        "other": "anything else"
                    }
                }
            }
        )
    except Exception:
        return {"handoff": "could not classify the request"}

    kind = choiceValue(verdict, "kind")
    if kind is None:
        return {"handoff": "could not classify the request"}

    if kind == "other":
        return {"handoff": "request is read-only or outside the job", "read_only": True}

    if kind == "assign":
        try:
            team = kit.read("team")
        except Exception:
            return {"handoff": "could not read team"}

        if not isinstance(team, dict):
            return {"handoff": "could not read team"}

        peopleMap = team.get("people")
        if not isinstance(peopleMap, dict) or len(peopleMap) == 0:
            return {"handoff": "could not read team"}

        people = sorted(list(peopleMap.keys()))
        peopleLower = []
        nameLookup = {}
        for person in people:
            lower = person.lower()
            peopleLower.append(lower)
            nameLookup[lower] = person

        requestLower = request.lower()
        namePattern = makeNamePattern(peopleLower)
        dayPattern = makeDayPattern()

        personCandidates = []
        for match in kit.find(namePattern, requestLower):
            person = nameLookup.get(match)
            if person is not None:
                uniqueAppend(personCandidates, person)

        dayCandidates = []
        for match in kit.find(dayPattern, requestLower):
            day = normalizeDay(match)
            if day is not None:
                uniqueAppend(dayCandidates, day)

        if len(personCandidates) == 0 or len(dayCandidates) == 0:
            return {"handoff": "could not identify the requested shift change"}

        if len(personCandidates) == 1:
            personPick = personCandidates[0]
        else:
            try:
                personAnswer = await kit.ask(
                    {"request": request, "people": personCandidates},
                    {
                        "person": {
                            "type": "choice",
                            "instructions": "Pick the one team member the request wants on the shift, using the candidate names found in the request. If none fit, choose none.",
                            "criteria": {personCandidates[0]: personCandidates[0]}
                        }
                    }
                )
            except Exception:
                return {"handoff": "could not identify the requested shift change"}
            personPick = choiceValue(personAnswer, "person")
            if personPick is None or personPick not in personCandidates:
                return {"handoff": "could not identify the requested shift change"}

        if len(dayCandidates) == 1:
            dayPick = dayCandidates[0]
        else:
            try:
                dayAnswer = await kit.ask(
                    {"request": request, "days": dayCandidates},
                    {
                        "day": {
                            "type": "choice",
                            "instructions": "Pick the one weekday the request wants, using the candidate days found in the request. If none fit, choose none.",
                            "criteria": {dayCandidates[0]: dayCandidates[0]}
                        }
                    }
                )
            except Exception:
                return {"handoff": "could not identify the requested shift change"}
            dayPick = choiceValue(dayAnswer, "day")
            if dayPick is None or dayPick not in dayCandidates:
                return {"handoff": "could not identify the requested shift change"}

        try:
            available = await kit.procedure("available_people", day=dayPick)
        except Exception:
            return {"handoff": "could not complete the shift change"}

        if not isinstance(available, dict):
            return {"handoff": "could not complete the shift change"}

        allowed = available.get("people")
        if not isinstance(allowed, list) or personPick not in allowed:
            return {"handoff": "could not complete the shift change"}

        try:
            result = await kit.procedure("assign_shift", day=dayPick, person=personPick)
        except Exception:
            return {"handoff": "could not complete the shift change"}

        if not isinstance(result, dict):
            return {"handoff": "could not complete the shift change"}
        if result.get("status") != "assigned":
            return {"handoff": "could not complete the shift change"}
        if result.get("day") != dayPick or result.get("person") != personPick:
            return {"handoff": "could not complete the shift change"}

        return {
            "action": "assign_shift",
            "arguments": {"day": dayPick, "person": personPick},
            "reply": "Done."
        }

    if kind != "publish":
        return {"handoff": "could not classify the request"}

    try:
        team = kit.read("team")
    except Exception:
        return {"handoff": "could not read team"}

    if not isinstance(team, dict):
        return {"handoff": "could not read team"}

    peopleMap = team.get("people")
    if not isinstance(peopleMap, dict) or len(peopleMap) == 0:
        return {"handoff": "could not read team"}

    try:
        leave = kit.read("leave")
    except Exception:
        return {"handoff": "could not read leave"}

    if not isinstance(leave, dict):
        return {"handoff": "could not read leave"}

    people = sorted(list(peopleMap.keys()))
    peopleLower = []
    nameLookup = {}
    for person in people:
        lower = person.lower()
        peopleLower.append(lower)
        nameLookup[lower] = person

    requestLower = request.lower()
    parsed = parsePublishConstraints(requestLower, peopleLower, nameLookup)
    if parsed["fixedConflict"]:
        return {"handoff": "could not satisfy the rota constraints"}

    fixedDay = parsed["fixedDay"]
    forbid = parsed["forbid"]
    need = parsed["need"]
    maxone = parsed["maxone"]
    noc = parsed["noc"]
    beforePairs = parsed["beforePairs"]

    leaveByDay = {}
    for day in DAY_NAMES:
        leaveByDay[day] = set()

    for person in leave:
        awayDays = leave.get(person)
        if not isinstance(awayDays, list):
            continue
        for day in awayDays:
            if not isinstance(day, str):
                continue
            canonicalDay = normalizeDay(day.lower())
            if canonicalDay is not None:
                leaveByDay[canonicalDay].add(person)

    domains = {}
    for day in DAY_NAMES:
        try:
            available = await kit.procedure("available_people", day=day)
        except Exception:
            return {"handoff": "could not read availability"}

        if not isinstance(available, dict):
            return {"handoff": "could not read availability"}

        allowed = available.get("people")
        if not isinstance(allowed, list):
            return {"handoff": "could not read availability"}

        domain = []
        for person in people:
            if person in allowed and person not in leaveByDay.get(day, set()):
                domain.append(person)

        if len(domain) == 0:
            return {"handoff": "could not satisfy the rota constraints"}

        forced = fixedDay.get(day)
        if forced is not None and forced not in domain:
            return {"handoff": "could not satisfy the rota constraints"}

        domains[day] = domain

    plan = []
    counts = {}
    firstSeen = {}
    found = [None]

    def search(index):
        if found[0] is not None:
            return
        if index == len(DAY_NAMES):
            for person in need:
                if counts.get(person, 0) < 1:
                    return
            found[0] = list(plan)
            return

        day = DAY_NAMES[index]
        forced = fixedDay.get(day)
        if forced is not None:
            candidates = [forced]
        else:
            candidates = domains.get(day, [])

        for person in candidates:
            if person in forbid and day in forbid[person]:
                continue
            count = counts.get(person, 0)
            if count >= 2:
                continue
            if person in maxone and count >= 1:
                continue
            if index > 0 and plan[index - 1] == person and person in noc:
                continue

            addedFirst = False
            previousFirst = None
            if person not in firstSeen:
                firstSeen[person] = index
                addedFirst = True
            else:
                previousFirst = firstSeen.get(person)

            plan.append(person)
            counts[person] = count + 1

            if orderOk(firstSeen, beforePairs):
                search(index + 1)

            plan.pop()
            if count == 0:
                del counts[person]
            else:
                counts[person] = count

            if addedFirst:
                del firstSeen[person]
            else:
                if previousFirst is not None:
                    firstSeen[person] = previousFirst

            if found[0] is not None:
                return

    search(0)

    if found[0] is None:
        return {"handoff": "could not satisfy the rota constraints"}

    rota = {
        "monday": found[0][0],
        "tuesday": found[0][1],
        "wednesday": found[0][2],
        "thursday": found[0][3],
        "friday": found[0][4]
    }

    try:
        result = await kit.procedure(
            "publish_rota",
            monday=rota["monday"],
            tuesday=rota["tuesday"],
            wednesday=rota["wednesday"],
            thursday=rota["thursday"],
            friday=rota["friday"]
        )
    except Exception:
        return {"handoff": "could not publish the rota"}

    if not isinstance(result, dict):
        return {"handoff": "could not publish the rota"}
    if result.get("status") != "published":
        return {"handoff": "could not publish the rota"}

    return {
        "action": "publish_rota",
        "arguments": rota,
        "reply": "Published."
    }
