    def noulValue(answer):
        if not isinstance(answer, dict):
            return None
        value = answer.get("noul")
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            if value > 0.7:
                return True
            if value < 0.3:
                return False
        return None

    def choiceValue(answer, options):
