        options = availableByDay[day]
        if len(required) == 1:
            needed = required[0]
            if needed not in options:
                return None
            options = [needed]

        for person in options:
            if person in forbidByDay[day]:
                continue
            if person in leaveByPerson and day in leaveByPerson[person]:
                continue
            if counts[person] >= limits[person]:
                continue
            if index > 0 and plan[index - 1] == person and person in noConsecutive:
