            oldCount = counts[person]
            oldFirst = firstIndex[person]
            plan[index] = person
            counts[person] = oldCount + 1
            if oldCount == 0:
                firstIndex[person] = index

            result = search(index + 1)
            counts[person] = oldCount
            firstIndex[person] = oldFirst
            plan[index] = None
            if result is not None:
                return result

        return None

    result = search(0)
    if result is None:
        return {"handoff": "No rota satisfies all the stated constraints and standing rules."}

