async def decide(request, kit):
    state = {'request': request}
    questions = {
        'doing_action_now': {
            'type': 'noul',
            'instructions': 'Does the request ask right now and for real for an action this job performs? It is not if it is a question, a preview or hypothetical, a reminder for later, something the person already did, something to hold off on or undo, or anything outside this job.'
        }
    }
    try:
        answer = await kit.ask(state, questions)
        doing = answer['doing_action_now']
        if doing > 0.7:
            questions = {
                'which_memory': {
                    'type': 'choice',
                    'instructions': 'Which acting memory best fits this request?',
                    'criteria': {
                        'direct_shift_change': MEMORY_DESCRIPTIONS['direct_shift_change'],
                        'weekly_rota_plan_and_publish': MEMORY_DESCRIPTIONS['weekly_rota_plan_and_publish'],
                        'none': 'Neither acting memory fits.'
                    }
                }
            }
            answer2 = await kit.ask(state, questions)
            choice = answer2['which_memory']
            picked = choice['choice']
            probs = choice['probabilities']
            if picked in ACTING_MEMORIES and isinstance(probs, dict):
                best = probs.get(picked)
                if isinstance(best, (int, float)) and best >= 0.5:
                    return {'serve': picked}
            return {'serve': ACTION_MEMORY}
        if doing < 0.3:
            return {'serve': ACTION_MEMORY}
        return {'serve': ACTION_MEMORY}
    except Exception:
        return {'serve': ACTION_MEMORY}"}

{"source":"DIRECT_SHIFT = 'direct_shift_change'
WEEKLY_ROTA = 'weekly_rota_plan_and_publish'
READ_ONLY = 'read_only_question_or_out_of_scope'

ACTION_INSTRUCTIONS = 'Decide whether the request asks for an action of this job to be carried out now. Choose action_now only if it asks to put one named person on one named day shift, or to plan and publish the rota for the coming week. Choose not_action_now for questions about the current state, previews, hypotheticals, reminders, undo requests, instructions to wait, notes that it is already done, and anything the tools do not cover.'
ACTION_CRITERIA = {'action_now': 'The request asks for an action to be carried out now.', 'not_action_now': 'The request does not ask for an action to be carried out now.'}

DIRECT_SHIFT_DESCRIPTION = 'Requests to put one named person on one named day shift, or to move that day shift to a new person, including terse one day forms and filler around them.'
WEEKLY_ROTA_DESCRIPTION = 'Requests to plan the rota for the coming week and publish it, usually with constraints, limits, or ordering rules for the whole week.'
NONE_DESCRIPTION = 'Neither acting memory clearly fits.'

async def decide(request, kit):
    state = {'request': request}
    questions = {'kind': {'type': 'choice', 'instructions': ACTION_INSTRUCTIONS, 'criteria': ACTION_CRITERIA}}
    answer = await kit.ask(state, questions)
    kind = 'not_action_now'
    if isinstance(answer, dict) and 'kind' in answer and isinstance(answer['kind'], dict) and 'choice' in answer['kind']:
        kind = answer['kind']['choice']
    if kind != 'action_now':
        return {'serve': READ_ONLY}
    questions = {'memory': {'type': 'choice', 'instructions': 'Choose which acting memory fits the request best. direct_shift_change means requests to put one named person on one named day shift, or to move that day shift to a new person, including terse one day forms and filler around them. weekly_rota_plan_and_publish means requests to plan the rota for the coming week and publish it, usually with constraints, limits, or ordering rules for the whole week. If neither acting memory fits, choose none.', 'criteria': {DIRECT_SHIFT: DIRECT_SHIFT_DESCRIPTION, WEEKLY_ROTA: WEEKLY_ROTA_DESCRIPTION, 'none': NONE_DESCRIPTION}}}
    answer = await kit.ask(state, questions)
    memory = ''
    if isinstance(answer, dict) and 'memory' in answer and isinstance(answer['memory'], dict) and 'choice' in answer['memory']:
        memory = answer['memory']['choice']
    if memory == DIRECT_SHIFT or memory == WEEKLY_ROTA:
        return {'serve': memory}
    probs = {}
    if isinstance(answer, dict) and 'memory' in answer and isinstance(answer['memory'], dict) and 'probabilities' in answer['memory']:
        probs = answer['memory']['probabilities']
    if isinstance(probs, dict):
        direct = -1.0
        weekly = -1.0
        if DIRECT_SHIFT in probs:
            direct = probs[DIRECT_SHIFT]
        if WEEKLY_ROTA in probs:
            weekly = probs[WEEKLY_ROTA]
        if weekly > direct:
            return {'serve': WEEKLY_ROTA}
    return {'serve': DIRECT_SHIFT}"}

