DIRECT_DESC = "Requests to put one named person on one named day's shift, or to move that day's shift to a new person. This includes terse forms like 'Wed: Noor', 'Mon: Omar', and phrasing with filler such as 'Leave Lena alone. Put Omar on Monday.' It does not include whole-rota planning or questions about who is on call."
WEEKLY_DESC = "Requests to plan next week's rota and publish it, usually with constraints like who must work, who must not work certain days, one-shift or two-shift limits, and ordering constraints such as one person's first shift needing to come before another's. This is the whole-week scheduling job, not a single-day change."

async def decide(request, kit):
    state = {"request": request}
    first = await kit.ask(state, {
        "action_now": {
            "type": "noul",
            "instructions": "Does the user's message ask for one of this job's actions to be carried out now, rather than asking about current state, a preview, a hypothetical, a reminder, an undo, something to hold for later, or anything the tools don't cover?"
        }
    })
    p = first["action_now"]
    if p < 0.3:
        return {"serve": READ_ONLY_NAME}
    if p > 0.7:
        action = await kit.ask(state, {
            "memory": {
                "type": "choice",
                "instructions": "Which acting memory best fits this request? Choose the likeliest option.",
                "criteria": {
                    DIRECT_NAME: DIRECT_DESC,
                    WEEKLY_NAME: WEEKLY_DESC,
                    "none": "Neither acting memory fits this request."
                }
            }
        })
        choice = action["memory"]["choice"]
        if choice == DIRECT_NAME or choice == WEEKLY_NAME:
            return {"serve": choice}
        recall = await kit.recall(request, 3)
        candidates = []
        if isinstance(recall, list):
            candidates = recall
        elif isinstance(recall, tuple):
            candidates = list(recall)
        elif isinstance(recall, dict):
            for key in ["memories", "items", "results", "choices", "names"]:
                if key in recall and isinstance(recall[key], list):
                    candidates = recall[key]
                    break
            if len(candidates) == 0:
                candidates = list(recall.values())
        else:
            candidates = [recall]
        for item in candidates:
            if item == DIRECT_NAME or item == WEEKLY_NAME:
                return {"serve": item}
        return {"serve": DIRECT_NAME}
    second = await kit.ask(state, {
        "action_now": {
            "type": "choice",
            "instructions": "Is this more likely to be a request to carry out an action now, or a read-only/out-of-scope request?",
            "criteria": {
                "action_now": "The message asks to do the job now.",
                "read_only": "The message is asking about state, a preview, a hypothetical, a reminder, an undo, or something outside the tools."
            }
        }
    })
    if second["action_now"]["choice"] == "read_only":
        return {"serve": READ_ONLY_NAME}
    action = await kit.ask(state, {
        "memory": {
            "type": "choice",
            "instructions": "Which acting memory best fits this request? Choose the likeliest option.",
            "criteria": {
                DIRECT_NAME: DIRECT_DESC,
                WEEKLY_NAME: WEEKLY_DESC,
                "none": "Neither acting memory fits this request."
            }
        }
    })
    choice = action["memory"]["choice"]
    if choice == DIRECT_NAME or choice == WEEKLY_NAME:
        return {"serve": choice}
    recall = await kit.recall(request, 3)
    candidates = []
    if isinstance(recall, list):
        candidates = recall
    elif isinstance(recall, tuple):
        candidates = list(recall)
    elif isinstance(recall, dict):
        for key in ["memories", "items", "results", "choices", "names"]:
            if key in recall and isinstance(recall[key], list):
                candidates = recall[key]
                break
        if len(candidates) == 0:
            candidates = list(recall.values())
    else:
        candidates = [recall]
    for item in candidates:
        if item == DIRECT_NAME or item == WEEKLY_NAME:
            return {"serve": item}
    return {"serve": DIRECT_NAME}
"}

