    'fri': 'Friday',
}
DAY_PATTERNS = (
    r'\b(?:Monday|Tuesday|Wednesday|Thursday|Friday|Mon|Tue|Wed|Thu|Fri)\b',
    r'\b(?:monday|tuesday|wednesday|thursday|friday|mon|tue|wed|thu|fri)\b',
)
NAME_PATTERN = r'\b[A-Z][a-z]+\b'
DAY_WORDS = ('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday')
YES_CUTOFF = 0.7
CONFIDENCE_CUTOFF = 0.7


async def decide(request, kit):
    judgment = await kit.ask(
        {'request': request},
        {
            'now': {
                'type': 'noul',
                'instructions': 'Does this request ask to assign one named person to one weekday shift now, rather than asking about the rota or requesting another kind of on-call work?',
            }
        },
    )
    if judgment.get('now', 0.0) <= YES_CUTOFF:
        return {'handoff': 'This request is not a direct shift change.', 'read_only': True}

    day_candidates = []
    seen_days = set()
    for pattern in DAY_PATTERNS:
        for token in kit.find(pattern, request):
            day = DAY_ALIASES.get(token.lower())
            if day is None:
                continue
            if day not in seen_days:
                seen_days.add(day)
                day_candidates.append(day)

    person_candidates = []
    seen_people = set()
    for token in kit.find(NAME_PATTERN, request):
        if token.lower() in DAY_ALIASES:
            continue
        if token not in seen_people:
            seen_people.add(token)
            person_candidates.append(token)

    if len(day_candidates) == 0 or len(person_candidates) == 0:
        return {'handoff': 'I could not identify both the day and the person.', 'read_only': True}

    day_options = {}
    for day in day_candidates:
        day_options[day] = day
    day_options['none'] = 'none of these fit'

    person_options = {}
    for person in person_candidates:
        person_options[person] = person
    person_options['none'] = 'none of these fit'

    judged = await kit.ask(
        {'request': request, 'day_candidates': day_candidates, 'person_candidates': person_candidates},
        {
            'day': {
                'type': 'choice',
                'instructions': 'Choose the weekday to assign. If none of the candidates fits, choose none.',
                'criteria': day_options,
            },
            'person': {
                'type': 'choice',
                'instructions': 'Choose the person to assign to that shift. If none of the candidates fits, choose none.',
                'criteria': person_options,
            },
        },
    )

    day_pick = judged.get('day', {})
    person_pick = judged.get('person', {})
    day_choice = day_pick.get('choice')
    person_choice = person_pick.get('choice')

    if day_choice not in day_options or person_choice not in person_options:
        return {'handoff': 'The requested day or person was unclear.', 'read_only': True}
    if day_choice == 'none' or person_choice == 'none':
        return {'handoff': 'The requested day or person was unclear.', 'read_only': True}
    if day_pick.get('confidence', 0.0) < CONFIDENCE_CUTOFF or person_pick.get('confidence', 0.0) < CONFIDENCE_CUTOFF:
        return {'handoff': 'The requested day or person was not clear enough to act on.', 'read_only': True}

    day = DAY_ALIASES.get(day_choice.lower())
    if day is None:
        return {'handoff': 'The requested day was unclear.', 'read_only': True}

    person = person_choice
    if len(person) == 0:
        return {'handoff': 'The requested person was unclear.', 'read_only': True}

    return {'action': 'assign_shift', 'arguments': {'day': day, 'person': person}, 'reply': 'Assigned ' + person + ' to ' + day + '.'}
"}

{"source":"DAYPATTERN = '\\b(?:Monday|Mon|Tuesday|Tue|Tues|Wednesday|Wed|Thursday|Thu|Thur|Thurs|Friday|Fri)\\b'
PERSONPATTERN = '\\b(?:Priya|Omar|Lena|Sam|Noor|Tomas)\\b'
DAYMAP = {'mon': 'Monday', 'monday': 'Monday', 'tue': 'Tuesday', 'tues': 'Tuesday', 'tuesday': 'Tuesday', 'wed': 'Wednesday', 'wednesday': 'Wednesday', 'thu': 'Thursday', 'thur': 'Thursday', 'thurs': 'Thursday', 'thursday': 'Thursday', 'fri': 'Friday', 'friday': 'Friday'}
PEOPLE = ['Priya', 'Omar', 'Lena', 'Sam', 'Noor', 'Tomas']
INTENTNO = 0.3
INTENTYES = 0.7
CHOICECONF = 0.8

async def decide(request, kit):
    try:
        intentReply = await kit.ask({'request': request}, {'intent': {'type': 'noul', 'instructions': 'Is the request asking to carry out exactly one direct shift assignment or reassignment now, rather than asking about it, planning a rota, or asking for multiple changes?'}})
    except Exception:
        return {'handoff': 'Could not judge whether the request is a direct shift change.'}
    if not isinstance(intentReply, dict) or 'intent' not in intentReply:
        return {'handoff': 'Could not judge whether the request is a direct shift change.'}
    intent = intentReply.get('intent', 0.0)
    if intent < INTENTNO:
        return {'handoff': 'This request is not a direct shift change request.', 'read_only': True}
    if intent <= INTENTYES:
        return {'handoff': 'Could not tell whether the request is a direct shift change request.'}
    dayRaw = kit.find(DAYPATTERN, request)
    personRaw = kit.find(PERSONPATTERN, request)
    dayCriteria = {}
    for item in dayRaw:
        dayCriteria[item] = item
    dayCriteria['none'] = 'no clear weekday match'
    personCriteria = {}
    for item in personRaw:
        personCriteria[item] = item
    personCriteria['none'] = 'no clear person match'
    try:
        pickReply = await kit.ask({'request': request, 'day_candidates': dayRaw, 'person_candidates': personRaw}, {'day': {'type': 'choice', 'instructions': 'Which matched weekday is the shift day to change? Pick the likeliest raw weekday mention. If none fit, choose none.', 'criteria': dayCriteria}, 'person': {'type': 'choice', 'instructions': 'Which matched team member should be assigned to the shift? Pick the likeliest raw person name. If none fit, choose none.', 'criteria': personCriteria}})
    except Exception:
        return {'handoff': 'Could not identify the day and person for the shift change.'}
    if not isinstance(pickReply, dict) or 'day' not in pickReply or 'person' not in pickReply:
        return {'handoff': 'Could not identify the day and person for the shift change.'}
    dayJudge = pickReply.get('day')
    personJudge = pickReply.get('person')
    if not isinstance(dayJudge, dict) or not isinstance(personJudge, dict):
        return {'handoff': 'Could not identify the day and person for the shift change.'}
    dayChoice = dayJudge.get('choice')
    personChoice = personJudge.get('choice')
    if dayChoice == 'none' or personChoice == 'none':
        return {'handoff': 'Could not identify a single day and person for the shift change.'}
    if dayChoice is None or personChoice is None:
        return {'handoff': 'Could not identify a single day and person for the shift change.'}
    if dayJudge.get('confidence', 0.0) < CHOICECONF or personJudge.get('confidence', 0.0) < CHOICECONF:
        return {'handoff': 'Could not identify a single day and person for the shift change.'}
    dayKey = str(dayChoice).lower()
    if dayKey not in DAYMAP:
        return {'handoff': 'Could not map the chosen weekday to a tool day.'}
    if personChoice not in PEOPLE:
        return {'handoff': 'Could not map the chosen person to a team member.'}
    day = DAYMAP[dayKey]
    return {'action': 'assign_shift', 'arguments': {'day': day, 'person': personChoice}, 'reply': 'Done. ' + personChoice + ' is on ' + day + '.'}"}

{"source":"DIRECT_SHIFT = 'direct_shift_change'
WEEKLY_ROTA = 'weekly_rota_plan_and_publish'
READ_ONLY = 'read_only_question_or_out_of_scope'
TEAM_NAMES = ['Priya', 'Omar', 'Lena', 'Sam', 'Noor', 'Tomas']
DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']
DAY_INDEX = {'Monday': 0, 'Tuesday': 1, 'Wednesday': 2, 'Thursday': 3, 'Friday': 4}
YES_LIMIT = 0.7
NO_LIMIT = 0.3

ACTION_INSTRUCTIONS = 'Does the request ask for one of this desk actions to be carried out now?'
KIND_INSTRUCTIONS = 'If the request asks for an action now, choose direct_shift_change for one named person on one named weekday, weekly_rota_plan_and_publish for planning and publishing next weeks rota, or none if it is mixed, unsupported, or not one of those jobs.'
DIRECT_SINGLE_INSTRUCTIONS = 'Does the request ask for exactly one direct shift change now, and not a removal, undo, or second change?'
DAY_CRITERIA = {'Monday': 'Monday', 'Tuesday': 'Tuesday', 'Wednesday': 'Wednesday', 'Thursday': 'Thursday', 'Friday': 'Friday', 'none': 'No single weekday can be identified.'}
PERSON_CRITERIA = {'Priya': 'Priya', 'Omar': 'Omar', 'Lena': 'Lena', 'Sam': 'Sam', 'Noor': 'Noor', 'Tomas': 'Tomas', 'none': 'No single person can be identified.'}


def get_choice(answer, name):
    if isinstance(answer, dict):
        item = answer.get(name)
        if isinstance(item, dict):
            choice = item.get('choice')
            if isinstance(choice, str):
                return choice
            probs = item.get('probabilities')
            if isinstance(probs, dict):
                best = None
                bestp = -1.0
                for option in probs:
                    p = probs.get(option)
                    if isinstance(p, float) or isinstance(p, int):
                        if p > bestp:
                            bestp = p
                            best = option
                if isinstance(best, str):
                    return best
    return None


def get_noul(answer, name):
    if isinstance(answer, dict):
        item = answer.get(name)
        if isinstance(item, dict):
            p = item.get('noul')
            if isinstance(p, float) or isinstance(p, int):
                if p > YES_LIMIT:
                    return True
                if p < NO_LIMIT:
                    return False
    return None


async def decide(request, kit):
    state = {'request': request}
    answer = await kit.ask(state, {'action': {'type': 'noul', 'instructions': ACTION_INSTRUCTIONS}})
    action = get_noul(answer, 'action')
    if action is None:
        return {'handoff': 'unclear whether the request asks for action now', 'read_only': True}
    if not action:
        return {'handoff': 'the request is not asking for an action now', 'read_only': True}

    answer = await kit.ask(state, {'kind': {'type': 'choice', 'instructions': KIND_INSTRUCTIONS, 'criteria': {DIRECT_SHIFT: 'One direct shift change.', WEEKLY_ROTA: 'Plan and publish next weeks rota.', 'none': 'Not one of those jobs.'}}})
    kind = get_choice(answer, 'kind')
    if kind is None:
        return {'handoff': 'unclear which job this request is asking for', 'read_only': True}
    if kind == 'none':
        return {'handoff': 'the request does not match the direct shift or weekly rota jobs', 'read_only': True}

    if kind == DIRECT_SHIFT:
        answer = await kit.ask(state, {'single': {'type': 'noul', 'instructions': DIRECT_SINGLE_INSTRUCTIONS}})
        single = get_noul(answer, 'single')
        if single is None or not single:
            return {'handoff': 'the request is not a single direct shift change', 'read_only': True}
        answer = await kit.ask(state, {'day': {'type': 'choice', 'instructions': 'Which weekday is being changed?', 'criteria': DAY_CRITERIA}, 'person': {'type': 'choice', 'instructions': 'Which team member should be put on that shift?', 'criteria': PERSON_CRITERIA}})
        day = get_choice(answer, 'day')
        person = get_choice(answer, 'person')
        if day not in DAYS or person not in TEAM_NAMES:
            return {'handoff': 'could not identify the day and person for the shift change', 'read_only': True}
        return {'action': 'assign_shift', 'arguments': {'day': day, 'person': person}, 'reply': 'Done, ' + person + ' is on ' + day + '.'}

    team = kit.read('read_team')
    leave = kit.read('read_leave')
    rota = kit.read('read_rota')
    people_data = {}
    if isinstance(team, dict):
        people_data = team.get('people', {})
    if not isinstance(people_data, dict):
        return {'handoff': 'could not read the team roster', 'read_only': True}
    people = sorted(list(people_data.keys()))
    if len(people) == 0:
        return {'handoff': 'could not read the team roster', 'read_only': True}

    questions = {}
    for person in people:
        questions['need_' + person] = {'type': 'noul', 'instructions': 'In the request, does ' + person + ' need a shift this week?'}
        questions['max1_' + person] = {'type': 'noul', 'instructions': 'In the request, is ' + person + ' limited to one shift at most?'}
        questions['row_' + person] = {'type': 'noul', 'instructions': 'In the request, does it say ' + person + ' should not work two days in a row?'}
    for day in DAYS:
        for person in people:
            questions['must_' + person + '_' + day] = {'type': 'noul', 'instructions': 'In the request, does ' + person + ' have to take ' + day + '?'}
            questions['cant_' + person + '_' + day] = {'type': 'noul', 'instructions': 'In the request, can ' + person + ' not do ' + day + '?'}
    for a in people:
        for b in people:
            if a != b:
                questions['before_' + a + '_' + b] = {'type': 'noul', 'instructions': 'In the request, does ' + a + ' need a first shift before ' + b + '?'}

    answer = await kit.ask({'request': request, 'people': people, 'days': DAYS}, questions)

    need = set()
    max1 = set()
    no_consec = set()
    fixed = {}
    cant = {}
    order_pairs = []

    for person in people:
        cant[person] = set()
        if get_noul(answer, 'need_' + person):
            need.add(person)
        if get_noul(answer, 'max1_' + person):
            max1.add(person)
        if get_noul(answer, 'row_' + person):
            no_consec.add(person)
    for day in DAYS:
        for person in people:
            if get_noul(answer, 'must_' + person + '_' + day):
                if day in fixed and fixed[day] != person:
                    return {'handoff': 'the request requires more than one person on ' + day}
                fixed[day] = person
            if get_noul(answer, 'cant_' + person + '_' + day):
                cant[person].add(day)
    for a in people:
        for b in people:
            if a != b and get_noul(answer, 'before_' + a + '_' + b):
                order_pairs.append((a, b))

    leave_days = {}
    if isinstance(leave, dict):
        leave_days = leave.get('leave', {})
    if not isinstance(leave_days, dict):
        leave_days = {}

    for day in fixed:
        person = fixed[day]
        if person in leave_days:
            if day in leave_days.get(person, []):
                return {'handoff': 'the request conflicts with leave or day limits'}
        if person in cant and day in cant[person]:
            return {'handoff': 'the request conflicts with leave or day limits'}

    counts = {}
    first = {}
    for person in people:
        counts[person] = 0
        first[person] = None

    def can_place(day_index, person, assignment):
        day = DAYS[day_index]
        if person in leave_days:
            if day in leave_days.get(person, []):
                return False
        if day in cant.get(person, set()):
            return False
        if counts[person] >= 2:
            return False
        if person in max1 and counts[person] >= 1:
            return False
        if person in no_consec and day_index > 0:
            prev = assignment.get(DAYS[day_index - 1])
            if prev == person:
                return False
        for a, b in order_pairs:
            if person == a:
                fb = first.get(b)
                if fb is not None and fb < day_index:
                    return False
            elif person == b:
                fa = first.get(a)
                if fa is None or fa >= day_index:
                    return False
        return True

    def score_person(day_index, person):
        score = 0
        if fixed.get(DAYS[day_index]) == person:
            score += 1000
        if counts[person] == 0 and person in need:
            score += 100
        if counts[person] == 0 and person in max1:
            score += 50
        if counts[person] == 0:
            score += 10
        score -= counts[person]
        return score

    def search(day_index, assignment):
        if day_index >= len(DAYS):
            for person in need:
                if counts.get(person, 0) == 0:
                    return None
            return dict(assignment)
        day = DAYS[day_index]
        forced = fixed.get(day)
        if forced is not None:
            candidates = [forced]
        else:
            candidates = []
            for person in people:
                candidates.append((0 - score_person(day_index, person), person))
            candidates = sorted(candidates)
            ordered = []
            for item in candidates:
                ordered.append(item[1])
            candidates = ordered
        for person in candidates:
            if not can_place(day_index, person, assignment):
                continue
            assignment[day] = person
            old_first = first[person]
            if old_first is None:
                first[person] = day_index
            counts[person] += 1
            result = search(day_index + 1, assignment)
            if result is not None:
                return result
            counts[person] -= 1
            first[person] = old_first
            assignment.pop(day, None)
        return None

    rota_plan = search(0, {})
    if rota_plan is None:
        return {'handoff': 'no valid rota fits the request'}

    publish_args = {}
    for day in DAYS:
        publish_args[day.lower()] = rota_plan[day]
    return {'action': 'publish_rota', 'arguments': publish_args, 'reply': 'Published the rota.'}"}

