DAY_ALIASES = {'mon': 'Monday', 'monday': 'Monday', 'tue': 'Tuesday', 'tues': 'Tuesday', 'tuesday': 'Tuesday', 'wed': 'Wednesday', 'weds': 'Wednesday', 'wednesday': 'Wednesday', 'thu': 'Thursday', 'thur': 'Thursday', 'thurs': 'Thursday', 'thursday': 'Thursday', 'fri': 'Friday', 'friday': 'Friday'}
PERSON_ALIASES = {'priya': 'Priya', 'omar': 'Omar', 'lena': 'Lena', 'sam': 'Sam', 'noor': 'Noor', 'tomas': 'Tomas'}

ACTION_INSTRUCTIONS = 'Does the request ask for one of this desk actions to be carried out now?'
KIND_INSTRUCTIONS = 'If the request asks for an action now, choose direct_shift_change for one named person on one named weekday, weekly_rota_plan_and_publish for planning and publishing next weeks rota, or none if it is mixed, unsupported, or not one of those jobs.'

def get_choice(answer, name):
    if isinstance(answer, dict):
        item = answer.get(name)
        if isinstance(item, dict):
            choice = item.get('choice')
            if isinstance(choice, str):
                return choice
            probs = item.get('probabilities')
            if isinstance(probs, dict):
                best = None
                bestp = -1.0
                for option in probs:
                    p = probs.get(option)
                    if isinstance(p, float) or isinstance(p, int):
                        if p > bestp:
                            bestp = p
                            best = option
                if isinstance(best, str):
                    return best
    return None


def get_noul(answer, name):
    if isinstance(answer, dict):
        item = answer.get(name)
        if isinstance(item, dict):
            p = item.get('noul')
            if isinstance(p, float) or isinstance(p, int):
                if p > YES_LIMIT:
                    return True
                if p < NO_LIMIT:
                    return False
    return None


def find_options(request, kit, pattern, mapping):
    found = kit.find(pattern, request.lower())
    options = []
    seen = set()
    for item in found:
        canon = mapping.get(item, item)
        if canon not in seen:
            seen.add(canon)
            options.append(canon)
    return options


async def pick_value(request, kit, pattern, mapping, label):
    options = find_options(request, kit, pattern, mapping)
    if len(options) == 0:
        return None
    criteria = {}
    for option in options:
        criteria[option] = option
    criteria['none'] = 'No single ' + label + ' fits.'
    answer = await kit.ask({'request': request, 'options': options}, {'pick': {'type': 'choice', 'instructions': 'Pick the ' + label + ' named in the request from the candidates.', 'criteria': criteria}})
    choice = get_choice(answer, 'pick')
    if choice is None or choice == 'none':
        return None
    if choice not in options:
        return None
    return choice


async def decide(request, kit):
    state = {'request': request}
    answer = await kit.ask(state, {'action': {'type': 'noul', 'instructions': ACTION_INSTRUCTIONS}})
    action = get_noul(answer, 'action')
    if action is False:
        return {'handoff': 'the request is not asking for an action now', 'read_only': True}

    answer = await kit.ask(state, {'kind': {'type': 'choice', 'instructions': KIND_INSTRUCTIONS, 'criteria': {DIRECT_SHIFT: 'One direct shift change.', WEEKLY_ROTA: 'Plan and publish next weeks rota.', 'none': 'Not one of those jobs.'}}})
    kind = get_choice(answer, 'kind')
    if kind is None:
