{"source":"ACTINGNAMES = ('direct_shift_change', 'weekly_rota_plan_and_publish')
MEMORYDESCRIPTIONS = {
    'direct_shift_change': 'Requests to put one named person on one named day shift, or to move that day shift to a new person. This includes terse forms like Wed: Noor and Mon: Omar, and phrasing with filler such as Leave Lena alone. Put Omar on Monday. It does not include whole-rota planning or questions about who is on call.',
    'weekly_rota_plan_and_publish': 'Requests to plan next week rota and publish it, usually with constraints like who must work, who must not work certain days, one-shift or two-shift limits, and ordering constraints such as the first shift of one person needing to come before another. This is the whole-week scheduling job, not a single-day change.',
    'read_only_question_or_out_of_scope': 'Questions about the current rota, whether something was already changed, hypothetical previews like what would next week look like if..., reminders, managers, pager numbers, or anything else outside assigning one shift or publishing next week rota.'
}
READONLYMEMORY = 'read_only_question_or_out_of_scope'

def pickRecall(recalled):
    if isinstance(recalled, str):
        if recalled in ACTINGNAMES:
            return recalled
        return ACTINGNAMES[0]
    if isinstance(recalled, list) or isinstance(recalled, tuple):
        for item in recalled:
            if item in ACTINGNAMES:
                return item
        if len(recalled) > 0 and recalled[0] in ACTINGNAMES:
            return recalled[0]
        return ACTINGNAMES[0]
    if isinstance(recalled, dict):
        for item in recalled.values():
            if item in ACTINGNAMES:
                return item
        return ACTINGNAMES[0]
    return ACTINGNAMES[0]

async def routeMemory(request, kit):
    choiceResult = await kit.ask({'request': request}, {'memory': {'type': 'choice', 'instructions': 'Choose the acting memory that best fits the request. direct_shift_change handles one named person on one named day shift, or moving that shift to a new person. weekly_rota_plan_and_publish handles planning and publishing the whole next week rota under constraints.', 'criteria': {'direct_shift_change': MEMORYDESCRIPTIONS['direct_shift_change'], 'weekly_rota_plan_and_publish': MEMORYDESCRIPTIONS['weekly_rota_plan_and_publish']}}})
    answer = choiceResult['memory']['choice']
    if answer in ACTINGNAMES:
        return {'serve': answer}
    recalled = await kit.recall(request, 3)
    return {'serve': pickRecall(recalled)}

async def decide(request, kit):
    firstResult = await kit.ask({'request': request}, {'judgment': {'type': 'noul', 'instructions': 'Does the request ask for an action of this job to be carried out now, rather than a question, preview, hypothetical, reminder, undo, deferral, note that it is already done, or anything the tools do not cover?'}})
    firstAnswer = firstResult['judgment']['noul']
    if firstAnswer > 0.7:
        return await routeMemory(request, kit)
    if firstAnswer < 0.2:
        return {'serve': READONLYMEMORY}
    secondResult = await kit.ask({'request': request}, {'followup': {'type': 'noul', 'instructions': 'Is this a bare or terse instruction that names what to assign or change, with no question, no negation, no deferral, no undo, and no preview? Very short requests with no verb that pair an item with a target count as such an instruction.'}})
    secondAnswer = secondResult['followup']['noul']
    if secondAnswer > 0.6:
        return await routeMemory(request, kit)
    return {'serve': READONLYMEMORY}"}

{"source":"DIRECT_SHIFT = 'direct_shift_change'
