        day = await pick_value(request, kit, DAY_PATTERN, DAY_ALIASES, 'weekday')
        person = await pick_value(request, kit, PERSON_PATTERN, PERSON_ALIASES, 'team member')
        if day is None or person is None:
            return {'handoff': 'could not identify the day and person for the shift change'}
        available = await kit.procedure('available_people', day=day)
        people = []
        if isinstance(available, dict):
            people = available.get('people', [])
        if not isinstance(people, list) or person not in people:
            return {'handoff': 'the chosen person is not available for that day'}
        return {'action': 'assign_shift', 'arguments': {'day': day, 'person': person}, 'reply': 'Done, ' + person + ' is on ' + day + '.'}

    team = kit.read('read_team')
    leave = kit.read('read_leave')
    rota = kit.read('read_rota')
    people_data = {}
    if isinstance(team, dict):
        people_data = team.get('people', {})
