    questions = {'count': {'type': 'score', 'instructions': 'How many distinct rota rules does the request state in total? Count each separate requirement about needing a shift, being limited to one shift, not working two days in a row, taking or not taking a specific day, and one person needing the first shift before another person.', 'criteria': countLevels}}

    dayCriteria = {}
    for day in days:
        dayCriteria[day] = day
    dayCriteria['none'] = 'none'

    for name in names:
        questions['need_' + name] = {'type': 'noul', 'instructions': 'Does the request say ' + name + ' needs a shift this week?'}
        questions['max1_' + name] = {'type': 'noul', 'instructions': 'Does the request limit ' + name + ' to one shift at most?'}
        questions['row_' + name] = {'type': 'noul', 'instructions': 'Does the request say ' + name + ' should not work two days in a row?'}
        questions['must_' + name] = {'type': 'choice', 'instructions': 'If the request says ' + name + ' has to take one specific day, which day is it? Choose one of the days mentioned in the request, or none.', 'criteria': dayCriteria}
        for day in days:
            questions['cant_' + name + '_' + day] = {'type': 'noul', 'instructions': 'Does the request say ' + name + ' cannot do ' + day + '?'}

    for i in range(len(names)):
        for j in range(len(names)):
            if i != j:
                a = names[i]
                b = names[j]
                questions['before_' + a + '_' + b] = {'type': 'noul', 'instructions': 'Does the request say the first shift for ' + a + ' must come before the first shift for ' + b + '?'}

    answers = await kit.ask({'request': request}, questions)
    countAnswer = answers['count']['score']
    if answers['count']['confidence'] < 0.5:
        return {'handoff': 'unclear total rule count'}

    need = set()
    maxOne = set()
    noRow = set()
    mustDay = {}
    forbid = {}
    beforePairs = []
    extracted = 0

    for name in names:
        needAnswer = answers['need_' + name]['noul']
        if needAnswer > 0.7:
            need.add(name)
            extracted += 1
        elif needAnswer < 0.3:
            pass
        else:
            return {'handoff': 'unclear whether ' + name + ' needs a shift'}

        maxAnswer = answers['max1_' + name]['noul']
