            firstB = firsts[b]
            if firstB is not None:
                if firstA is None:
                    return False
                if firstA >= firstB:
                    return False
        return True

    def solve(index, rotaMap, counts, firsts):
        if index == len(DAYS):
            for person in need:
                if counts.get(person, 0) < 1:
                    return None
            for person in maxOne:
                if counts.get(person, 0) > 1:
                    return None
            for a, b in beforePairs:
                if firsts[a] is None or firsts[b] is None:
                    return None
                if firsts[a] >= firsts[b]:
                    return None
            return rotaMap

        day = DAYS[index]
        if day in dayMustPerson:
            candidates = [dayMustPerson[day]]
        else:
            candidates = available[day]

        previous = None
        if index > 0:
            previous = rotaMap[DAYS[index - 1]]

        for person in candidates:
            if person not in peopleSet:
