        questions['need_' + person] = {'type': 'noul', 'instructions': 'Does the request say ' + person + ' needs a shift this week?'}
        questions['max1_' + person] = {'type': 'noul', 'instructions': 'Does the request say ' + person + ' should have one shift at most?'}
        questions['row_' + person] = {'type': 'noul', 'instructions': 'Does the request say ' + person + ' should not work two days in a row?'}
        questions['must_' + person] = {'type': 'choice', 'instructions': 'If the request says ' + person + ' has to take one specific day, which day is it? Choose one of the days or none.', 'criteria': dayChoices}
        for day in DAYS:
            questions['cant_' + person + '_' + day] = {'type': 'noul', 'instructions': 'Does the request say ' + person + ' cannot do ' + day + '?'}

    for i in range(len(people)):
        for j in range(len(people)):
            if i != j:
                a = people[i]
                b = people[j]
                questions['before_' + a + '_' + b] = {'type': 'noul', 'instructions': 'Does the request say ' + a + ' first shift has to come before ' + b + ' first shift?'}

    answers = await kit.ask({'request': request}, questions)

    countAnswer = answers['count']['score']
    need = set()
    maxOne = set()
    noRow = set()
    mustDay = {}
    forbid = {}
    beforePairs = []
    extracted = 0

    for person in people:
        needAnswer = answers['need_' + person]['noul']
        if needAnswer > 0.7:
            need.add(person)
            extracted += 1
        elif needAnswer < 0.3:
            pass
        else:
            return {'handoff': 'unclear whether ' + person + ' needs a shift'}

        maxAnswer = answers['max1_' + person]['noul']
        if maxAnswer > 0.7:
            maxOne.add(person)
            extracted += 1
        elif maxAnswer < 0.3:
            pass
        else:
            return {'handoff': 'unclear whether ' + person + ' is limited to one shift'}

        rowAnswer = answers['row_' + person]['noul']
        if rowAnswer > 0.7:
            noRow.add(person)
            extracted += 1
        elif rowAnswer < 0.3:
            pass
        else:
            return {'handoff': 'unclear whether ' + person + ' should avoid consecutive shifts'}

        dayAnswer = answers['must_' + person]['choice']
        if dayAnswer == 'none':
            pass
        elif dayAnswer in DAYS:
            mustDay[person] = dayAnswer
            extracted += 1
        else:
            return {'handoff': 'fixed day choice is not usable'}

        forbid[person] = set()
        for day in DAYS:
            key = 'cant_' + person + '_' + day
            answer = answers[key]['noul']
            if answer > 0.7:
                forbid[person].add(day)
                extracted += 1
            elif answer < 0.3:
                pass
            else:
                return {'handoff': 'unclear whether ' + person + ' cannot do ' + day}

    for i in range(len(people)):
        for j in range(len(people)):
            if i != j:
                a = people[i]
                b = people[j]
                key = 'before_' + a + '_' + b
                answer = answers[key]['noul']
                if answer > 0.7:
                    beforePairs.append((a, b))
                    extracted += 1
                elif answer < 0.3:
                    pass
                else:
                    return {'handoff': 'unclear ordering between ' + a + ' and ' + b}

    if abs(countAnswer - extracted) > 0.5:
        return {'handoff': 'the extracted rules do not match the request'}

    peopleSet = set(people)
    leaveDays = {}
    for person in people:
        leaveDays[person] = set(leave['leave'].get(person, []))

    available = {}
    for day in DAYS:
        result = await kit.procedure('available_people', day=day)
        items = result['people']
        current = []
        for person in items:
            if person in peopleSet:
                current.append(person)
        available[day] = current

    dayMustPerson = {}
    for person in mustDay:
        day = mustDay[person]
        if day in dayMustPerson and dayMustPerson[day] != person:
            return {'handoff': 'conflicting fixed-day requirements'}
        dayMustPerson[day] = person
        if day in leaveDays[person]:
            return {'handoff': 'a fixed day is on leave'}
        if person not in available[day]:
            return {'handoff': 'a fixed day is impossible with availability'}

    for a, b in beforePairs:
        if a in mustDay and b in mustDay:
            if DAYORDER[mustDay[a]] >= DAYORDER[mustDay[b]]:
                return {'handoff': 'ordering constraints conflict with fixed days'}

    limits = {}
    for person in people:
        limits[person] = 2
    for person in maxOne:
        limits[person] = 1

    dayCandidates = {}
    for day in DAYS:
        if day in dayMustPerson:
            dayCandidates[day] = [dayMustPerson[day]]
        else:
            cands = []
            for person in available[day]:
                if person not in peopleSet:
                    continue
                if day in leaveDays[person]:
                    continue
                if day in forbid[person]:
                    continue
                cands.append(person)
            dayCandidates[day] = cands
            if len(cands) == 0:
                return {'handoff': 'no one is available for ' + day}

    def okPartial(firsts):
        for a, b in beforePairs:
            fb = firsts[b]
            fa = firsts[a]
            if fb is not None:
                if fa is None:
                    return False
                if fa >= fb:
                    return False
        return True

    def solve(index, rotaMap, counts, firsts):
        if index == len(DAYS):
            for person in need:
                if counts.get(person, 0) < 1:
                    return None
            for person in maxOne:
                if counts.get(person, 0) > 1:
                    return None
            for a, b in beforePairs:
                fa = firsts[a]
                fb = firsts[b]
                if fa is None or fb is None or fa >= fb:
                    return None
            return rotaMap

        day = DAYS[index]
        candidates = dayCandidates[day]
        prevPerson = None
        if index > 0:
            prevPerson = rotaMap[DAYS[index - 1]]

        for person in candidates:
            if counts.get(person, 0) >= limits[person]:
                continue
            if person in noRow and prevPerson == person:
                continue

            nextCounts = dict(counts)
            nextCounts[person] = nextCounts.get(person, 0) + 1
            nextFirsts = dict(firsts)
            if nextFirsts[person] is None:
                nextFirsts[person] = index
            if not okPartial(nextFirsts):
                continue

            nextRota = dict(rotaMap)
            nextRota[day] = person
            result = solve(index + 1, nextRota, nextCounts, nextFirsts)
            if result is not None:
                return result

        return None

    startCounts = {}
    startFirsts = {}
    for person in people:
        startCounts[person] = 0
        startFirsts[person] = None

    solved = solve(0, {}, startCounts, startFirsts)
    if solved is None:
        return {'handoff': 'no rota satisfies the request'}

    return {'action': 'publish_rota', 'arguments': {'monday': solved['Monday'], 'tuesday': solved['Tuesday'], 'wednesday': solved['Wednesday'], 'thursday': solved['Thursday'], 'friday': solved['Friday']}, 'reply': 'Published the rota.'}"}

"""Kinds learned from the runs. A router written from the contract asks Jev which kind a request is, and sends any
request that should not be acted on to a read-only hand-off. Each acting kind served by the language model gets the
lowest reasoning level that stays right. The acting kind the model serves most is moved to a decision program, which
is kept only if it makes no wrong action on the shared requests.
"""

KINDS_PROMPT = """{contract}

Below are runs where the assistant, a language model, handled requests for
this job: each request, every tool call with its result, and the verdict.
Some requests are worded oddly, some should not be acted on at all, and
some runs went wrong.

List the kinds of request these runs show, and for each write what the
assistant should know the next time it meets one: how ids are really
written in the tools, which tools to call and in what order, and the
mistakes to avoid. Use as few kinds as cover the runs.

Reply with only a JSON list. Each item has the keys "name" (short, in
snake_case), "description" (which requests belong to this kind, and which
similar ones don't), "guidance" (what the assistant should know), and
"acts" (true if a request of this kind should end in an action, false if
it should only be answered or passed on).

{episodes}"""

RULES = """Rules for the program's source:
- It defines exactly `async def decide(request, kit)` and follows the contract above for every call it makes and every value it returns.
- No imports, no names starting with an underscore, no bare `except`, no str.format, no f-strings.
- The only builtins it may use are Exception, KeyError, TypeError, ValueError, abs, all, any, bool, dict, divmod, enumerate, filter, float, int, isinstance, len, list, map, max, min, range, reversed, round, set, sorted, str, sum, tuple, zip.
- Whatever it decides about what the request asks for, it decides by asking Jev (as the contract describes), never by looking for words or patterns in the request text. Requests will be worded in ways not seen here.
- Code is only for what code can know exactly: calling tools, matching ids that tools return, checking constraints."""

ROUTER_PROMPT = """{contract}

{rules}

Write the routing program for this job. For each request it must pick one
of the memories below and return {"serve": name}, or hand off itself as the
contract says. Ask Jev for a typed judgment: first, whether the request
really asks for an action to be carried out now that one of the acting
memories covers. Requests that only ask a question, ask for a preview,
want something undone or removed, want a reminder or message, say nothing
is needed, say not to do something yet, or ask for anything the tools
cannot do, should not be acted on: send them to a read-only memory, or
hand off read-only as the contract says. Only when Jev judges the request
an action of one acting memory, serve that memory. When in doubt, do not
act.

Memories:
{memories}

Shared requests, labeled with whether they should be acted on:
{tests}

{feedback}

Reply with only a JSON object {"source": "<the program's full source>"}."""

PROGRAM_PROMPT = """{contract}

{rules}

Write a decision program that fully serves requests of this kind without a
language model, calling the tools and asking Jev as the contract says:

Kind: {name}
Which requests: {description}
What to know: {guidance}

The router only sends requests here that it judged to be this kind, but it
can be wrong. First ask Jev to extract what the request asks for, as typed
fields (for example who and which day), and whether it really asks for
this action now. If it does not, or any field is missing or doesn't match
an id the tools report, hand off read-only (or hand off) as the contract
says rather than act. A wrong action costs far more than a hand-off. Look
up real ids with the tools before acting.

Runs the language model did for this job:
{episodes}

Shared requests routed to this kind, labeled:
{tests}

{feedback}

Reply with only a JSON object {"source": "<the program's full source>"}."""

ROUTER = """async def decide(request, kit):
    found = await kit.recall(request, k=1)
    if len(found) == 0:
        return {"handoff": "nothing learned applies"}
    return {"serve": found[0]["name"]}
"""

LEVELS = ["none", "low", "medium", "high"]


async def write_program(lab, prompt):
    reply = await lab.ask(prompt)
    try:
        value = lab.parse(reply)
    except Exception:
        return None
    if isinstance(value, dict):
        source = value.get("source")
        if isinstance(source, str) and "async def decide" in source:
            return source
    return None


async def trial(lab, source, ids):
    results = []
    for tid in ids:
        try:
            outcome = await lab.practice(source, tid)
            reward = outcome[0]
            reason = outcome[1]
            served = outcome[2]
        except Exception as error:
            reward = 0
            reason = "error: " + str(error)
            served = None
        results.append({"id": tid, "reward": reward, "reason": str(reason), "served": served})
    return results


def total(results):
    return sum(r["reward"] for r in results)


def describe_failures(lab, results, labels):
    lines = []
    for r in results:
        if r["reward"] < 1:
            act = labels.get(r["id"])
            tag = "should act" if act else "should not act"
            if act is None:
                tag = "unlabeled"
            lines.append("- " + tag + ": " + str(lab.request(r["id"])) + " -> reward " + str(r["reward"]) + ", served by " + str(r["served"]) + ": " + r["reason"])
    if len(lines) == 0:
        return ""
    return "Your previous attempt fell short on these requests; fix it:\n" + "\n".join(lines[:25])


def show_tests(lab, ids, labels):
    lines = []
    for tid in ids:
        act = labels.get(tid)
        tag = "unlabeled"
        if act is True:
            tag = "should act"
        if act is False:
            tag = "should not act"
        lines.append("- [" + tag + "] " + str(lab.request(tid)))
    if len(lines) == 0:
        return "(none)"
    return "\n".join(lines)


def store(lab, memory):
    lab.remember(memory["name"], memory["description"], memory["body"], route=memory["route"], read_only=memory["read_only"])


async def learn(lab):
    memories = []
    if len(lab.memories) > 0:
        for m in lab.memories:
            memories.append({"name": m["name"], "description": m["description"], "body": m["body"],
                             "route": m.get("route", "none"), "read_only": bool(m.get("read_only", False))})
    else:
        shown = "\n\n".join(lab.render(e) for e in lab.episodes)
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
        for kind in lab.parse(reply):
            memories.append({"name": kind["name"], "description": kind["description"], "body": kind["guidance"],
                             "route": "none", "read_only": not kind["acts"]})
    for m in memories:
        store(lab, m)

    labels = {}
    ids = []
    for t in lab.tests:
        labels[t["id"]] = t["should_act"]
        ids.append(t["id"])
    if len(ids) == 0:
        ids = list(lab.stream())[:30]

    listing = "\n".join("- " + m["name"] + (" (read-only, never acts)" if m["read_only"] else " (acts)") + ": " + m["description"] for m in memories)
    tests_text = show_tests(lab, ids, labels)

    # Router: written from the contract, compared with nearest-memory recall.
    router = ROUTER
    best = await trial(lab, ROUTER, ids)
    feedback = ""
    for attempt in range(2):
        source = await write_program(lab, lab.fill(ROUTER_PROMPT, contract=lab.contract, rules=RULES,
                                                   memories=listing, tests=tests_text, feedback=feedback))
        if source is None:
            continue
        results = await trial(lab, source, ids)
        if total(results) > total(best):
            router = source
            best = results
        feedback = describe_failures(lab, results, labels)
        if feedback == "":
            break

    def served_ids(results, name):
        return [r["id"] for r in results if r["served"] == name]

    # Lowest reasoning level that stays right for each acting LLM memory.
    for m in memories:
        if m["read_only"] or m["route"] == "program":
            continue
        mine = [tid for tid in served_ids(best, m["name"]) if labels.get(tid, True)]
        if len(mine) == 0:
            continue
        chosen = None
        for level in LEVELS:
            m["route"] = level
            store(lab, m)
            results = await trial(lab, router, mine)
            if all(r["reward"] >= 0.6 for r in results):
                chosen = level
                break
        if chosen is None:
            chosen = "high"
        m["route"] = chosen
        store(lab, m)
    best = await trial(lab, router, ids)

    # Move the acting memory the model serves most to a decision program.
    target = None
    count = 0
    for m in memories:
        if m["read_only"] or m["route"] == "program":
            continue
        n = len([r for r in best if r["served"] == m["name"] and r["reward"] >= 0.6])
        if n > count:
            count = n
            target = m
    if target is not None:
        mine = served_ids(best, target["name"])
        before = [r for r in best if r["id"] in mine]
        level = target["route"]
        episodes = "\n\n".join(lab.render(e) for e in lab.episodes)
        feedback = ""
        kept = False
        for attempt in range(3):
            source = await write_program(lab, lab.fill(PROGRAM_PROMPT, contract=lab.contract, rules=RULES,
                                                       name=target["name"], description=target["description"],
                                                       guidance=target["body"], episodes=episodes,
                                                       tests=show_tests(lab, mine, labels), feedback=feedback))
            if source is None:
                continue
            target["body"] = target["body"] if False else source
            target["route"] = "program"
            target["read_only"] = False
            store(lab, target)
            results = await trial(lab, router, mine)
            if all(r["reward"] > 0 for r in results) and total(results) >= total(before):
                kept = True
                break
            feedback = describe_failures(lab, results, labels)
        if not kept:
            for m in lab.memories:
                pass
            original = None
            for m in memories:
                if m["name"] == target["name"]:
                    original = m
            restored = {"name": target["name"], "description": target["description"],
                        "body": target.get("guidance_backup", ""), "route": level, "read_only": False}
            if restored["body"] == "":
                restored["body"] = target["description"]
            store(lab, restored)
            lab.note("program for " + target["name"] + " not kept; back on the model at " + level)
        else:
            lab.note("program for " + target["name"] + " kept")
    return router

