READ_ONLY_MEMORY = "question_or_unsupported_request"

MEMORY_NAMES = ["assign_one_shift", "plan_and_publish_rota", "question_or_unsupported_request"]

MEMORY_CRITERIA = {
    "assign_one_shift": "The user asks to put one named person on one named day. This covers wordings like 'please have Omar take Wednesday', 'Please give Friday's shift to Priya' with chatty padding around it, terse forms like 'Mon: Omar', 'Wed: Noor' or 'Omar for Tue', and 'Leave Noor alone. Put Omar on Wednesday.' It does not cover removing someone from a day ('Take Noor off Wednesday'), previews ('what would it look like if..., don't change it'), or questions about whether a move already happened. Those belong to question_or_unsupported_request.",
    "plan_and_publish_rota": "The user asks to plan next week's on-call rota (Monday to Friday) and publish it under a list of constraints. The constraints may come as sentences or bullets, wrapped in openers like 'hey, need next week's rota done and published' or 'The roadmap review ran long...'. Requests that only ask what a week would look like without changing it, or that say to publish nothing, do not belong here.",
    "question_or_unsupported_request": "Anything that is not assigning one shift or planning and publishing the week. This includes questions about the rota ('Who's on call Wednesday?', 'Did you already move Noor to Wednesday?', 'Would Omar be allowed to take Tuesday?'), previews ('What would next week look like if Noor took Wednesday? Don't change it.', 'Show me a possible rota; publish nothing'), removals or undos ('Take Noor off Wednesday', 'Undo the change that put Omar on Tuesday'), things the user says are already done or must not be done yet ('I already put Omar on Tuesday myself', 'Don't put Omar on Tuesday yet'), reminders ('Remind me on Friday to give Omar Tuesday'), information the tools don't hold ('Who's the manager for Noor?', 'When does Omar's contract end?'), messaging or other actions the tools cannot do ('Send Noor a reminder', 'Order lunch', 'Reset a pager password', 'Add someone to a channel').",
}

INSTRUCTIONS = "Decide which memory the user's message in `request` belongs to. The desk can only do two things: put one named person on one day's shift, and plan and publish next week's rota under the given constraints. Any request which should not end in an action belongs to question_or_unsupported_request: questions, previews that must not change anything, undos and removals, things the user says are already done or must not be done yet, reminders, messages, and anything the tools cannot do. Judge what the user actually wants done, not the words they use."


async def decide(request, kit):
    state = {"request": request}
    questions = {
        "memory": {
            "type": "choice",
            "instructions": INSTRUCTIONS,
            "criteria": MEMORY_CRITERIA,
        }
    }
    name = READ_ONLY_MEMORY
    try:
        reply = await kit.ask(state, questions)
        answer = reply.get("memory", {})
        if isinstance(answer, dict):
            chosen = answer.get("choice")
            if isinstance(chosen, str) and chosen in MEMORY_NAMES:
                name = chosen
    except (KeyError, TypeError, ValueError):
        name = READ_ONLY_MEMORY
    return {"serve": name}
