```python
PEOPLE = ["Priya", "Omar", "Lena", "Sam", "Noor", "Tomas"]
DAYS = {"mon": "Monday", "tue": "Tuesday", "wed": "Wednesday", "thu": "Thursday", "fri": "Friday"}
DAY_PATTERN = "(?i)\\b(?:mon|tue|wed|thu|fri)[a-z]*\\b"
NAME_PATTERN = "\\b[A-Z][a-z]+\\b"

PLAN_MEMORY = (
    "This is a request to plan and publish next week's on-call rota. "
    "First call read_leave(); read_team() and read_rota() are optional. "
    "Choose one person for each day, Monday to Friday. The rota must obey every constraint in the request "
    "('X has to take D', 'X can't do D', 'Give X one shift at most', "
    "'X shouldn't work two days in a row', and 'X and Y both need a shift, X's first shift before Y's'). "
    "It must also obey the standing rules: nobody takes more than two shifts, and nobody works a day they are on leave. "
    "Then call publish_rota once, with the lowercase keys monday, tuesday, wednesday, thursday and friday. "
    "There is no need to call assign_shift for each day."
)
READ_MEMORY = (
    "This request does not ask to put a person on a shift or to publish a rota. "
    "It may be a question, a preview, a removal, a reminder or an undo. "
    "Answer it from the read tools if you can (read_rota answers who is on which day), "
    "or explain that the desk cannot do it. Do not change anything."
)


def day_of(text):
    key = text.strip().lower()[:3]
    if key in DAYS:
        return DAYS[key]
    return None


async def decide(request, kit):
    day_cands = kit.find(DAY_PATTERN, request)
    name_cands = kit.find(NAME_PATTERN, request)

    questions = {
        "kind": {
            "type": "choice",
            "instructions": "What does the user ask for in `request`? Ignore chatty padding.",
            "criteria": {
                "assign": "Put exactly one named person on exactly one named day, now. Examples: 'Mon: Omar', "
                          "'please have Omar take Wednesday', 'Leave Noor alone. Put Omar on Wednesday.'",
                "plan": "Plan or build next week's whole rota under constraints, and publish it",
                "other": "Anything else: asking who is on a day, a preview that should not change anything, "
                         "taking someone off a day, asking whether a change already happened, reminders, "
                         "undoing a change, or questions about people",
                "unclear": "An assignment request that is ambiguous, names several assignments, or misses the person or the day",
            },
        }
    }
    day_opts = {}
    for c in day_cands:
        if c not in day_opts:
            day_opts[c] = "the day written as '" + c + "'"
    day_opts["none"] = "no day is named as the day to assign"
    questions["day"] = {
        "type": "choice",
        "instructions": "In `request`, which day is the user asking to put someone on?",
        "criteria": day_opts,
    }
    name_opts = {}
    for c in name_cands:
        if c not in name_opts:
            name_opts[c] = "the person named '" + c + "'"
    name_opts["none"] = "no person is named as the one to put on the shift"
    questions["person"] = {
        "type": "choice",
        "instructions": "In `request`, which person is being put on the day's shift? "
                        "This is never someone named in a 'Leave X alone' clause, and never a day name or a filler word.",
        "criteria": name_opts,
    }

    ans = await kit.ask({"request": request}, questions)
    kind = ans.get("kind", {})
    k = kind.get("choice")
    kconf = kind.get("confidence", 0.0)

    if k == "plan" and kconf >= 0.6:
        return {"handoff": "Rota planning request", "route": "medium", "memory": PLAN_MEMORY}
    if k == "other" and kconf >= 0.6:
        return {"handoff": "Not an assignment or a planning request", "read_only": True,
                "route": "low", "memory": READ_MEMORY}
    if k != "assign" or kconf < 0.75:
        return {"handoff": "Unclear what the request asks for"}

    dchoice = ans.get("day", {})
    pchoice = ans.get("person", {})
    if dchoice.get("confidence", 0.0) < 0.7 or pchoice.get("confidence", 0.0) < 0.7:
        return {"handoff": "Day or person is uncertain"}
    draw = dchoice.get("choice")
    praw = pchoice.get("choice")
    if draw is None or draw == "none" or draw not in day_cands:
        return {"handoff": "No day found"}
    if praw is None or praw == "none" or praw not in name_cands:
        return {"handoff": "No person found"}
    day = day_of(draw)
    if day is None:
        return {"handoff": "Day not recognised"}
    person = None
    for p in PEOPLE:
        if p.lower() == praw.strip().lower():
            person = p
    if person is None:
        return {"handoff": "Person not on the team"}

    avail = await kit.procedure("available_people", day=day)
    people = []
    if isinstance(avail, dict):
        people = avail.get("people", [])
    if person not in people:
        return {"handoff": person + " is not available on " + day,
                "route": "low",
                "memory": person + " is on leave or unavailable on " + day + " according to available_people. "
                          "Do not assign. Tell the user."}

    return {"action": "assign_shift",
            "arguments": {"day": day, "person": person},
            "reply": person + " is now on call for " + day + "."}
